INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES
  ('b0000001-0000-4000-a000-00000020002b', 'a0000001-0000-4000-a000-000000000014', 'multiple_choice', '「分かる」의 의미로 올바른 것은?', '分かる(わかる)는 ''알다, 이해하다''라는 뜻의 N5 동사입니다.', 1, 1, 'N5', 'vocab', true),
  ('b0000001-0000-4000-a000-00000020002c', 'a0000001-0000-4000-a000-000000000014', 'multiple_choice', '「要る」의 의미로 올바른 것은?', '要る(いる)는 ''필요하다''라는 뜻의 N5 동사입니다.', 1, 2, 'N5', 'vocab', true),
  ('b0000001-0000-4000-a000-00000020002d', 'a0000001-0000-4000-a000-000000000014', 'multiple_choice', '「押す」의 의미로 올바른 것은?', '押す(おす)는 ''누르다, 밀다''라는 뜻의 N5 동사입니다.', 1, 3, 'N5', 'vocab', true),
  ('b0000001-0000-4000-a000-00000020002e', 'a0000001-0000-4000-a000-000000000014', 'multiple_choice', '「引く」의 의미로 올바른 것은?', '引く(ひく)는 ''당기다, (사전을) 찾다''라는 뜻의 N5 동사입니다.', 1, 4, 'N5', 'vocab', true),
  ('b0000001-0000-4000-a000-00000020002f', 'a0000001-0000-4000-a000-000000000014', 'multiple_choice', '「吹く」의 의미로 올바른 것은?', '吹く(ふく)는 ''불다''라는 뜻의 N5 동사입니다.', 1, 5, 'N5', 'vocab', true),
  ('b0000001-0000-4000-a000-000000200030', 'a0000001-0000-4000-a000-000000000014', 'multiple_choice', '「降る」의 의미로 올바른 것은?', '降る(ふる)는 ''(비/눈이) 내리다''라는 뜻의 N5 동사입니다.', 1, 6, 'N5', 'vocab', true),
  ('b0000001-0000-4000-a000-000000200031', 'a0000001-0000-4000-a000-000000000014', 'multiple_choice', '「並ぶ」의 의미로 올바른 것은?', '並ぶ(ならぶ)는 ''줄 서다''라는 뜻의 N5 동사입니다.', 1, 7, 'N5', 'vocab', true),
  ('b0000001-0000-4000-a000-000000200032', 'a0000001-0000-4000-a000-000000000014', 'multiple_choice', '「置く」의 의미로 올바른 것은?', '置く(おく)는 ''놓다, 두다''라는 뜻의 N5 동사입니다.', 1, 8, 'N5', 'vocab', true),
  ('b0000001-0000-4000-a000-000000200033', 'a0000001-0000-4000-a000-000000000014', 'multiple_choice', '「売る」의 의미로 올바른 것은?', '売る(うる)는 ''팔다''라는 뜻의 N5 동사입니다.', 1, 9, 'N5', 'vocab', true),
  ('b0000001-0000-4000-a000-000000200034', 'a0000001-0000-4000-a000-000000000014', 'multiple_choice', '「払う」의 의미로 올바른 것은?', '払う(はらう)는 ''지불하다''라는 뜻의 N5 동사입니다.', 1, 10, 'N5', 'vocab', true),
