INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES
  ('b0000001-0000-4000-a000-000000200055', 'a0000001-0000-4000-a000-000000000015', 'multiple_choice', '「男」의 의미로 올바른 것은?', '男(おとこ)는 ''남자''라는 뜻의 N5 명사입니다.', 1, 1, 'N5', 'vocab', true),
