  ('b0000001-0000-4000-a000-00000020007f', 'a0000001-0000-4000-a000-000000000016', 'multiple_choice', '「辞書」의 의미로 올바른 것은?', '辞書(じしょ)는 ''사전''라는 뜻의 N5 명사입니다.', 1, 1, 'N5', 'vocab', true),
