  ('b0000001-0000-4000-a000-000000200090', 'a0000001-0000-4000-a000-000000000016', 'multiple_choice', '「猫」의 의미로 올바른 것은?', '猫(ねこ)는 ''고양이''라는 뜻의 N5 명사입니다.', 1, 18, 'N5', 'vocab', true),
