  ('b0000001-0000-4000-a000-0000002000a9', 'a0000001-0000-4000-a000-000000000017', 'multiple_choice', '「言葉」의 의미로 올바른 것은?', '言葉(ことば)는 ''말, 언어''라는 뜻의 N5 명사입니다.', 1, 1, 'N5', 'vocab', true),
