  ('b0000001-0000-4000-a000-0000002000ab', 'a0000001-0000-4000-a000-000000000017', 'multiple_choice', '「質問」의 의미로 올바른 것은?', '質問(しつもん)는 ''질문''라는 뜻의 N5 명사입니다.', 1, 3, 'N5', 'vocab', true),
