  ('b0000001-0000-4000-a000-0000002000af', 'a0000001-0000-4000-a000-000000000017', 'multiple_choice', '「試験」의 의미로 올바른 것은?', '試験(しけん)는 ''시험''라는 뜻의 N5 명사입니다.', 1, 7, 'N5', 'vocab', true),
  ('b0000001-0000-4000-a000-0000002000b0', 'a0000001-0000-4000-a000-000000000017', 'multiple_choice', '「とても」의 의미로 올바른 것은?', 'とても(とても)는 ''매우, 아주''라는 뜻의 N5 부사입니다.', 1, 8, 'N5', 'vocab', true),
  ('b0000001-0000-4000-a000-0000002000b1', 'a0000001-0000-4000-a000-000000000017', 'multiple_choice', '「もう」의 의미로 올바른 것은?', 'もう(もう)는 ''이미, 벌써''라는 뜻의 N5 부사입니다.', 1, 9, 'N5', 'vocab', true),
  ('b0000001-0000-4000-a000-0000002000b2', 'a0000001-0000-4000-a000-000000000017', 'multiple_choice', '「まだ」의 의미로 올바른 것은?', 'まだ(まだ)는 ''아직''라는 뜻의 N5 부사입니다.', 1, 10, 'N5', 'vocab', true),
