  ('b0000001-0000-4000-a000-0000002000b9', 'a0000001-0000-4000-a000-000000000017', 'multiple_choice', '「全然」의 의미로 올바른 것은?', '全然(ぜんぜん)는 ''전혀 (~않다)''라는 뜻의 N5 부사입니다.', 1, 17, 'N5', 'vocab', true),
