  ('b0000001-0000-4000-a000-0000002000c1', 'a0000001-0000-4000-a000-000000000017', 'multiple_choice', '「ゆっくり」의 의미로 올바른 것은?', 'ゆっくり(ゆっくり)는 ''천천히''라는 뜻의 N5 부사입니다.', 1, 25, 'N5', 'vocab', true),
