INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES
  ('b0000001-0000-4000-a000-0000002000fd', 'a0000001-0000-4000-a000-000000000019', 'multiple_choice', '「決まる」의 의미로 올바른 것은?', '決まる(きまる)는 ''정해지다, 결정되다''라는 뜻의 N4 동사입니다.', 1, 1, 'N4', 'vocab', true),
  ('b0000001-0000-4000-a000-0000002000fe', 'a0000001-0000-4000-a000-000000000019', 'multiple_choice', '「変わる」의 의미로 올바른 것은?', '変わる(かわる)는 ''변하다, 달라지다''라는 뜻의 N4 동사입니다.', 1, 2, 'N4', 'vocab', true),
  ('b0000001-0000-4000-a000-0000002000ff', 'a0000001-0000-4000-a000-000000000019', 'multiple_choice', '「集まる」의 의미로 올바른 것은?', '集まる(あつまる)는 ''모이다''라는 뜻의 N4 동사입니다.', 1, 3, 'N4', 'vocab', true),
  ('b0000001-0000-4000-a000-000000200100', 'a0000001-0000-4000-a000-000000000019', 'multiple_choice', '「落とす」의 의미로 올바른 것은?', '落とす(おとす)는 ''떨어뜨리다''라는 뜻의 N4 동사입니다.', 1, 4, 'N4', 'vocab', true),
  ('b0000001-0000-4000-a000-000000200101', 'a0000001-0000-4000-a000-000000000019', 'multiple_choice', '「落ちる」의 의미로 올바른 것은?', '落ちる(おちる)는 ''떨어지다''라는 뜻의 N4 동사입니다.', 1, 5, 'N4', 'vocab', true),
  ('b0000001-0000-4000-a000-000000200102', 'a0000001-0000-4000-a000-000000000019', 'multiple_choice', '「始める」의 의미로 올바른 것은?', '始める(はじめる)는 ''시작하다 (타동사)''라는 뜻의 N4 동사입니다.', 1, 6, 'N4', 'vocab', true),
  ('b0000001-0000-4000-a000-000000200103', 'a0000001-0000-4000-a000-000000000019', 'multiple_choice', '「始まる」의 의미로 올바른 것은?', '始まる(はじまる)는 ''시작되다 (자동사)''라는 뜻의 N4 동사입니다.', 1, 7, 'N4', 'vocab', true),
  ('b0000001-0000-4000-a000-000000200104', 'a0000001-0000-4000-a000-000000000019', 'multiple_choice', '「壊す」의 의미로 올바른 것은?', '壊す(こわす)는 ''부수다, 고장 내다''라는 뜻의 N4 동사입니다.', 1, 8, 'N4', 'vocab', true),
  ('b0000001-0000-4000-a000-000000200105', 'a0000001-0000-4000-a000-000000000019', 'multiple_choice', '「見つかる」의 의미로 올바른 것은?', '見つかる(みつかる)는 ''발견되다, 찾아지다''라는 뜻의 N4 동사입니다.', 1, 9, 'N4', 'vocab', true),
  ('b0000001-0000-4000-a000-000000200106', 'a0000001-0000-4000-a000-000000000019', 'multiple_choice', '「起こす」의 의미로 올바른 것은?', '起こす(おこす)는 ''깨우다, 일으키다''라는 뜻의 N4 동사입니다.', 1, 10, 'N4', 'vocab', true),
  ('b0000001-0000-4000-a000-000000200107', 'a0000001-0000-4000-a000-000000000019', 'multiple_choice', '「起きる」의 의미로 올바른 것은?', '起きる(おきる)는 ''일어나다''라는 뜻의 N4 동사입니다.', 1, 11, 'N4', 'vocab', true),
  ('b0000001-0000-4000-a000-000000200108', 'a0000001-0000-4000-a000-000000000019', 'multiple_choice', '「直す」의 의미로 올바른 것은?', '直す(なおす)는 ''고치다, 수리하다''라는 뜻의 N4 동사입니다.', 1, 12, 'N4', 'vocab', true),
  ('b0000001-0000-4000-a000-000000200109', 'a0000001-0000-4000-a000-000000000019', 'multiple_choice', '「直る」의 의미로 올바른 것은?', '直る(なおる)는 ''고쳐지다, 낫다''라는 뜻의 N4 동사입니다.', 1, 13, 'N4', 'vocab', true),
  ('b0000001-0000-4000-a000-00000020010a', 'a0000001-0000-4000-a000-000000000019', 'multiple_choice', '「汚す」의 의미로 올바른 것은?', '汚す(よごす)는 ''더럽히다''라는 뜻의 N4 동사입니다.', 1, 14, 'N4', 'vocab', true),
  ('b0000001-0000-4000-a000-00000020010b', 'a0000001-0000-4000-a000-000000000019', 'multiple_choice', '「汚れる」의 의미로 올바른 것은?', '汚れる(よごれる)는 ''더러워지다''라는 뜻의 N4 동사입니다.', 1, 15, 'N4', 'vocab', true),
  ('b0000001-0000-4000-a000-00000020010c', 'a0000001-0000-4000-a000-000000000019', 'multiple_choice', '「立てる」의 의미로 올바른 것은?', '立てる(たてる)는 ''세우다''라는 뜻의 N4 동사입니다.', 1, 16, 'N4', 'vocab', true),
  ('b0000001-0000-4000-a000-00000020010d', 'a0000001-0000-4000-a000-000000000019', 'multiple_choice', '「立つ」의 의미로 올바른 것은?', '立つ(たつ)는 ''서다''라는 뜻의 N4 동사입니다.', 1, 17, 'N4', 'vocab', true),
  ('b0000001-0000-4000-a000-00000020010e', 'a0000001-0000-4000-a000-000000000019', 'multiple_choice', '「調べる」의 의미로 올바른 것은?', '調べる(しらべる)는 ''조사하다, 알아보다''라는 뜻의 N4 동사입니다.', 1, 18, 'N4', 'vocab', true),
  ('b0000001-0000-4000-a000-00000020010f', 'a0000001-0000-4000-a000-000000000019', 'multiple_choice', '「比べる」의 의미로 올바른 것은?', '比べる(くらべる)는 ''비교하다''라는 뜻의 N4 동사입니다.', 1, 19, 'N4', 'vocab', true),
  ('b0000001-0000-4000-a000-000000200110', 'a0000001-0000-4000-a000-000000000019', 'multiple_choice', '「伝える」의 의미로 올바른 것은?', '伝える(つたえる)는 ''전하다, 알리다''라는 뜻의 N4 동사입니다.', 1, 20, 'N4', 'vocab', true),
  ('b0000001-0000-4000-a000-000000200111', 'a0000001-0000-4000-a000-000000000019', 'multiple_choice', '「捨てる」의 의미로 올바른 것은?', '捨てる(すてる)는 ''버리다''라는 뜻의 N4 동사입니다.', 1, 21, 'N4', 'vocab', true),
  ('b0000001-0000-4000-a000-000000200112', 'a0000001-0000-4000-a000-000000000019', 'multiple_choice', '「拾う」의 의미로 올바른 것은?', '拾う(ひろう)는 ''줍다''라는 뜻의 N4 동사입니다.', 1, 22, 'N4', 'vocab', true),
  ('b0000001-0000-4000-a000-000000200113', 'a0000001-0000-4000-a000-000000000019', 'multiple_choice', '「申し込む」의 의미로 올바른 것은?', '申し込む(もうしこむ)는 ''신청하다''라는 뜻의 N4 동사입니다.', 1, 23, 'N4', 'vocab', true),
  ('b0000001-0000-4000-a000-000000200114', 'a0000001-0000-4000-a000-000000000019', 'multiple_choice', '「育てる」의 의미로 올바른 것은?', '育てる(そだてる)는 ''키우다, 기르다''라는 뜻의 N4 동사입니다.', 1, 24, 'N4', 'vocab', true),
  ('b0000001-0000-4000-a000-000000200115', 'a0000001-0000-4000-a000-000000000019', 'multiple_choice', '「運ぶ」의 의미로 올바른 것은?', '運ぶ(はこぶ)는 ''나르다, 운반하다''라는 뜻의 N4 동사입니다.', 1, 25, 'N4', 'vocab', true),
  ('b0000001-0000-4000-a000-000000200116', 'a0000001-0000-4000-a000-000000000019', 'multiple_choice', '「選ぶ」의 의미로 올바른 것은?', '選ぶ(えらぶ)는 ''고르다, 선택하다''라는 뜻의 N4 동사입니다.', 1, 26, 'N4', 'vocab', true),
  ('b0000001-0000-4000-a000-000000200117', 'a0000001-0000-4000-a000-000000000019', 'multiple_choice', '「引っ越す」의 의미로 올바른 것은?', '引っ越す(ひっこす)는 ''이사하다''라는 뜻의 N4 동사입니다.', 1, 27, 'N4', 'vocab', true),
  ('b0000001-0000-4000-a000-000000200118', 'a0000001-0000-4000-a000-000000000019', 'multiple_choice', '「込む」의 의미로 올바른 것은?', '込む(こむ)는 ''붐비다, 혼잡하다''라는 뜻의 N4 동사입니다.', 1, 28, 'N4', 'vocab', true),
  ('b0000001-0000-4000-a000-000000200119', 'a0000001-0000-4000-a000-000000000019', 'multiple_choice', '「足りる」의 의미로 올바른 것은?', '足りる(たりる)는 ''충분하다, 족하다''라는 뜻의 N4 동사입니다.', 1, 29, 'N4', 'vocab', true),
