  ('b0000001-0000-4000-a000-00000020011b', 'a0000001-0000-4000-a000-000000000019', 'multiple_choice', '「笑う」의 의미로 올바른 것은?', '笑う(わらう)는 ''웃다''라는 뜻의 N4 동사입니다.', 1, 31, 'N4', 'vocab', true),
