  ('b0000001-0000-4000-a000-00000020012a', 'a0000001-0000-4000-a000-00000000001a', 'multiple_choice', '「入学する」의 의미로 올바른 것은?', '入学する(にゅうがくする)는 ''입학하다''라는 뜻의 N4 동사입니다.', 1, 1, 'N4', 'vocab', true),
  ('b0000001-0000-4000-a000-00000020012b', 'a0000001-0000-4000-a000-00000000001a', 'multiple_choice', '「予約する」의 의미로 올바른 것은?', '予約する(よやくする)는 ''예약하다''라는 뜻의 N4 동사입니다.', 1, 2, 'N4', 'vocab', true),
  ('b0000001-0000-4000-a000-00000020012c', 'a0000001-0000-4000-a000-00000000001a', 'multiple_choice', '「翻訳する」의 의미로 올바른 것은?', '翻訳する(ほんやくする)는 ''번역하다''라는 뜻의 N4 동사입니다.', 1, 3, 'N4', 'vocab', true),
  ('b0000001-0000-4000-a000-00000020012d', 'a0000001-0000-4000-a000-00000000001a', 'multiple_choice', '「生産する」의 의미로 올바른 것은?', '生産する(せいさんする)는 ''생산하다''라는 뜻의 N4 동사입니다.', 1, 4, 'N4', 'vocab', true),
  ('b0000001-0000-4000-a000-00000020012e', 'a0000001-0000-4000-a000-00000000001a', 'multiple_choice', '「輸出する」의 의미로 올바른 것은?', '輸出する(ゆしゅつする)는 ''수출하다''라는 뜻의 N4 동사입니다.', 1, 5, 'N4', 'vocab', true),
  ('b0000001-0000-4000-a000-00000020012f', 'a0000001-0000-4000-a000-00000000001a', 'multiple_choice', '「輸入する」의 의미로 올바른 것은?', '輸入する(ゆにゅうする)는 ''수입하다''라는 뜻의 N4 동사입니다.', 1, 6, 'N4', 'vocab', true),
