  ('b0000001-0000-4000-a000-000000200135', 'a0000001-0000-4000-a000-00000000001a', 'multiple_choice', '「反対する」의 의미로 올바른 것은?', '反対する(はんたいする)는 ''반대하다''라는 뜻의 N4 동사입니다.', 1, 12, 'N4', 'vocab', true),
  ('b0000001-0000-4000-a000-000000200136', 'a0000001-0000-4000-a000-00000000001a', 'multiple_choice', '「安心する」의 의미로 올바른 것은?', '安心する(あんしんする)는 ''안심하다''라는 뜻의 N4 동사입니다.', 1, 13, 'N4', 'vocab', true),
  ('b0000001-0000-4000-a000-000000200137', 'a0000001-0000-4000-a000-00000000001a', 'multiple_choice', '「心配する」의 의미로 올바른 것은?', '心配する(しんぱいする)는 ''걱정하다''라는 뜻의 N4 동사입니다.', 1, 14, 'N4', 'vocab', true),
  ('b0000001-0000-4000-a000-000000200138', 'a0000001-0000-4000-a000-00000000001a', 'multiple_choice', '「包む」의 의미로 올바른 것은?', '包む(つつむ)는 ''싸다, 포장하다''라는 뜻의 N4 동사입니다.', 1, 15, 'N4', 'vocab', true),
  ('b0000001-0000-4000-a000-000000200139', 'a0000001-0000-4000-a000-00000000001a', 'multiple_choice', '「乾く」의 의미로 올바른 것은?', '乾く(かわく)는 ''마르다''라는 뜻의 N4 동사입니다.', 1, 16, 'N4', 'vocab', true),
  ('b0000001-0000-4000-a000-00000020013a', 'a0000001-0000-4000-a000-00000000001a', 'multiple_choice', '「濡れる」의 의미로 올바른 것은?', '濡れる(ぬれる)는 ''젖다''라는 뜻의 N4 동사입니다.', 1, 17, 'N4', 'vocab', true),
  ('b0000001-0000-4000-a000-00000020013b', 'a0000001-0000-4000-a000-00000000001a', 'multiple_choice', '「沸かす」의 의미로 올바른 것은?', '沸かす(わかす)는 ''끓이다''라는 뜻의 N4 동사입니다.', 1, 18, 'N4', 'vocab', true),
  ('b0000001-0000-4000-a000-00000020013c', 'a0000001-0000-4000-a000-00000000001a', 'multiple_choice', '「沸く」의 의미로 올바른 것은?', '沸く(わく)는 ''끓다''라는 뜻의 N4 동사입니다.', 1, 19, 'N4', 'vocab', true),
  ('b0000001-0000-4000-a000-00000020013d', 'a0000001-0000-4000-a000-00000000001a', 'multiple_choice', '「焼く」의 의미로 올바른 것은?', '焼く(やく)는 ''굽다''라는 뜻의 N4 동사입니다.', 1, 20, 'N4', 'vocab', true),
  ('b0000001-0000-4000-a000-00000020013e', 'a0000001-0000-4000-a000-00000000001a', 'multiple_choice', '「揺れる」의 의미로 올바른 것은?', '揺れる(ゆれる)는 ''흔들리다''라는 뜻의 N4 동사입니다.', 1, 21, 'N4', 'vocab', true),
  ('b0000001-0000-4000-a000-00000020013f', 'a0000001-0000-4000-a000-00000000001a', 'multiple_choice', '「触る」의 의미로 올바른 것은?', '触る(さわる)는 ''만지다''라는 뜻의 N4 동사입니다.', 1, 22, 'N4', 'vocab', true),
  ('b0000001-0000-4000-a000-000000200140', 'a0000001-0000-4000-a000-00000000001a', 'multiple_choice', '「うるさい」의 의미로 올바른 것은?', 'うるさい(うるさい)는 ''시끄럽다''라는 뜻의 N4 い형용사입니다.', 1, 23, 'N4', 'vocab', true),
  ('b0000001-0000-4000-a000-000000200141', 'a0000001-0000-4000-a000-00000000001a', 'multiple_choice', '「汚い」의 의미로 올바른 것은?', '汚い(きたない)는 ''더럽다''라는 뜻의 N4 い형용사입니다.', 1, 24, 'N4', 'vocab', true),
  ('b0000001-0000-4000-a000-000000200142', 'a0000001-0000-4000-a000-00000000001a', 'multiple_choice', '「正しい」의 의미로 올바른 것은?', '正しい(ただしい)는 ''올바르다, 정확하다''라는 뜻의 N4 い형용사입니다.', 1, 25, 'N4', 'vocab', true),
  ('b0000001-0000-4000-a000-000000200143', 'a0000001-0000-4000-a000-00000000001a', 'multiple_choice', '「珍しい」의 의미로 올바른 것은?', '珍しい(めずらしい)는 ''드물다, 신기하다''라는 뜻의 N4 い형용사입니다.', 1, 26, 'N4', 'vocab', true),
  ('b0000001-0000-4000-a000-000000200144', 'a0000001-0000-4000-a000-00000000001a', 'multiple_choice', '「危ない」의 의미로 올바른 것은?', '危ない(あぶない)는 ''위험하다''라는 뜻의 N4 い형용사입니다.', 1, 27, 'N4', 'vocab', true),
  ('b0000001-0000-4000-a000-000000200145', 'a0000001-0000-4000-a000-00000000001a', 'multiple_choice', '「恥ずかしい」의 의미로 올바른 것은?', '恥ずかしい(はずかしい)는 ''부끄럽다''라는 뜻의 N4 い형용사입니다.', 1, 28, 'N4', 'vocab', true),
  ('b0000001-0000-4000-a000-000000200146', 'a0000001-0000-4000-a000-00000000001a', 'multiple_choice', '「悲しい」의 의미로 올바른 것은?', '悲しい(かなしい)는 ''슬프다''라는 뜻의 N4 い형용사입니다.', 1, 29, 'N4', 'vocab', true),
  ('b0000001-0000-4000-a000-000000200147', 'a0000001-0000-4000-a000-00000000001a', 'multiple_choice', '「嬉しい」의 의미로 올바른 것은?', '嬉しい(うれしい)는 ''기쁘다''라는 뜻의 N4 い형용사입니다.', 1, 30, 'N4', 'vocab', true),
  ('b0000001-0000-4000-a000-000000200148', 'a0000001-0000-4000-a000-00000000001a', 'multiple_choice', '「寂しい」의 의미로 올바른 것은?', '寂しい(さびしい)는 ''외롭다, 쓸쓸하다''라는 뜻의 N4 い형용사입니다.', 1, 31, 'N4', 'vocab', true),
  ('b0000001-0000-4000-a000-000000200149', 'a0000001-0000-4000-a000-00000000001a', 'multiple_choice', '「厳しい」의 의미로 올바른 것은?', '厳しい(きびしい)는 ''엄격하다, 힘들다''라는 뜻의 N4 い형용사입니다.', 1, 32, 'N4', 'vocab', true),
  ('b0000001-0000-4000-a000-00000020014a', 'a0000001-0000-4000-a000-00000000001a', 'multiple_choice', '「柔らかい」의 의미로 올바른 것은?', '柔らかい(やわらかい)는 ''부드럽다''라는 뜻의 N4 い형용사입니다.', 1, 33, 'N4', 'vocab', true),
  ('b0000001-0000-4000-a000-00000020014b', 'a0000001-0000-4000-a000-00000000001a', 'multiple_choice', '「硬い」의 의미로 올바른 것은?', '硬い(かたい)는 ''딱딱하다, 단단하다''라는 뜻의 N4 い형용사입니다.', 1, 34, 'N4', 'vocab', true),
  ('b0000001-0000-4000-a000-00000020014c', 'a0000001-0000-4000-a000-00000000001a', 'multiple_choice', '「眠い」의 의미로 올바른 것은?', '眠い(ねむい)는 ''졸리다''라는 뜻의 N4 い형용사입니다.', 1, 35, 'N4', 'vocab', true),
  ('b0000001-0000-4000-a000-00000020014d', 'a0000001-0000-4000-a000-00000000001a', 'multiple_choice', '「痒い」의 의미로 올바른 것은?', '痒い(かゆい)는 ''가렵다''라는 뜻의 N4 い형용사입니다.', 1, 36, 'N4', 'vocab', true),
  ('b0000001-0000-4000-a000-00000020014e', 'a0000001-0000-4000-a000-00000000001a', 'multiple_choice', '「深い」의 의미로 올바른 것은?', '深い(ふかい)는 ''깊다''라는 뜻의 N4 い형용사입니다.', 1, 37, 'N4', 'vocab', true),
  ('b0000001-0000-4000-a000-00000020014f', 'a0000001-0000-4000-a000-00000000001a', 'multiple_choice', '「浅い」의 의미로 올바른 것은?', '浅い(あさい)는 ''얕다''라는 뜻의 N4 い형용사입니다.', 1, 38, 'N4', 'vocab', true),
  ('b0000001-0000-4000-a000-000000200150', 'a0000001-0000-4000-a000-00000000001a', 'multiple_choice', '「太い」의 의미로 올바른 것은?', '太い(ふとい)는 ''굵다, 뚱뚱하다''라는 뜻의 N4 い형용사입니다.', 1, 39, 'N4', 'vocab', true),
  ('b0000001-0000-4000-a000-000000200151', 'a0000001-0000-4000-a000-00000000001a', 'multiple_choice', '「細い」의 의미로 올바른 것은?', '細い(ほそい)는 ''가늘다, 가는''라는 뜻의 N4 い형용사입니다.', 1, 40, 'N4', 'vocab', true),
  ('b0000001-0000-4000-a000-000000200152', 'a0000001-0000-4000-a000-00000000001a', 'multiple_choice', '「酸っぱい」의 의미로 올바른 것은?', '酸っぱい(すっぱい)는 ''시다, 새콤하다''라는 뜻의 N4 い형용사입니다.', 1, 41, 'N4', 'vocab', true),
  ('b0000001-0000-4000-a000-000000200153', 'a0000001-0000-4000-a000-00000000001a', 'multiple_choice', '「苦い」의 의미로 올바른 것은?', '苦い(にがい)는 ''쓰다''라는 뜻의 N4 い형용사입니다.', 1, 42, 'N4', 'vocab', true),
  ('b0000001-0000-4000-a000-000000200154', 'a0000001-0000-4000-a000-00000000001a', 'multiple_choice', '「素晴らしい」의 의미로 올바른 것은?', '素晴らしい(すばらしい)는 ''훌륭하다, 멋지다''라는 뜻의 N4 い형용사입니다.', 1, 43, 'N4', 'vocab', true),
  ('b0000001-0000-4000-a000-000000200155', 'a0000001-0000-4000-a000-00000000001a', 'multiple_choice', '「羨ましい」의 의미로 올바른 것은?', '羨ましい(うらやましい)는 ''부럽다''라는 뜻의 N4 い형용사입니다.', 1, 44, 'N4', 'vocab', true),
  ('b0000001-0000-4000-a000-000000200156', 'a0000001-0000-4000-a000-00000000001a', 'multiple_choice', '「仲がいい」의 의미로 올바른 것은?', '仲がいい(なかがいい)는 ''사이가 좋다''라는 뜻의 N4 い형용사입니다.', 1, 45, 'N4', 'vocab', true);

