-- N4 語彙テスト 第8回 (45 questions)
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES
  ('b0000001-0000-4000-a000-000000200157', 'a0000001-0000-4000-a000-00000000001b', 'multiple_choice', '「激しい」의 의미로 올바른 것은?', '激しい(はげしい)는 ''격렬하다, 심하다''라는 뜻의 N4 い형용사입니다.', 1, 1, 'N4', 'vocab', true),
  ('b0000001-0000-4000-a000-000000200158', 'a0000001-0000-4000-a000-00000000001b', 'multiple_choice', '「恐ろしい」의 의미로 올바른 것은?', '恐ろしい(おそろしい)는 ''무섭다, 두렵다''라는 뜻의 N4 い형용사입니다.', 1, 2, 'N4', 'vocab', true),
  ('b0000001-0000-4000-a000-000000200159', 'a0000001-0000-4000-a000-00000000001b', 'multiple_choice', '「簡単」의 의미로 올바른 것은?', '簡単(かんたん)는 ''간단하다, 쉽다''라는 뜻의 N4 な형용사입니다.', 1, 3, 'N4', 'vocab', true),
  ('b0000001-0000-4000-a000-00000020015a', 'a0000001-0000-4000-a000-00000000001b', 'multiple_choice', '「不便」의 의미로 올바른 것은?', '不便(ふべん)는 ''불편하다''라는 뜻의 N4 な형용사입니다.', 1, 4, 'N4', 'vocab', true),
  ('b0000001-0000-4000-a000-00000020015b', 'a0000001-0000-4000-a000-00000000001b', 'multiple_choice', '「熱心」의 의미로 올바른 것은?', '熱心(ねっしん)는 ''열심이다, 열성적이다''라는 뜻의 N4 な형용사입니다.', 1, 5, 'N4', 'vocab', true),
  ('b0000001-0000-4000-a000-00000020015c', 'a0000001-0000-4000-a000-00000000001b', 'multiple_choice', '「安全」의 의미로 올바른 것은?', '安全(あんぜん)는 ''안전하다''라는 뜻의 N4 な형용사입니다.', 1, 6, 'N4', 'vocab', true),
  ('b0000001-0000-4000-a000-00000020015d', 'a0000001-0000-4000-a000-00000000001b', 'multiple_choice', '「危険」의 의미로 올바른 것은?', '危険(きけん)는 ''위험하다''라는 뜻의 N4 な형용사입니다.', 1, 7, 'N4', 'vocab', true),
  ('b0000001-0000-4000-a000-00000020015e', 'a0000001-0000-4000-a000-00000000001b', 'multiple_choice', '「無理」의 의미로 올바른 것은?', '無理(むり)는 ''무리이다, 불가능하다''라는 뜻의 N4 な형용사입니다.', 1, 8, 'N4', 'vocab', true),
  ('b0000001-0000-4000-a000-00000020015f', 'a0000001-0000-4000-a000-00000000001b', 'multiple_choice', '「邪魔」의 의미로 올바른 것은?', '邪魔(じゃま)는 ''방해가 되다''라는 뜻의 N4 な형용사입니다.', 1, 9, 'N4', 'vocab', true),
  ('b0000001-0000-4000-a000-000000200160', 'a0000001-0000-4000-a000-00000000001b', 'multiple_choice', '「素直」의 의미로 올바른 것은?', '素直(すなお)는 ''순수하다, 솔직하다''라는 뜻의 N4 な형용사입니다.', 1, 10, 'N4', 'vocab', true),
  ('b0000001-0000-4000-a000-000000200161', 'a0000001-0000-4000-a000-00000000001b', 'multiple_choice', '「真面目」의 의미로 올바른 것은?', '真面目(まじめ)는 ''성실하다, 진지하다''라는 뜻의 N4 な형용사입니다.', 1, 11, 'N4', 'vocab', true),
  ('b0000001-0000-4000-a000-000000200162', 'a0000001-0000-4000-a000-00000000001b', 'multiple_choice', '「適当」의 의미로 올바른 것은?', '適当(てきとう)는 ''적당하다, 대충''라는 뜻의 N4 な형용사입니다.', 1, 12, 'N4', 'vocab', true),
  ('b0000001-0000-4000-a000-000000200163', 'a0000001-0000-4000-a000-00000000001b', 'multiple_choice', '「十分」의 의미로 올바른 것은?', '十分(じゅうぶん)는 ''충분하다''라는 뜻의 N4 な형용사입니다.', 1, 13, 'N4', 'vocab', true),
  ('b0000001-0000-4000-a000-000000200164', 'a0000001-0000-4000-a000-00000000001b', 'multiple_choice', '「盛ん」의 의미로 올바른 것은?', '盛ん(さかん)는 ''성하다, 활발하다''라는 뜻의 N4 な형용사입니다.', 1, 14, 'N4', 'vocab', true),
  ('b0000001-0000-4000-a000-000000200165', 'a0000001-0000-4000-a000-00000000001b', 'multiple_choice', '「立派」의 의미로 올바른 것은?', '立派(りっぱ)는 ''훌륭하다, 멋지다''라는 뜻의 N4 な형용사입니다.', 1, 15, 'N4', 'vocab', true),
  ('b0000001-0000-4000-a000-000000200166', 'a0000001-0000-4000-a000-00000000001b', 'multiple_choice', '「豊か」의 의미로 올바른 것은?', '豊か(ゆたか)는 ''풍부하다, 풍요롭다''라는 뜻의 N4 な형용사입니다.', 1, 16, 'N4', 'vocab', true),
  ('b0000001-0000-4000-a000-000000200167', 'a0000001-0000-4000-a000-00000000001b', 'multiple_choice', '「確か」의 의미로 올바른 것은?', '確か(たしか)는 ''확실하다''라는 뜻의 N4 な형용사입니다.', 1, 17, 'N4', 'vocab', true),
  ('b0000001-0000-4000-a000-000000200168', 'a0000001-0000-4000-a000-00000000001b', 'multiple_choice', '「急」의 의미로 올바른 것은?', '急(きゅう)는 ''급하다''라는 뜻의 N4 な형용사입니다.', 1, 18, 'N4', 'vocab', true),
  ('b0000001-0000-4000-a000-000000200169', 'a0000001-0000-4000-a000-00000000001b', 'multiple_choice', '「普通」의 의미로 올바른 것은?', '普通(ふつう)는 ''보통이다, 평범하다''라는 뜻의 N4 な형용사입니다.', 1, 19, 'N4', 'vocab', true),
  ('b0000001-0000-4000-a000-00000020016a', 'a0000001-0000-4000-a000-00000000001b', 'multiple_choice', '「有名」의 의미로 올바른 것은?', '有名(ゆうめい)는 ''유명하다''라는 뜻의 N4 な형용사입니다.', 1, 20, 'N4', 'vocab', true),
  ('b0000001-0000-4000-a000-00000020016b', 'a0000001-0000-4000-a000-00000000001b', 'multiple_choice', '「予定」의 의미로 올바른 것은?', '予定(よてい)는 ''예정, 계획''라는 뜻의 N4 명사입니다.', 1, 21, 'N4', 'vocab', true),
  ('b0000001-0000-4000-a000-00000020016c', 'a0000001-0000-4000-a000-00000000001b', 'multiple_choice', '「約束」의 의미로 올바른 것은?', '約束(やくそく)는 ''약속''라는 뜻의 N4 명사입니다.', 1, 22, 'N4', 'vocab', true),
  ('b0000001-0000-4000-a000-00000020016d', 'a0000001-0000-4000-a000-00000000001b', 'multiple_choice', '「意見」의 의미로 올바른 것은?', '意見(いけん)는 ''의견''라는 뜻의 N4 명사입니다.', 1, 23, 'N4', 'vocab', true),
  ('b0000001-0000-4000-a000-00000020016e', 'a0000001-0000-4000-a000-00000000001b', 'multiple_choice', '「理由」의 의미로 올바른 것은?', '理由(りゆう)는 ''이유''라는 뜻의 N4 명사입니다.', 1, 24, 'N4', 'vocab', true),
  ('b0000001-0000-4000-a000-00000020016f', 'a0000001-0000-4000-a000-00000000001b', 'multiple_choice', '「関係」의 의미로 올바른 것은?', '関係(かんけい)는 ''관계''라는 뜻의 N4 명사입니다.', 1, 25, 'N4', 'vocab', true),
  ('b0000001-0000-4000-a000-000000200170', 'a0000001-0000-4000-a000-00000000001b', 'multiple_choice', '「番組」의 의미로 올바른 것은?', '番組(ばんぐみ)는 ''프로그램, 방송''라는 뜻의 N4 명사입니다.', 1, 26, 'N4', 'vocab', true),
  ('b0000001-0000-4000-a000-000000200171', 'a0000001-0000-4000-a000-00000000001b', 'multiple_choice', '「場所」의 의미로 올바른 것은?', '場所(ばしょ)는 ''장소''라는 뜻의 N4 명사입니다.', 1, 27, 'N4', 'vocab', true),
  ('b0000001-0000-4000-a000-000000200172', 'a0000001-0000-4000-a000-00000000001b', 'multiple_choice', '「季節」의 의미로 올바른 것은?', '季節(きせつ)는 ''계절''라는 뜻의 N4 명사입니다.', 1, 28, 'N4', 'vocab', true),
