INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES
  ('b0000001-0000-4000-a000-0000002001b0', 'a0000001-0000-4000-a000-00000000001d', 'multiple_choice', '「用事」의 의미로 올바른 것은?', '用事(ようじ)는 ''용무, 볼일''라는 뜻의 N4 명사입니다.', 1, 1, 'N4', 'vocab', true),
  ('b0000001-0000-4000-a000-0000002001b1', 'a0000001-0000-4000-a000-00000000001d', 'multiple_choice', '「味方」의 의미로 올바른 것은?', '味方(みかた)는 ''아군, 편''라는 뜻의 N4 명사입니다.', 1, 2, 'N4', 'vocab', true),
  ('b0000001-0000-4000-a000-0000002001b2', 'a0000001-0000-4000-a000-00000000001d', 'multiple_choice', '「相手」의 의미로 올바른 것은?', '相手(あいて)는 ''상대''라는 뜻의 N4 명사입니다.', 1, 3, 'N4', 'vocab', true),
  ('b0000001-0000-4000-a000-0000002001b3', 'a0000001-0000-4000-a000-00000000001d', 'multiple_choice', '「合計」의 의미로 올바른 것은?', '合計(ごうけい)는 ''합계''라는 뜻의 N4 명사입니다.', 1, 4, 'N4', 'vocab', true),
  ('b0000001-0000-4000-a000-0000002001b4', 'a0000001-0000-4000-a000-00000000001d', 'multiple_choice', '「平均」의 의미로 올바른 것은?', '平均(へいきん)는 ''평균''라는 뜻의 N4 명사입니다.', 1, 5, 'N4', 'vocab', true),
  ('b0000001-0000-4000-a000-0000002001b5', 'a0000001-0000-4000-a000-00000000001d', 'multiple_choice', '「以上」의 의미로 올바른 것은?', '以上(いじょう)는 ''이상''라는 뜻의 N4 명사입니다.', 1, 6, 'N4', 'vocab', true),
  ('b0000001-0000-4000-a000-0000002001b6', 'a0000001-0000-4000-a000-00000000001d', 'multiple_choice', '「以下」의 의미로 올바른 것은?', '以下(いか)는 ''이하''라는 뜻의 N4 명사입니다.', 1, 7, 'N4', 'vocab', true),
  ('b0000001-0000-4000-a000-0000002001b7', 'a0000001-0000-4000-a000-00000000001d', 'multiple_choice', '「以内」의 의미로 올바른 것은?', '以内(いない)는 ''이내''라는 뜻의 N4 명사입니다.', 1, 8, 'N4', 'vocab', true),
  ('b0000001-0000-4000-a000-0000002001b8', 'a0000001-0000-4000-a000-00000000001d', 'multiple_choice', '「途中」의 의미로 올바른 것은?', '途中(とちゅう)는 ''도중''라는 뜻의 N4 명사입니다.', 1, 9, 'N4', 'vocab', true),
  ('b0000001-0000-4000-a000-0000002001b9', 'a0000001-0000-4000-a000-00000000001d', 'multiple_choice', '「最初」의 의미로 올바른 것은?', '最初(さいしょ)는 ''최초, 처음''라는 뜻의 N4 명사입니다.', 1, 10, 'N4', 'vocab', true),
  ('b0000001-0000-4000-a000-0000002001ba', 'a0000001-0000-4000-a000-00000000001d', 'multiple_choice', '「最後」의 의미로 올바른 것은?', '最後(さいご)는 ''최후, 마지막''라는 뜻의 N4 명사입니다.', 1, 11, 'N4', 'vocab', true),
  ('b0000001-0000-4000-a000-0000002001bb', 'a0000001-0000-4000-a000-00000000001d', 'multiple_choice', '「最近」의 의미로 올바른 것은?', '最近(さいきん)는 ''최근''라는 뜻의 N4 명사입니다.', 1, 12, 'N4', 'vocab', true),
  ('b0000001-0000-4000-a000-0000002001bc', 'a0000001-0000-4000-a000-00000000001d', 'multiple_choice', '「最中」의 의미로 올바른 것은?', '最中(さいちゅう)는 ''한창, ~하는 중''라는 뜻의 N4 명사입니다.', 1, 13, 'N4', 'vocab', true),
  ('b0000001-0000-4000-a000-0000002001bd', 'a0000001-0000-4000-a000-00000000001d', 'multiple_choice', '「全体」의 의미로 올바른 것은?', '全体(ぜんたい)는 ''전체''라는 뜻의 N4 명사입니다.', 1, 14, 'N4', 'vocab', true),
  ('b0000001-0000-4000-a000-0000002001be', 'a0000001-0000-4000-a000-00000000001d', 'multiple_choice', '「部分」의 의미로 올바른 것은?', '部分(ぶぶん)는 ''부분''라는 뜻의 N4 명사입니다.', 1, 15, 'N4', 'vocab', true),
  ('b0000001-0000-4000-a000-0000002001bf', 'a0000001-0000-4000-a000-00000000001d', 'multiple_choice', '「事務所」의 의미로 올바른 것은?', '事務所(じむしょ)는 ''사무소''라는 뜻의 N4 명사입니다.', 1, 16, 'N4', 'vocab', true),
  ('b0000001-0000-4000-a000-0000002001c0', 'a0000001-0000-4000-a000-00000000001d', 'multiple_choice', '「工場」의 의미로 올바른 것은?', '工場(こうじょう)는 ''공장''라는 뜻의 N4 명사입니다.', 1, 17, 'N4', 'vocab', true),
  ('b0000001-0000-4000-a000-0000002001c1', 'a0000001-0000-4000-a000-00000000001d', 'multiple_choice', '「売り場」의 의미로 올바른 것은?', '売り場(うりば)는 ''매장''라는 뜻의 N4 명사입니다.', 1, 18, 'N4', 'vocab', true),
  ('b0000001-0000-4000-a000-0000002001c2', 'a0000001-0000-4000-a000-00000000001d', 'multiple_choice', '「特に」의 의미로 올바른 것은?', '特に(とくに)는 ''특히''라는 뜻의 N4 부사입니다.', 1, 19, 'N4', 'vocab', true),
  ('b0000001-0000-4000-a000-0000002001c3', 'a0000001-0000-4000-a000-00000000001d', 'multiple_choice', '「必ず」의 의미로 올바른 것은?', '必ず(かならず)는 ''반드시''라는 뜻의 N4 부사입니다.', 1, 20, 'N4', 'vocab', true),
  ('b0000001-0000-4000-a000-0000002001c4', 'a0000001-0000-4000-a000-00000000001d', 'multiple_choice', '「急に」의 의미로 올바른 것은?', '急に(きゅうに)는 ''갑자기''라는 뜻의 N4 부사입니다.', 1, 21, 'N4', 'vocab', true),
  ('b0000001-0000-4000-a000-0000002001c5', 'a0000001-0000-4000-a000-00000000001d', 'multiple_choice', '「やっと」의 의미로 올바른 것은?', 'やっと(やっと)는 ''겨우, 드디어''라는 뜻의 N4 부사입니다.', 1, 22, 'N4', 'vocab', true),
  ('b0000001-0000-4000-a000-0000002001c6', 'a0000001-0000-4000-a000-00000000001d', 'multiple_choice', '「なかなか」의 의미로 올바른 것은?', 'なかなか(なかなか)는 ''좀처럼, 꽤''라는 뜻의 N4 부사입니다.', 1, 23, 'N4', 'vocab', true),
  ('b0000001-0000-4000-a000-0000002001c7', 'a0000001-0000-4000-a000-00000000001d', 'multiple_choice', '「だんだん」의 의미로 올바른 것은?', 'だんだん(だんだん)는 ''점점, 차차''라는 뜻의 N4 부사입니다.', 1, 24, 'N4', 'vocab', true),
  ('b0000001-0000-4000-a000-0000002001c8', 'a0000001-0000-4000-a000-00000000001d', 'multiple_choice', '「そろそろ」의 의미로 올바른 것은?', 'そろそろ(そろそろ)는 ''슬슬, 곧''라는 뜻의 N4 부사입니다.', 1, 25, 'N4', 'vocab', true),
