-- N4 語彙テスト 第11回 (44 questions)
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES
  ('b0000001-0000-4000-a000-0000002001dc', 'a0000001-0000-4000-a000-00000000001e', 'multiple_choice', '「直接」의 의미로 올바른 것은?', '直接(ちょくせつ)는 ''직접''라는 뜻의 N4 부사입니다.', 1, 1, 'N4', 'vocab', true),
  ('b0000001-0000-4000-a000-0000002001dd', 'a0000001-0000-4000-a000-00000000001e', 'multiple_choice', '「自然に」의 의미로 올바른 것은?', '自然に(しぜんに)는 ''자연스럽게''라는 뜻의 N4 부사입니다.', 1, 2, 'N4', 'vocab', true),
  ('b0000001-0000-4000-a000-0000002001de', 'a0000001-0000-4000-a000-00000000001e', 'multiple_choice', '「相変わらず」의 의미로 올바른 것은?', '相変わらず(あいかわらず)는 ''여전히, 변함없이''라는 뜻의 N4 부사입니다.', 1, 3, 'N4', 'vocab', true),
  ('b0000001-0000-4000-a000-0000002001df', 'a0000001-0000-4000-a000-00000000001e', 'multiple_choice', '「いきなり」의 의미로 올바른 것은?', 'いきなり(いきなり)는 ''갑자기, 느닷없이''라는 뜻의 N4 부사입니다.', 1, 4, 'N4', 'vocab', true),
  ('b0000001-0000-4000-a000-0000002001e0', 'a0000001-0000-4000-a000-00000000001e', 'multiple_choice', '「つまり」의 의미로 올바른 것은?', 'つまり(つまり)는 ''즉, 다시 말해''라는 뜻의 N4 접속사입니다.', 1, 5, 'N4', 'vocab', true),
  ('b0000001-0000-4000-a000-0000002001e1', 'a0000001-0000-4000-a000-00000000001e', 'multiple_choice', '「それで」의 의미로 올바른 것은?', 'それで(それで)는 ''그래서''라는 뜻의 N4 접속사입니다.', 1, 6, 'N4', 'vocab', true),
  ('b0000001-0000-4000-a000-0000002001e2', 'a0000001-0000-4000-a000-00000000001e', 'multiple_choice', '「それに」의 의미로 올바른 것은?', 'それに(それに)는 ''게다가''라는 뜻의 N4 접속사입니다.', 1, 7, 'N4', 'vocab', true),
  ('b0000001-0000-4000-a000-0000002001e3', 'a0000001-0000-4000-a000-00000000001e', 'multiple_choice', '「ところが」의 의미로 올바른 것은?', 'ところが(ところが)는 ''그런데, 하지만''라는 뜻의 N4 접속사입니다.', 1, 8, 'N4', 'vocab', true),
  ('b0000001-0000-4000-a000-0000002001e4', 'a0000001-0000-4000-a000-00000000001e', 'multiple_choice', '「それなら」의 의미로 올바른 것은?', 'それなら(それなら)는 ''그렇다면''라는 뜻의 N4 접속사입니다.', 1, 9, 'N4', 'vocab', true),
  ('b0000001-0000-4000-a000-0000002001e5', 'a0000001-0000-4000-a000-00000000001e', 'multiple_choice', '「しかも」의 의미로 올바른 것은?', 'しかも(しかも)는 ''게다가, 더구나''라는 뜻의 N4 접속사입니다.', 1, 10, 'N4', 'vocab', true),
  ('b0000001-0000-4000-a000-0000002001e6', 'a0000001-0000-4000-a000-00000000001e', 'multiple_choice', '「ただし」의 의미로 올바른 것은?', 'ただし(ただし)는 ''단, 다만''라는 뜻의 N4 접속사입니다.', 1, 11, 'N4', 'vocab', true),
  ('b0000001-0000-4000-a000-0000002001e7', 'a0000001-0000-4000-a000-00000000001e', 'multiple_choice', '「なぜなら」의 의미로 올바른 것은?', 'なぜなら(なぜなら)는 ''왜냐하면''라는 뜻의 N4 접속사입니다.', 1, 12, 'N4', 'vocab', true),
  ('b0000001-0000-4000-a000-0000002001e8', 'a0000001-0000-4000-a000-00000000001e', 'multiple_choice', '「すると」의 의미로 올바른 것은?', 'すると(すると)는 ''그러자''라는 뜻의 N4 접속사입니다.', 1, 13, 'N4', 'vocab', true),
  ('b0000001-0000-4000-a000-0000002001e9', 'a0000001-0000-4000-a000-00000000001e', 'multiple_choice', '「または」의 의미로 올바른 것은?', 'または(または)는 ''또는''라는 뜻의 N4 접속사입니다.', 1, 14, 'N4', 'vocab', true),
  ('b0000001-0000-4000-a000-0000002001ea', 'a0000001-0000-4000-a000-00000000001e', 'multiple_choice', '「〜回」의 의미로 올바른 것은?', '〜回(かい)는 ''~회, ~번''라는 뜻의 N4 표현입니다.', 1, 15, 'N4', 'vocab', true),
  ('b0000001-0000-4000-a000-0000002001eb', 'a0000001-0000-4000-a000-00000000001e', 'multiple_choice', '「〜倍」의 의미로 올바른 것은?', '〜倍(ばい)는 ''~배''라는 뜻의 N4 표현입니다.', 1, 16, 'N4', 'vocab', true),
  ('b0000001-0000-4000-a000-0000002001ec', 'a0000001-0000-4000-a000-00000000001e', 'multiple_choice', '「〜点」의 의미로 올바른 것은?', '〜点(てん)는 ''~점''라는 뜻의 N4 표현입니다.', 1, 17, 'N4', 'vocab', true),
  ('b0000001-0000-4000-a000-0000002001ed', 'a0000001-0000-4000-a000-00000000001e', 'multiple_choice', '「〜割」의 의미로 올바른 것은?', '〜割(わり)는 ''~할, ~퍼센트''라는 뜻의 N4 표현입니다.', 1, 18, 'N4', 'vocab', true),
  ('b0000001-0000-4000-a000-0000002001ee', 'a0000001-0000-4000-a000-00000000001e', 'multiple_choice', '「〜泊」의 의미로 올바른 것은?', '〜泊(はく)는 ''~박''라는 뜻의 N4 표현입니다.', 1, 19, 'N4', 'vocab', true),
  ('b0000001-0000-4000-a000-0000002001ef', 'a0000001-0000-4000-a000-00000000001e', 'multiple_choice', '「〜畳」의 의미로 올바른 것은?', '〜畳(じょう)는 ''~다다미(넓이 단위)''라는 뜻의 N4 표현입니다.', 1, 20, 'N4', 'vocab', true),
  ('b0000001-0000-4000-a000-0000002001f0', 'a0000001-0000-4000-a000-00000000001e', 'multiple_choice', '「〜代」의 의미로 올바른 것은?', '〜代(だい)는 ''~대 (연령, 요금)''라는 뜻의 N4 표현입니다.', 1, 21, 'N4', 'vocab', true),
  ('b0000001-0000-4000-a000-0000002001f1', 'a0000001-0000-4000-a000-00000000001e', 'multiple_choice', '「〜届け」의 의미로 올바른 것은?', '〜届け(とどけ)는 ''~신고''라는 뜻의 N4 표현입니다.', 1, 22, 'N4', 'vocab', true),
  ('b0000001-0000-4000-a000-0000002001f2', 'a0000001-0000-4000-a000-00000000001e', 'multiple_choice', '「それでは」의 의미로 올바른 것은?', 'それでは(それでは)는 ''그러면, 그럼''라는 뜻의 N4 표현입니다.', 1, 23, 'N4', 'vocab', true),
  ('b0000001-0000-4000-a000-0000002001f3', 'a0000001-0000-4000-a000-00000000001e', 'multiple_choice', '「ところで」의 의미로 올바른 것은?', 'ところで(ところで)는 ''그런데 (화제 전환)''라는 뜻의 N4 표현입니다.', 1, 24, 'N4', 'vocab', true),
  ('b0000001-0000-4000-a000-0000002001f4', 'a0000001-0000-4000-a000-00000000001e', 'multiple_choice', '「おかげで」의 의미로 올바른 것은?', 'おかげで(おかげで)는 ''덕분에''라는 뜻의 N4 표현입니다.', 1, 25, 'N4', 'vocab', true),
  ('b0000001-0000-4000-a000-0000002001f5', 'a0000001-0000-4000-a000-00000000001e', 'multiple_choice', '「せいで」의 의미로 올바른 것은?', 'せいで(せいで)는 ''~탓에, ~때문에''라는 뜻의 N4 표현입니다.', 1, 26, 'N4', 'vocab', true),
  ('b0000001-0000-4000-a000-0000002001f6', 'a0000001-0000-4000-a000-00000000001e', 'multiple_choice', '「ようにする」의 의미로 올바른 것은?', 'ようにする(ようにする)는 ''~하도록 하다''라는 뜻의 N4 표현입니다.', 1, 27, 'N4', 'vocab', true),
  ('b0000001-0000-4000-a000-0000002001f7', 'a0000001-0000-4000-a000-00000000001e', 'multiple_choice', '「ようになる」의 의미로 올바른 것은?', 'ようになる(ようになる)는 ''~하게 되다''라는 뜻의 N4 표현입니다.', 1, 28, 'N4', 'vocab', true),
  ('b0000001-0000-4000-a000-0000002001f8', 'a0000001-0000-4000-a000-00000000001e', 'multiple_choice', '「ことにする」의 의미로 올바른 것은?', 'ことにする(ことにする)는 ''~하기로 하다''라는 뜻의 N4 표현입니다.', 1, 29, 'N4', 'vocab', true),
  ('b0000001-0000-4000-a000-0000002001f9', 'a0000001-0000-4000-a000-00000000001e', 'multiple_choice', '「ことになる」의 의미로 올바른 것은?', 'ことになる(ことになる)는 ''~하게 되다''라는 뜻의 N4 표현입니다.', 1, 30, 'N4', 'vocab', true),
  ('b0000001-0000-4000-a000-0000002001fa', 'a0000001-0000-4000-a000-00000000001e', 'multiple_choice', '「たばかり」의 의미로 올바른 것은?', 'たばかり(たばかり)는 ''~한 지 얼마 안 되다''라는 뜻의 N4 표현입니다.', 1, 31, 'N4', 'vocab', true),
  ('b0000001-0000-4000-a000-0000002001fb', 'a0000001-0000-4000-a000-00000000001e', 'multiple_choice', '「ていただく」의 의미로 올바른 것은?', 'ていただく(ていただく)는 ''~해 주시다 (겸양)''라는 뜻의 N4 표현입니다.', 1, 32, 'N4', 'vocab', true),
  ('b0000001-0000-4000-a000-0000002001fc', 'a0000001-0000-4000-a000-00000000001e', 'multiple_choice', '「てくださる」의 의미로 올바른 것은?', 'てくださる(てくださる)는 ''~해 주시다 (존경)''라는 뜻의 N4 표현입니다.', 1, 33, 'N4', 'vocab', true),
  ('b0000001-0000-4000-a000-0000002001fd', 'a0000001-0000-4000-a000-00000000001e', 'multiple_choice', '「ていらっしゃる」의 의미로 올바른 것은?', 'ていらっしゃる(ていらっしゃる)는 ''~하고 계시다''라는 뜻의 N4 표현입니다.', 1, 34, 'N4', 'vocab', true),
  ('b0000001-0000-4000-a000-0000002001fe', 'a0000001-0000-4000-a000-00000000001e', 'multiple_choice', '「〜ずつ」의 의미로 올바른 것은?', '〜ずつ(ずつ)는 ''~씩''라는 뜻의 N4 표현입니다.', 1, 35, 'N4', 'vocab', true),
  ('b0000001-0000-4000-a000-0000002001ff', 'a0000001-0000-4000-a000-00000000001e', 'multiple_choice', '「〜ほど」의 의미로 올바른 것은?', '〜ほど(ほど)는 ''~만큼, ~정도''라는 뜻의 N4 표현입니다.', 1, 36, 'N4', 'vocab', true),
  ('b0000001-0000-4000-a000-000000200200', 'a0000001-0000-4000-a000-00000000001e', 'multiple_choice', '「〜ために」의 의미로 올바른 것은?', '〜ために(ために)는 ''~을 위해''라는 뜻의 N4 표현입니다.', 1, 37, 'N4', 'vocab', true),
  ('b0000001-0000-4000-a000-000000200201', 'a0000001-0000-4000-a000-00000000001e', 'multiple_choice', '「〜について」의 의미로 올바른 것은?', '〜について(について)는 ''~에 대해''라는 뜻의 N4 표현입니다.', 1, 38, 'N4', 'vocab', true),
  ('b0000001-0000-4000-a000-000000200202', 'a0000001-0000-4000-a000-00000000001e', 'multiple_choice', '「〜によって」의 의미로 올바른 것은?', '〜によって(によって)는 ''~에 의해, ~에 따라''라는 뜻의 N4 표현입니다.', 1, 39, 'N4', 'vocab', true),
  ('b0000001-0000-4000-a000-000000200203', 'a0000001-0000-4000-a000-00000000001e', 'multiple_choice', '「〜として」의 의미로 올바른 것은?', '〜として(として)는 ''~로서''라는 뜻의 N4 표현입니다.', 1, 40, 'N4', 'vocab', true),
  ('b0000001-0000-4000-a000-000000200204', 'a0000001-0000-4000-a000-00000000001e', 'multiple_choice', '「〜ようだ」의 의미로 올바른 것은?', '〜ようだ(ようだ)는 ''~인 것 같다''라는 뜻의 N4 표현입니다.', 1, 41, 'N4', 'vocab', true),
  ('b0000001-0000-4000-a000-000000200205', 'a0000001-0000-4000-a000-00000000001e', 'multiple_choice', '「〜らしい」의 의미로 올바른 것은?', '〜らしい(らしい)는 ''~인 것 같다, ~답다''라는 뜻의 N4 표현입니다.', 1, 42, 'N4', 'vocab', true),
  ('b0000001-0000-4000-a000-000000200206', 'a0000001-0000-4000-a000-00000000001e', 'multiple_choice', '「〜みたいだ」의 의미로 올바른 것은?', '〜みたいだ(みたいだ)는 ''~같다, ~처럼''라는 뜻의 N4 표현입니다.', 1, 43, 'N4', 'vocab', true),
  ('b0000001-0000-4000-a000-000000200207', 'a0000001-0000-4000-a000-00000000001e', 'multiple_choice', '「お疲れ様」의 의미로 올바른 것은?', 'お疲れ様(おつかれさま)는 ''수고하셨습니다''라는 뜻의 N4 표현입니다.', 1, 44, 'N4', 'vocab', true);

