  ('b0000001-0000-4000-a000-000000200208', 'a0000001-0000-4000-a000-00000000001f', 'multiple_choice', '「応じる」의 의미로 올바른 것은?', '応じる(おうじる)는 ''응하다''라는 뜻의 N3 동사입니다.', 1, 1, 'N3', 'vocab', true),
  ('b0000001-0000-4000-a000-000000200209', 'a0000001-0000-4000-a000-00000000001f', 'multiple_choice', '「求める」의 의미로 올바른 것은?', '求める(もとめる)는 ''구하다, 요구하다''라는 뜻의 N3 동사입니다.', 1, 2, 'N3', 'vocab', true),
  ('b0000001-0000-4000-a000-00000020020a', 'a0000001-0000-4000-a000-00000000001f', 'multiple_choice', '「認める」의 의미로 올바른 것은?', '認める(みとめる)는 ''인정하다''라는 뜻의 N3 동사입니다.', 1, 3, 'N3', 'vocab', true),
  ('b0000001-0000-4000-a000-00000020020b', 'a0000001-0000-4000-a000-00000000001f', 'multiple_choice', '「示す」의 의미로 올바른 것은?', '示す(しめす)는 ''나타내다, 보여주다''라는 뜻의 N3 동사입니다.', 1, 4, 'N3', 'vocab', true),
  ('b0000001-0000-4000-a000-00000020020c', 'a0000001-0000-4000-a000-00000000001f', 'multiple_choice', '「含む」의 의미로 올바른 것은?', '含む(ふくむ)는 ''포함하다''라는 뜻의 N3 동사입니다.', 1, 5, 'N3', 'vocab', true),
  ('b0000001-0000-4000-a000-00000020020d', 'a0000001-0000-4000-a000-00000000001f', 'multiple_choice', '「与える」의 의미로 올바른 것은?', '与える(あたえる)는 ''주다, 부여하다''라는 뜻의 N3 동사입니다.', 1, 6, 'N3', 'vocab', true),
  ('b0000001-0000-4000-a000-00000020020e', 'a0000001-0000-4000-a000-00000000001f', 'multiple_choice', '「得る」의 의미로 올바른 것은?', '得る(える)는 ''얻다''라는 뜻의 N3 동사입니다.', 1, 7, 'N3', 'vocab', true),
  ('b0000001-0000-4000-a000-00000020020f', 'a0000001-0000-4000-a000-00000000001f', 'multiple_choice', '「生じる」의 의미로 올바른 것은?', '生じる(しょうじる)는 ''발생하다''라는 뜻의 N3 동사입니다.', 1, 8, 'N3', 'vocab', true),
  ('b0000001-0000-4000-a000-000000200210', 'a0000001-0000-4000-a000-00000000001f', 'multiple_choice', '「占める」의 의미로 올바른 것은?', '占める(しめる)는 ''차지하다''라는 뜻의 N3 동사입니다.', 1, 9, 'N3', 'vocab', true),
  ('b0000001-0000-4000-a000-000000200211', 'a0000001-0000-4000-a000-00000000001f', 'multiple_choice', '「届ける」의 의미로 올바른 것은?', '届ける(とどける)는 ''전달하다, 배달하다''라는 뜻의 N3 동사입니다.', 1, 10, 'N3', 'vocab', true),
  ('b0000001-0000-4000-a000-000000200212', 'a0000001-0000-4000-a000-00000000001f', 'multiple_choice', '「届く」의 의미로 올바른 것은?', '届く(とどく)는 ''닿다, 도착하다''라는 뜻의 N3 동사입니다.', 1, 11, 'N3', 'vocab', true),
  ('b0000001-0000-4000-a000-000000200213', 'a0000001-0000-4000-a000-00000000001f', 'multiple_choice', '「伝える」의 의미로 올바른 것은?', '伝える(つたえる)는 ''전하다''라는 뜻의 N3 동사입니다.', 1, 12, 'N3', 'vocab', true),
  ('b0000001-0000-4000-a000-000000200214', 'a0000001-0000-4000-a000-00000000001f', 'multiple_choice', '「伝わる」의 의미로 올바른 것은?', '伝わる(つたわる)는 ''전해지다''라는 뜻의 N3 동사입니다.', 1, 13, 'N3', 'vocab', true),
  ('b0000001-0000-4000-a000-000000200215', 'a0000001-0000-4000-a000-00000000001f', 'multiple_choice', '「過ごす」의 의미로 올바른 것은?', '過ごす(すごす)는 ''보내다, 지내다''라는 뜻의 N3 동사입니다.', 1, 14, 'N3', 'vocab', true),
  ('b0000001-0000-4000-a000-000000200216', 'a0000001-0000-4000-a000-00000000001f', 'multiple_choice', '「通う」의 의미로 올바른 것은?', '通う(かよう)는 ''다니다''라는 뜻의 N3 동사입니다.', 1, 15, 'N3', 'vocab', true),
  ('b0000001-0000-4000-a000-000000200217', 'a0000001-0000-4000-a000-00000000001f', 'multiple_choice', '「通る」의 의미로 올바른 것은?', '通る(とおる)는 ''지나다, 통과하다''라는 뜻의 N3 동사입니다.', 1, 16, 'N3', 'vocab', true),
  ('b0000001-0000-4000-a000-000000200218', 'a0000001-0000-4000-a000-00000000001f', 'multiple_choice', '「通す」의 의미로 올바른 것은?', '通す(とおす)는 ''통과시키다''라는 뜻의 N3 동사입니다.', 1, 17, 'N3', 'vocab', true),
  ('b0000001-0000-4000-a000-000000200219', 'a0000001-0000-4000-a000-00000000001f', 'multiple_choice', '「勤める」의 의미로 올바른 것은?', '勤める(つとめる)는 ''근무하다''라는 뜻의 N3 동사입니다.', 1, 18, 'N3', 'vocab', true),
  ('b0000001-0000-4000-a000-00000020021a', 'a0000001-0000-4000-a000-00000000001f', 'multiple_choice', '「努める」의 의미로 올바른 것은?', '努める(つとめる)는 ''노력하다''라는 뜻의 N3 동사입니다.', 1, 19, 'N3', 'vocab', true),
  ('b0000001-0000-4000-a000-00000020021b', 'a0000001-0000-4000-a000-00000000001f', 'multiple_choice', '「向かう」의 의미로 올바른 것은?', '向かう(むかう)는 ''향하다''라는 뜻의 N3 동사입니다.', 1, 20, 'N3', 'vocab', true),
  ('b0000001-0000-4000-a000-00000020021c', 'a0000001-0000-4000-a000-00000000001f', 'multiple_choice', '「向ける」의 의미로 올바른 것은?', '向ける(むける)는 ''향하게 하다''라는 뜻의 N3 동사입니다.', 1, 21, 'N3', 'vocab', true),
  ('b0000001-0000-4000-a000-00000020021d', 'a0000001-0000-4000-a000-00000000001f', 'multiple_choice', '「迎える」의 의미로 올바른 것은?', '迎える(むかえる)는 ''맞이하다''라는 뜻의 N3 동사입니다.', 1, 22, 'N3', 'vocab', true),
  ('b0000001-0000-4000-a000-00000020021e', 'a0000001-0000-4000-a000-00000000001f', 'multiple_choice', '「育てる」의 의미로 올바른 것은?', '育てる(そだてる)는 ''기르다, 키우다''라는 뜻의 N3 동사입니다.', 1, 23, 'N3', 'vocab', true),
  ('b0000001-0000-4000-a000-00000020021f', 'a0000001-0000-4000-a000-00000000001f', 'multiple_choice', '「育つ」의 의미로 올바른 것은?', '育つ(そだつ)는 ''자라다''라는 뜻의 N3 동사입니다.', 1, 24, 'N3', 'vocab', true),
  ('b0000001-0000-4000-a000-000000200220', 'a0000001-0000-4000-a000-00000000001f', 'multiple_choice', '「経つ」의 의미로 올바른 것은?', '経つ(たつ)는 ''(시간이) 지나다''라는 뜻의 N3 동사입니다.', 1, 25, 'N3', 'vocab', true),
  ('b0000001-0000-4000-a000-000000200221', 'a0000001-0000-4000-a000-00000000001f', 'multiple_choice', '「経験する」의 의미로 올바른 것은?', '経験する(けいけんする)는 ''경험하다''라는 뜻의 N3 동사입니다.', 1, 26, 'N3', 'vocab', true),
  ('b0000001-0000-4000-a000-000000200222', 'a0000001-0000-4000-a000-00000000001f', 'multiple_choice', '「比べる」의 의미로 올바른 것은?', '比べる(くらべる)는 ''비교하다''라는 뜻의 N3 동사입니다.', 1, 27, 'N3', 'vocab', true),
  ('b0000001-0000-4000-a000-000000200223', 'a0000001-0000-4000-a000-00000000001f', 'multiple_choice', '「確認する」의 의미로 올바른 것은?', '確認する(かくにんする)는 ''확인하다''라는 뜻의 N3 동사입니다.', 1, 28, 'N3', 'vocab', true),
  ('b0000001-0000-4000-a000-000000200224', 'a0000001-0000-4000-a000-00000000001f', 'multiple_choice', '「参加する」의 의미로 올바른 것은?', '参加する(さんかする)는 ''참가하다''라는 뜻의 N3 동사입니다.', 1, 29, 'N3', 'vocab', true),
  ('b0000001-0000-4000-a000-000000200225', 'a0000001-0000-4000-a000-00000000001f', 'multiple_choice', '「紹介する」의 의미로 올바른 것은?', '紹介する(しょうかいする)는 ''소개하다''라는 뜻의 N3 동사입니다.', 1, 30, 'N3', 'vocab', true),
  ('b0000001-0000-4000-a000-000000200226', 'a0000001-0000-4000-a000-00000000001f', 'multiple_choice', '「説明する」의 의미로 올바른 것은?', '説明する(せつめいする)는 ''설명하다''라는 뜻의 N3 동사입니다.', 1, 31, 'N3', 'vocab', true),
  ('b0000001-0000-4000-a000-000000200227', 'a0000001-0000-4000-a000-00000000001f', 'multiple_choice', '「表現する」의 의미로 올바른 것은?', '表現する(ひょうげんする)는 ''표현하다''라는 뜻의 N3 동사입니다.', 1, 32, 'N3', 'vocab', true),
  ('b0000001-0000-4000-a000-000000200228', 'a0000001-0000-4000-a000-00000000001f', 'multiple_choice', '「提供する」의 의미로 올바른 것은?', '提供する(ていきょうする)는 ''제공하다''라는 뜻의 N3 동사입니다.', 1, 33, 'N3', 'vocab', true),
  ('b0000001-0000-4000-a000-000000200229', 'a0000001-0000-4000-a000-00000000001f', 'multiple_choice', '「発表する」의 의미로 올바른 것은?', '発表する(はっぴょうする)는 ''발표하다''라는 뜻의 N3 동사입니다.', 1, 34, 'N3', 'vocab', true),
  ('b0000001-0000-4000-a000-00000020022a', 'a0000001-0000-4000-a000-00000000001f', 'multiple_choice', '「活用する」의 의미로 올바른 것은?', '活用する(かつようする)는 ''활용하다''라는 뜻의 N3 동사입니다.', 1, 35, 'N3', 'vocab', true),
  ('b0000001-0000-4000-a000-00000020022b', 'a0000001-0000-4000-a000-00000000001f', 'multiple_choice', '「実施する」의 의미로 올바른 것은?', '実施する(じっしする)는 ''실시하다''라는 뜻의 N3 동사입니다.', 1, 36, 'N3', 'vocab', true),
  ('b0000001-0000-4000-a000-00000020022c', 'a0000001-0000-4000-a000-00000000001f', 'multiple_choice', '「対応する」의 의미로 올바른 것은?', '対応する(たいおうする)는 ''대응하다''라는 뜻의 N3 동사입니다.', 1, 37, 'N3', 'vocab', true),
  ('b0000001-0000-4000-a000-00000020022d', 'a0000001-0000-4000-a000-00000000001f', 'multiple_choice', '「影響する」의 의미로 올바른 것은?', '影響する(えいきょうする)는 ''영향을 끼치다''라는 뜻의 N3 동사입니다.', 1, 38, 'N3', 'vocab', true);

