-- N3 語彙テスト 第5回 (38 questions)
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES
  ('b0000001-0000-4000-a000-00000020022e', 'a0000001-0000-4000-a000-000000000020', 'multiple_choice', '「注目する」의 의미로 올바른 것은?', '注目する(ちゅうもくする)는 ''주목하다''라는 뜻의 N3 동사입니다.', 1, 1, 'N3', 'vocab', true),
  ('b0000001-0000-4000-a000-00000020022f', 'a0000001-0000-4000-a000-000000000020', 'multiple_choice', '「成長する」의 의미로 올바른 것은?', '成長する(せいちょうする)는 ''성장하다''라는 뜻의 N3 동사입니다.', 1, 2, 'N3', 'vocab', true),
  ('b0000001-0000-4000-a000-000000200230', 'a0000001-0000-4000-a000-000000000020', 'multiple_choice', '「利用する」의 의미로 올바른 것은?', '利用する(りようする)는 ''이용하다''라는 뜻의 N3 동사입니다.', 1, 3, 'N3', 'vocab', true),
  ('b0000001-0000-4000-a000-000000200231', 'a0000001-0000-4000-a000-000000000020', 'multiple_choice', '「関係する」의 의미로 올바른 것은?', '関係する(かんけいする)는 ''관계하다''라는 뜻의 N3 동사입니다.', 1, 4, 'N3', 'vocab', true),
  ('b0000001-0000-4000-a000-000000200232', 'a0000001-0000-4000-a000-000000000020', 'multiple_choice', '「連絡する」의 의미로 올바른 것은?', '連絡する(れんらくする)는 ''연락하다''라는 뜻의 N3 동사입니다.', 1, 5, 'N3', 'vocab', true),
  ('b0000001-0000-4000-a000-000000200233', 'a0000001-0000-4000-a000-000000000020', 'multiple_choice', '「準備する」의 의미로 올바른 것은?', '準備する(じゅんびする)는 ''준비하다''라는 뜻의 N3 동사입니다.', 1, 6, 'N3', 'vocab', true),
  ('b0000001-0000-4000-a000-000000200234', 'a0000001-0000-4000-a000-000000000020', 'multiple_choice', '「検討する」의 의미로 올바른 것은?', '検討する(けんとうする)는 ''검토하다''라는 뜻의 N3 동사입니다.', 1, 7, 'N3', 'vocab', true),
  ('b0000001-0000-4000-a000-000000200235', 'a0000001-0000-4000-a000-000000000020', 'multiple_choice', '「判断する」의 의미로 올바른 것은?', '判断する(はんだんする)는 ''판단하다''라는 뜻의 N3 동사입니다.', 1, 8, 'N3', 'vocab', true),
  ('b0000001-0000-4000-a000-000000200236', 'a0000001-0000-4000-a000-000000000020', 'multiple_choice', '「完成する」의 의미로 올바른 것은?', '完成する(かんせいする)는 ''완성하다''라는 뜻의 N3 동사입니다.', 1, 9, 'N3', 'vocab', true),
  ('b0000001-0000-4000-a000-000000200237', 'a0000001-0000-4000-a000-000000000020', 'multiple_choice', '「改善する」의 의미로 올바른 것은?', '改善する(かいぜんする)는 ''개선하다''라는 뜻의 N3 동사입니다.', 1, 10, 'N3', 'vocab', true),
  ('b0000001-0000-4000-a000-000000200238', 'a0000001-0000-4000-a000-000000000020', 'multiple_choice', '「達成する」의 의미로 올바른 것은?', '達成する(たっせいする)는 ''달성하다''라는 뜻의 N3 동사입니다.', 1, 11, 'N3', 'vocab', true),
  ('b0000001-0000-4000-a000-000000200239', 'a0000001-0000-4000-a000-000000000020', 'multiple_choice', '「増加する」의 의미로 올바른 것은?', '増加する(ぞうかする)는 ''증가하다''라는 뜻의 N3 동사입니다.', 1, 12, 'N3', 'vocab', true),
  ('b0000001-0000-4000-a000-00000020023a', 'a0000001-0000-4000-a000-000000000020', 'multiple_choice', '「減少する」의 의미로 올바른 것은?', '減少する(げんしょうする)는 ''감소하다''라는 뜻의 N3 동사입니다.', 1, 13, 'N3', 'vocab', true),
  ('b0000001-0000-4000-a000-00000020023b', 'a0000001-0000-4000-a000-000000000020', 'multiple_choice', '「報告する」의 의미로 올바른 것은?', '報告する(ほうこくする)는 ''보고하다''라는 뜻의 N3 동사입니다.', 1, 14, 'N3', 'vocab', true),
  ('b0000001-0000-4000-a000-00000020023c', 'a0000001-0000-4000-a000-000000000020', 'multiple_choice', '「相談する」의 의미로 올바른 것은?', '相談する(そうだんする)는 ''상담하다''라는 뜻의 N3 동사입니다.', 1, 15, 'N3', 'vocab', true),
  ('b0000001-0000-4000-a000-00000020023d', 'a0000001-0000-4000-a000-000000000020', 'multiple_choice', '「調査する」의 의미로 올바른 것은?', '調査する(ちょうさする)는 ''조사하다''라는 뜻의 N3 동사입니다.', 1, 16, 'N3', 'vocab', true),
  ('b0000001-0000-4000-a000-00000020023e', 'a0000001-0000-4000-a000-000000000020', 'multiple_choice', '「維持する」의 의미로 올바른 것은?', '維持する(いじする)는 ''유지하다''라는 뜻의 N3 동사입니다.', 1, 17, 'N3', 'vocab', true),
  ('b0000001-0000-4000-a000-00000020023f', 'a0000001-0000-4000-a000-000000000020', 'multiple_choice', '「幅広い」의 의미로 올바른 것은?', '幅広い(はばひろい)는 ''폭넓다''라는 뜻의 N3 い형용사입니다.', 1, 18, 'N3', 'vocab', true),
  ('b0000001-0000-4000-a000-000000200240', 'a0000001-0000-4000-a000-000000000020', 'multiple_choice', '「激しい」의 의미로 올바른 것은?', '激しい(はげしい)는 ''격렬하다, 심하다''라는 뜻의 N3 い형용사입니다.', 1, 19, 'N3', 'vocab', true),
  ('b0000001-0000-4000-a000-000000200241', 'a0000001-0000-4000-a000-000000000020', 'multiple_choice', '「著しい」의 의미로 올바른 것은?', '著しい(いちじるしい)는 ''현저하다''라는 뜻의 N3 い형용사입니다.', 1, 20, 'N3', 'vocab', true),
  ('b0000001-0000-4000-a000-000000200242', 'a0000001-0000-4000-a000-000000000020', 'multiple_choice', '「等しい」의 의미로 올바른 것은?', '等しい(ひとしい)는 ''같다, 동등하다''라는 뜻의 N3 い형용사입니다.', 1, 21, 'N3', 'vocab', true),
  ('b0000001-0000-4000-a000-000000200243', 'a0000001-0000-4000-a000-000000000020', 'multiple_choice', '「鋭い」의 의미로 올바른 것은?', '鋭い(するどい)는 ''날카롭다''라는 뜻의 N3 い형용사입니다.', 1, 22, 'N3', 'vocab', true),
  ('b0000001-0000-4000-a000-000000200244', 'a0000001-0000-4000-a000-000000000020', 'multiple_choice', '「恥ずかしい」의 의미로 올바른 것은?', '恥ずかしい(はずかしい)는 ''부끄럽다''라는 뜻의 N3 い형용사입니다.', 1, 23, 'N3', 'vocab', true),
  ('b0000001-0000-4000-a000-000000200245', 'a0000001-0000-4000-a000-000000000020', 'multiple_choice', '「悔しい」의 의미로 올바른 것은?', '悔しい(くやしい)는 ''분하다, 억울하다''라는 뜻의 N3 い형용사입니다.', 1, 24, 'N3', 'vocab', true),
  ('b0000001-0000-4000-a000-000000200246', 'a0000001-0000-4000-a000-000000000020', 'multiple_choice', '「素晴らしい」의 의미로 올바른 것은?', '素晴らしい(すばらしい)는 ''훌륭하다''라는 뜻의 N3 い형용사입니다.', 1, 25, 'N3', 'vocab', true),
  ('b0000001-0000-4000-a000-000000200247', 'a0000001-0000-4000-a000-000000000020', 'multiple_choice', '「珍しい」의 의미로 올바른 것은?', '珍しい(めずらしい)는 ''드물다, 진귀하다''라는 뜻의 N3 い형용사입니다.', 1, 26, 'N3', 'vocab', true),
  ('b0000001-0000-4000-a000-000000200248', 'a0000001-0000-4000-a000-000000000020', 'multiple_choice', '「望ましい」의 의미로 올바른 것은?', '望ましい(のぞましい)는 ''바람직하다''라는 뜻의 N3 い형용사입니다.', 1, 27, 'N3', 'vocab', true),
  ('b0000001-0000-4000-a000-000000200249', 'a0000001-0000-4000-a000-000000000020', 'multiple_choice', '「詳しい」의 의미로 올바른 것은?', '詳しい(くわしい)는 ''자세하다, 상세하다''라는 뜻의 N3 い형용사입니다.', 1, 28, 'N3', 'vocab', true),
  ('b0000001-0000-4000-a000-00000020024a', 'a0000001-0000-4000-a000-000000000020', 'multiple_choice', '「正しい」의 의미로 올바른 것은?', '正しい(ただしい)는 ''올바르다''라는 뜻의 N3 い형용사입니다.', 1, 29, 'N3', 'vocab', true),
  ('b0000001-0000-4000-a000-00000020024b', 'a0000001-0000-4000-a000-000000000020', 'multiple_choice', '「厳しい」의 의미로 올바른 것은?', '厳しい(きびしい)는 ''엄격하다, 어렵다''라는 뜻의 N3 い형용사입니다.', 1, 30, 'N3', 'vocab', true),
  ('b0000001-0000-4000-a000-00000020024c', 'a0000001-0000-4000-a000-000000000020', 'multiple_choice', '「乏しい」의 의미로 올바른 것은?', '乏しい(とぼしい)는 ''부족하다, 부실하다''라는 뜻의 N3 い형용사입니다.', 1, 31, 'N3', 'vocab', true),
  ('b0000001-0000-4000-a000-00000020024d', 'a0000001-0000-4000-a000-000000000020', 'multiple_choice', '「親しい」의 의미로 올바른 것은?', '親しい(したしい)는 ''친하다''라는 뜻의 N3 い형용사입니다.', 1, 32, 'N3', 'vocab', true),
  ('b0000001-0000-4000-a000-00000020024e', 'a0000001-0000-4000-a000-000000000020', 'multiple_choice', '「苦しい」의 의미로 올바른 것은?', '苦しい(くるしい)는 ''괴롭다, 힘들다''라는 뜻의 N3 い형용사입니다.', 1, 33, 'N3', 'vocab', true),
  ('b0000001-0000-4000-a000-00000020024f', 'a0000001-0000-4000-a000-000000000020', 'multiple_choice', '「涼しい」의 의미로 올바른 것은?', '涼しい(すずしい)는 ''시원하다''라는 뜻의 N3 い형용사입니다.', 1, 34, 'N3', 'vocab', true),
  ('b0000001-0000-4000-a000-000000200250', 'a0000001-0000-4000-a000-000000000020', 'multiple_choice', '「騒がしい」의 의미로 올바른 것은?', '騒がしい(さわがしい)는 ''시끄럽다''라는 뜻의 N3 い형용사입니다.', 1, 35, 'N3', 'vocab', true),
  ('b0000001-0000-4000-a000-000000200251', 'a0000001-0000-4000-a000-000000000020', 'multiple_choice', '「柔らかい」의 의미로 올바른 것은?', '柔らかい(やわらかい)는 ''부드럽다''라는 뜻의 N3 い형용사입니다.', 1, 36, 'N3', 'vocab', true),
  ('b0000001-0000-4000-a000-000000200252', 'a0000001-0000-4000-a000-000000000020', 'multiple_choice', '「疑わしい」의 의미로 올바른 것은?', '疑わしい(うたがわしい)는 ''의심스럽다''라는 뜻의 N3 い형용사입니다.', 1, 37, 'N3', 'vocab', true),
  ('b0000001-0000-4000-a000-000000200253', 'a0000001-0000-4000-a000-000000000020', 'multiple_choice', '「豊か」의 의미로 올바른 것은?', '豊か(ゆたか)는 ''풍부하다, 풍요롭다''라는 뜻의 N3 な형용사입니다.', 1, 38, 'N3', 'vocab', true);

