  ('b0000001-0000-4000-a000-000000200254', 'a0000001-0000-4000-a000-000000000021', 'multiple_choice', '「明らか」의 의미로 올바른 것은?', '明らか(あきらか)는 ''명백하다, 분명하다''라는 뜻의 N3 な형용사입니다.', 1, 1, 'N3', 'vocab', true),
