  ('b0000001-0000-4000-a000-000000200256', 'a0000001-0000-4000-a000-000000000021', 'multiple_choice', '「重大」의 의미로 올바른 것은?', '重大(じゅうだい)는 ''중대하다''라는 뜻의 N3 な형용사입니다.', 1, 3, 'N3', 'vocab', true),
