  ('b0000001-0000-4000-a000-000000200259', 'a0000001-0000-4000-a000-000000000021', 'multiple_choice', '「複雑」의 의미로 올바른 것은?', '複雑(ふくざつ)는 ''복잡하다''라는 뜻의 N3 な형용사입니다.', 1, 6, 'N3', 'vocab', true),
