-- N3 語彙テスト 第8回 (37 questions)
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES
  ('b0000001-0000-4000-a000-00000020029e', 'a0000001-0000-4000-a000-000000000023', 'multiple_choice', '「一般的」의 의미로 올바른 것은?', '一般的(いっぱんてき)는 ''일반적''라는 뜻의 N3 부사입니다.', 1, 1, 'N3', 'vocab', true),
  ('b0000001-0000-4000-a000-00000020029f', 'a0000001-0000-4000-a000-000000000023', 'multiple_choice', '「具体的」의 의미로 올바른 것은?', '具体的(ぐたいてき)는 ''구체적''라는 뜻의 N3 부사입니다.', 1, 2, 'N3', 'vocab', true),
  ('b0000001-0000-4000-a000-0000002002a0', 'a0000001-0000-4000-a000-000000000023', 'multiple_choice', '「比較的」의 의미로 올바른 것은?', '比較的(ひかくてき)는 ''비교적''라는 뜻의 N3 부사입니다.', 1, 3, 'N3', 'vocab', true),
  ('b0000001-0000-4000-a000-0000002002a1', 'a0000001-0000-4000-a000-000000000023', 'multiple_choice', '「徐々に」의 의미로 올바른 것은?', '徐々に(じょじょに)는 ''서서히''라는 뜻의 N3 부사입니다.', 1, 4, 'N3', 'vocab', true),
  ('b0000001-0000-4000-a000-0000002002a2', 'a0000001-0000-4000-a000-000000000023', 'multiple_choice', '「常に」의 의미로 올바른 것은?', '常に(つねに)는 ''항상''라는 뜻의 N3 부사입니다.', 1, 5, 'N3', 'vocab', true),
  ('b0000001-0000-4000-a000-0000002002a3', 'a0000001-0000-4000-a000-000000000023', 'multiple_choice', '「十分」의 의미로 올바른 것은?', '十分(じゅうぶん)는 ''충분히''라는 뜻의 N3 부사입니다.', 1, 6, 'N3', 'vocab', true),
  ('b0000001-0000-4000-a000-0000002002a4', 'a0000001-0000-4000-a000-000000000023', 'multiple_choice', '「全体」의 의미로 올바른 것은?', '全体(ぜんたい)는 ''전체''라는 뜻의 N3 부사입니다.', 1, 7, 'N3', 'vocab', true),
  ('b0000001-0000-4000-a000-0000002002a5', 'a0000001-0000-4000-a000-000000000023', 'multiple_choice', '「特に」의 의미로 올바른 것은?', '特に(とくに)는 ''특히''라는 뜻의 N3 부사입니다.', 1, 8, 'N3', 'vocab', true),
  ('b0000001-0000-4000-a000-0000002002a6', 'a0000001-0000-4000-a000-000000000023', 'multiple_choice', '「主に」의 의미로 올바른 것은?', '主に(おもに)는 ''주로''라는 뜻의 N3 부사입니다.', 1, 9, 'N3', 'vocab', true),
  ('b0000001-0000-4000-a000-0000002002a7', 'a0000001-0000-4000-a000-000000000023', 'multiple_choice', '「急に」의 의미로 올바른 것은?', '急に(きゅうに)는 ''갑자기''라는 뜻의 N3 부사입니다.', 1, 10, 'N3', 'vocab', true),
  ('b0000001-0000-4000-a000-0000002002a8', 'a0000001-0000-4000-a000-000000000023', 'multiple_choice', '「次第に」의 의미로 올바른 것은?', '次第に(しだいに)는 ''차차, 점점''라는 뜻의 N3 부사입니다.', 1, 11, 'N3', 'vocab', true),
  ('b0000001-0000-4000-a000-0000002002a9', 'a0000001-0000-4000-a000-000000000023', 'multiple_choice', '「相当」의 의미로 올바른 것은?', '相当(そうとう)는 ''상당히''라는 뜻의 N3 부사입니다.', 1, 12, 'N3', 'vocab', true),
  ('b0000001-0000-4000-a000-0000002002aa', 'a0000001-0000-4000-a000-000000000023', 'multiple_choice', '「ますます」의 의미로 올바른 것은?', 'ますます(ますます)는 ''점점 더''라는 뜻의 N3 부사입니다.', 1, 13, 'N3', 'vocab', true),
  ('b0000001-0000-4000-a000-0000002002ab', 'a0000001-0000-4000-a000-000000000023', 'multiple_choice', '「やはり」의 의미로 올바른 것은?', 'やはり(やはり)는 ''역시''라는 뜻의 N3 부사입니다.', 1, 14, 'N3', 'vocab', true),
  ('b0000001-0000-4000-a000-0000002002ac', 'a0000001-0000-4000-a000-000000000023', 'multiple_choice', '「むしろ」의 의미로 올바른 것은?', 'むしろ(むしろ)는 ''오히려''라는 뜻의 N3 부사입니다.', 1, 15, 'N3', 'vocab', true),
  ('b0000001-0000-4000-a000-0000002002ad', 'a0000001-0000-4000-a000-000000000023', 'multiple_choice', '「かなり」의 의미로 올바른 것은?', 'かなり(かなり)는 ''꽤, 상당히''라는 뜻의 N3 부사입니다.', 1, 16, 'N3', 'vocab', true),
  ('b0000001-0000-4000-a000-0000002002ae', 'a0000001-0000-4000-a000-000000000023', 'multiple_choice', '「わずか」의 의미로 올바른 것은?', 'わずか(わずか)는 ''겨우, 약간''라는 뜻의 N3 부사입니다.', 1, 17, 'N3', 'vocab', true),
  ('b0000001-0000-4000-a000-0000002002af', 'a0000001-0000-4000-a000-000000000023', 'multiple_choice', '「ただし」의 의미로 올바른 것은?', 'ただし(ただし)는 ''단, 다만''라는 뜻의 N3 접속사입니다.', 1, 18, 'N3', 'vocab', true),
  ('b0000001-0000-4000-a000-0000002002b0', 'a0000001-0000-4000-a000-000000000023', 'multiple_choice', '「したがって」의 의미로 올바른 것은?', 'したがって(したがって)는 ''따라서''라는 뜻의 N3 접속사입니다.', 1, 19, 'N3', 'vocab', true),
  ('b0000001-0000-4000-a000-0000002002b1', 'a0000001-0000-4000-a000-000000000023', 'multiple_choice', '「一方」의 의미로 올바른 것은?', '一方(いっぽう)는 ''한편''라는 뜻의 N3 접속사입니다.', 1, 20, 'N3', 'vocab', true),
  ('b0000001-0000-4000-a000-0000002002b2', 'a0000001-0000-4000-a000-000000000023', 'multiple_choice', '「それに対して」의 의미로 올바른 것은?', 'それに対して(それにたいして)는 ''그에 반해''라는 뜻의 N3 접속사입니다.', 1, 21, 'N3', 'vocab', true),
  ('b0000001-0000-4000-a000-0000002002b3', 'a0000001-0000-4000-a000-000000000023', 'multiple_choice', '「つまり」의 의미로 올바른 것은?', 'つまり(つまり)는 ''즉''라는 뜻의 N3 접속사입니다.', 1, 22, 'N3', 'vocab', true),
  ('b0000001-0000-4000-a000-0000002002b4', 'a0000001-0000-4000-a000-000000000023', 'multiple_choice', '「あらゆる」의 의미로 올바른 것은?', 'あらゆる(あらゆる)는 ''모든, 온갖''라는 뜻의 N3 연체사입니다.', 1, 23, 'N3', 'vocab', true),
  ('b0000001-0000-4000-a000-0000002002b5', 'a0000001-0000-4000-a000-000000000023', 'multiple_choice', '「わが」의 의미로 올바른 것은?', 'わが(わが)는 ''우리의, 나의''라는 뜻의 N3 연체사입니다.', 1, 24, 'N3', 'vocab', true),
  ('b0000001-0000-4000-a000-0000002002b6', 'a0000001-0000-4000-a000-000000000023', 'multiple_choice', '「ある」의 의미로 올바른 것은?', 'ある(ある)는 ''어떤''라는 뜻의 N3 연체사입니다.', 1, 25, 'N3', 'vocab', true),
  ('b0000001-0000-4000-a000-0000002002b7', 'a0000001-0000-4000-a000-000000000023', 'multiple_choice', '「各」의 의미로 올바른 것은?', '各(かく)는 ''각''라는 뜻의 N3 접두사입니다.', 1, 26, 'N3', 'vocab', true),
  ('b0000001-0000-4000-a000-0000002002b8', 'a0000001-0000-4000-a000-000000000023', 'multiple_choice', '「全」의 의미로 올바른 것은?', '全(ぜん)는 ''전, 모든''라는 뜻의 N3 접두사입니다.', 1, 27, 'N3', 'vocab', true),
  ('b0000001-0000-4000-a000-0000002002b9', 'a0000001-0000-4000-a000-000000000023', 'multiple_choice', '「約」의 의미로 올바른 것은?', '約(やく)는 ''약, 대략''라는 뜻의 N3 접두사입니다.', 1, 28, 'N3', 'vocab', true),
  ('b0000001-0000-4000-a000-0000002002ba', 'a0000001-0000-4000-a000-000000000023', 'multiple_choice', '「超」의 의미로 올바른 것은?', '超(ちょう)는 ''초, 매우''라는 뜻의 N3 접두사입니다.', 1, 29, 'N3', 'vocab', true),
  ('b0000001-0000-4000-a000-0000002002bb', 'a0000001-0000-4000-a000-000000000023', 'multiple_choice', '「的」의 의미로 올바른 것은?', '的(てき)는 ''~적''라는 뜻의 N3 접미사입니다.', 1, 30, 'N3', 'vocab', true),
  ('b0000001-0000-4000-a000-0000002002bc', 'a0000001-0000-4000-a000-000000000023', 'multiple_choice', '「性」의 의미로 올바른 것은?', '性(せい)는 ''~성''라는 뜻의 N3 접미사입니다.', 1, 31, 'N3', 'vocab', true),
  ('b0000001-0000-4000-a000-0000002002bd', 'a0000001-0000-4000-a000-000000000023', 'multiple_choice', '「化」의 의미로 올바른 것은?', '化(か)는 ''~화''라는 뜻의 N3 접미사입니다.', 1, 32, 'N3', 'vocab', true),
  ('b0000001-0000-4000-a000-0000002002be', 'a0000001-0000-4000-a000-000000000023', 'multiple_choice', '「率」의 의미로 올바른 것은?', '率(りつ)는 ''~율, ~률''라는 뜻의 N3 접미사입니다.', 1, 33, 'N3', 'vocab', true),
  ('b0000001-0000-4000-a000-0000002002bf', 'a0000001-0000-4000-a000-000000000023', 'multiple_choice', '「感」의 의미로 올바른 것은?', '感(かん)는 ''~감''라는 뜻의 N3 접미사입니다.', 1, 34, 'N3', 'vocab', true),
  ('b0000001-0000-4000-a000-0000002002c0', 'a0000001-0000-4000-a000-000000000023', 'multiple_choice', '「力」의 의미로 올바른 것은?', '力(りょく)는 ''~력''라는 뜻의 N3 접미사입니다.', 1, 35, 'N3', 'vocab', true),
  ('b0000001-0000-4000-a000-0000002002c1', 'a0000001-0000-4000-a000-000000000023', 'multiple_choice', '「量」의 의미로 올바른 것은?', '量(りょう)는 ''~량''라는 뜻의 N3 접미사입니다.', 1, 36, 'N3', 'vocab', true),
  ('b0000001-0000-4000-a000-0000002002c2', 'a0000001-0000-4000-a000-000000000023', 'multiple_choice', '「観」의 의미로 올바른 것은?', '観(かん)는 ''~관''라는 뜻의 N3 접미사입니다.', 1, 37, 'N3', 'vocab', true);

