-- N2 語彙テスト 第4回 (45 questions)
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES
  ('b0000001-0000-4000-a000-0000002002c3', 'a0000001-0000-4000-a000-000000000024', 'multiple_choice', '「怒る」의 의미로 올바른 것은?', '怒る(おこる)는 ''화내다''라는 뜻의 N2 동사입니다.', 1, 1, 'N2', 'vocab', true),
  ('b0000001-0000-4000-a000-0000002002c4', 'a0000001-0000-4000-a000-000000000024', 'multiple_choice', '「驚く」의 의미로 올바른 것은?', '驚く(おどろく)는 ''놀라다''라는 뜻의 N2 동사입니다.', 1, 2, 'N2', 'vocab', true),
  ('b0000001-0000-4000-a000-0000002002c5', 'a0000001-0000-4000-a000-000000000024', 'multiple_choice', '「悩む」의 의미로 올바른 것은?', '悩む(なやむ)는 ''고민하다''라는 뜻의 N2 동사입니다.', 1, 3, 'N2', 'vocab', true),
  ('b0000001-0000-4000-a000-0000002002c6', 'a0000001-0000-4000-a000-000000000024', 'multiple_choice', '「諦める」의 의미로 올바른 것은?', '諦める(あきらめる)는 ''포기하다''라는 뜻의 N2 동사입니다.', 1, 4, 'N2', 'vocab', true),
  ('b0000001-0000-4000-a000-0000002002c7', 'a0000001-0000-4000-a000-000000000024', 'multiple_choice', '「努力する」의 의미로 올바른 것은?', '努力する(どりょくする)는 ''노력하다''라는 뜻의 N2 동사입니다.', 1, 5, 'N2', 'vocab', true),
  ('b0000001-0000-4000-a000-0000002002c8', 'a0000001-0000-4000-a000-000000000024', 'multiple_choice', '「経験する」의 의미로 올바른 것은?', '経験する(けいけんする)는 ''경험하다''라는 뜻의 N2 동사입니다.', 1, 6, 'N2', 'vocab', true),
  ('b0000001-0000-4000-a000-0000002002c9', 'a0000001-0000-4000-a000-000000000024', 'multiple_choice', '「失敗する」의 의미로 올바른 것은?', '失敗する(しっぱいする)는 ''실패하다''라는 뜻의 N2 동사입니다.', 1, 7, 'N2', 'vocab', true),
  ('b0000001-0000-4000-a000-0000002002ca', 'a0000001-0000-4000-a000-000000000024', 'multiple_choice', '「競争する」의 의미로 올바른 것은?', '競争する(きょうそうする)는 ''경쟁하다''라는 뜻의 N2 동사입니다.', 1, 8, 'N2', 'vocab', true),
  ('b0000001-0000-4000-a000-0000002002cb', 'a0000001-0000-4000-a000-000000000024', 'multiple_choice', '「活用する」의 의미로 올바른 것은?', '活用する(かつようする)는 ''활용하다''라는 뜻의 N2 동사입니다.', 1, 9, 'N2', 'vocab', true),
  ('b0000001-0000-4000-a000-0000002002cc', 'a0000001-0000-4000-a000-000000000024', 'multiple_choice', '「発表する」의 의미로 올바른 것은?', '発表する(はっぴょうする)는 ''발표하다''라는 뜻의 N2 동사입니다.', 1, 10, 'N2', 'vocab', true),
  ('b0000001-0000-4000-a000-0000002002cd', 'a0000001-0000-4000-a000-000000000024', 'multiple_choice', '「主張する」의 의미로 올바른 것은?', '主張する(しゅちょうする)는 ''주장하다''라는 뜻의 N2 동사입니다.', 1, 11, 'N2', 'vocab', true),
  ('b0000001-0000-4000-a000-0000002002ce', 'a0000001-0000-4000-a000-000000000024', 'multiple_choice', '「反対する」의 의미로 올바른 것은?', '反対する(はんたいする)는 ''반대하다''라는 뜻의 N2 동사입니다.', 1, 12, 'N2', 'vocab', true),
  ('b0000001-0000-4000-a000-0000002002cf', 'a0000001-0000-4000-a000-000000000024', 'multiple_choice', '「賛成する」의 의미로 올바른 것은?', '賛成する(さんせいする)는 ''찬성하다''라는 뜻의 N2 동사입니다.', 1, 13, 'N2', 'vocab', true),
  ('b0000001-0000-4000-a000-0000002002d0', 'a0000001-0000-4000-a000-000000000024', 'multiple_choice', '「参加する」의 의미로 올바른 것은?', '参加する(さんかする)는 ''참가하다''라는 뜻의 N2 동사입니다.', 1, 14, 'N2', 'vocab', true),
  ('b0000001-0000-4000-a000-0000002002d1', 'a0000001-0000-4000-a000-000000000024', 'multiple_choice', '「対応する」의 의미로 올바른 것은?', '対応する(たいおうする)는 ''대응하다''라는 뜻의 N2 동사입니다.', 1, 15, 'N2', 'vocab', true),
  ('b0000001-0000-4000-a000-0000002002d2', 'a0000001-0000-4000-a000-000000000024', 'multiple_choice', '「表現する」의 의미로 올바른 것은?', '表現する(ひょうげんする)는 ''표현하다''라는 뜻의 N2 동사입니다.', 1, 16, 'N2', 'vocab', true),
  ('b0000001-0000-4000-a000-0000002002d3', 'a0000001-0000-4000-a000-000000000024', 'multiple_choice', '「判断する」의 의미로 올바른 것은?', '判断する(はんだんする)는 ''판단하다''라는 뜻의 N2 동사입니다.', 1, 17, 'N2', 'vocab', true),
  ('b0000001-0000-4000-a000-0000002002d4', 'a0000001-0000-4000-a000-000000000024', 'multiple_choice', '「交換する」의 의미로 올바른 것은?', '交換する(こうかんする)는 ''교환하다''라는 뜻의 N2 동사입니다.', 1, 18, 'N2', 'vocab', true),
  ('b0000001-0000-4000-a000-0000002002d5', 'a0000001-0000-4000-a000-000000000024', 'multiple_choice', '「変化する」의 의미로 올바른 것은?', '変化する(へんかする)는 ''변화하다''라는 뜻의 N2 동사입니다.', 1, 19, 'N2', 'vocab', true),
  ('b0000001-0000-4000-a000-0000002002d6', 'a0000001-0000-4000-a000-000000000024', 'multiple_choice', '「説明する」의 의미로 올바른 것은?', '説明する(せつめいする)는 ''설명하다''라는 뜻의 N2 동사입니다.', 1, 20, 'N2', 'vocab', true),
  ('b0000001-0000-4000-a000-0000002002d7', 'a0000001-0000-4000-a000-000000000024', 'multiple_choice', '「証明する」의 의미로 올바른 것은?', '証明する(しょうめいする)는 ''증명하다''라는 뜻의 N2 동사입니다.', 1, 21, 'N2', 'vocab', true),
  ('b0000001-0000-4000-a000-0000002002d8', 'a0000001-0000-4000-a000-000000000024', 'multiple_choice', '「想像する」의 의미로 올바른 것은?', '想像する(そうぞうする)는 ''상상하다''라는 뜻의 N2 동사입니다.', 1, 22, 'N2', 'vocab', true),
  ('b0000001-0000-4000-a000-0000002002d9', 'a0000001-0000-4000-a000-000000000024', 'multiple_choice', '「注目する」의 의미로 올바른 것은?', '注目する(ちゅうもくする)는 ''주목하다''라는 뜻의 N2 동사입니다.', 1, 23, 'N2', 'vocab', true),
  ('b0000001-0000-4000-a000-0000002002da', 'a0000001-0000-4000-a000-000000000024', 'multiple_choice', '「予測する」의 의미로 올바른 것은?', '予測する(よそくする)는 ''예측하다''라는 뜻의 N2 동사입니다.', 1, 24, 'N2', 'vocab', true),
  ('b0000001-0000-4000-a000-0000002002db', 'a0000001-0000-4000-a000-000000000024', 'multiple_choice', '「指摘する」의 의미로 올바른 것은?', '指摘する(してきする)는 ''지적하다''라는 뜻의 N2 동사입니다.', 1, 25, 'N2', 'vocab', true),
