  ('b0000001-0000-4000-a000-0000002002dd', 'a0000001-0000-4000-a000-000000000024', 'multiple_choice', '「拡大する」의 의미로 올바른 것은?', '拡大する(かくだいする)는 ''확대하다''라는 뜻의 N2 동사입니다.', 1, 27, 'N2', 'vocab', true),
  ('b0000001-0000-4000-a000-0000002002de', 'a0000001-0000-4000-a000-000000000024', 'multiple_choice', '「縮小する」의 의미로 올바른 것은?', '縮小する(しゅくしょうする)는 ''축소하다''라는 뜻의 N2 동사입니다.', 1, 28, 'N2', 'vocab', true),
  ('b0000001-0000-4000-a000-0000002002df', 'a0000001-0000-4000-a000-000000000024', 'multiple_choice', '「増加する」의 의미로 올바른 것은?', '増加する(ぞうかする)는 ''증가하다''라는 뜻의 N2 동사입니다.', 1, 29, 'N2', 'vocab', true),
  ('b0000001-0000-4000-a000-0000002002e0', 'a0000001-0000-4000-a000-000000000024', 'multiple_choice', '「減少する」의 의미로 올바른 것은?', '減少する(げんしょうする)는 ''감소하다''라는 뜻의 N2 동사입니다.', 1, 30, 'N2', 'vocab', true),
  ('b0000001-0000-4000-a000-0000002002e1', 'a0000001-0000-4000-a000-000000000024', 'multiple_choice', '「共感する」의 의미로 올바른 것은?', '共感する(きょうかんする)는 ''공감하다''라는 뜻의 N2 동사입니다.', 1, 31, 'N2', 'vocab', true),
  ('b0000001-0000-4000-a000-0000002002e2', 'a0000001-0000-4000-a000-000000000024', 'multiple_choice', '「含める」의 의미로 올바른 것은?', '含める(ふくめる)는 ''포함시키다''라는 뜻의 N2 동사입니다.', 1, 32, 'N2', 'vocab', true),
  ('b0000001-0000-4000-a000-0000002002e3', 'a0000001-0000-4000-a000-000000000024', 'multiple_choice', '「求める」의 의미로 올바른 것은?', '求める(もとめる)는 ''요구하다, 구하다''라는 뜻의 N2 동사입니다.', 1, 33, 'N2', 'vocab', true),
  ('b0000001-0000-4000-a000-0000002002e4', 'a0000001-0000-4000-a000-000000000024', 'multiple_choice', '「与える」의 의미로 올바른 것은?', '与える(あたえる)는 ''주다, 부여하다''라는 뜻의 N2 동사입니다.', 1, 34, 'N2', 'vocab', true),
  ('b0000001-0000-4000-a000-0000002002e5', 'a0000001-0000-4000-a000-000000000024', 'multiple_choice', '「示す」의 의미로 올바른 것은?', '示す(しめす)는 ''나타내다, 보여주다''라는 뜻의 N2 동사입니다.', 1, 35, 'N2', 'vocab', true),
  ('b0000001-0000-4000-a000-0000002002e6', 'a0000001-0000-4000-a000-000000000024', 'multiple_choice', '「占める」의 의미로 올바른 것은?', '占める(しめる)는 ''차지하다''라는 뜻의 N2 동사입니다.', 1, 36, 'N2', 'vocab', true),
  ('b0000001-0000-4000-a000-0000002002e7', 'a0000001-0000-4000-a000-000000000024', 'multiple_choice', '「伴う」의 의미로 올바른 것은?', '伴う(ともなう)는 ''수반하다''라는 뜻의 N2 동사입니다.', 1, 37, 'N2', 'vocab', true),
  ('b0000001-0000-4000-a000-0000002002e8', 'a0000001-0000-4000-a000-000000000024', 'multiple_choice', '「基づく」의 의미로 올바른 것은?', '基づく(もとづく)는 ''근거하다, 기초하다''라는 뜻의 N2 동사입니다.', 1, 38, 'N2', 'vocab', true),
  ('b0000001-0000-4000-a000-0000002002e9', 'a0000001-0000-4000-a000-000000000024', 'multiple_choice', '「異なる」의 의미로 올바른 것은?', '異なる(ことなる)는 ''다르다''라는 뜻의 N2 동사입니다.', 1, 39, 'N2', 'vocab', true),
  ('b0000001-0000-4000-a000-0000002002ea', 'a0000001-0000-4000-a000-000000000024', 'multiple_choice', '「満たす」의 의미로 올바른 것은?', '満たす(みたす)는 ''충족시키다, 채우다''라는 뜻의 N2 동사입니다.', 1, 40, 'N2', 'vocab', true),
  ('b0000001-0000-4000-a000-0000002002eb', 'a0000001-0000-4000-a000-000000000024', 'multiple_choice', '「生じる」의 의미로 올바른 것은?', '生じる(しょうじる)는 ''발생하다, 생기다''라는 뜻의 N2 동사입니다.', 1, 41, 'N2', 'vocab', true),
  ('b0000001-0000-4000-a000-0000002002ec', 'a0000001-0000-4000-a000-000000000024', 'multiple_choice', '「応じる」의 의미로 올바른 것은?', '応じる(おうじる)는 ''응하다''라는 뜻의 N2 동사입니다.', 1, 42, 'N2', 'vocab', true),
  ('b0000001-0000-4000-a000-0000002002ed', 'a0000001-0000-4000-a000-000000000024', 'multiple_choice', '「果たす」의 의미로 올바른 것은?', '果たす(はたす)는 ''이루다, 수행하다''라는 뜻의 N2 동사입니다.', 1, 43, 'N2', 'vocab', true),
  ('b0000001-0000-4000-a000-0000002002ee', 'a0000001-0000-4000-a000-000000000024', 'multiple_choice', '「抱える」의 의미로 올바른 것은?', '抱える(かかえる)는 ''떠안다, 안고 있다''라는 뜻의 N2 동사입니다.', 1, 44, 'N2', 'vocab', true),
  ('b0000001-0000-4000-a000-0000002002ef', 'a0000001-0000-4000-a000-000000000024', 'multiple_choice', '「覆す」의 의미로 올바른 것은?', '覆す(くつがえす)는 ''뒤집다, 覆す''라는 뜻의 N2 동사입니다.', 1, 45, 'N2', 'vocab', true);

