-- N2 語彙テスト 第5回 (45 questions)
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES
  ('b0000001-0000-4000-a000-0000002002f0', 'a0000001-0000-4000-a000-000000000025', 'multiple_choice', '「補う」의 의미로 올바른 것은?', '補う(おぎなう)는 ''보충하다, 보완하다''라는 뜻의 N2 동사입니다.', 1, 1, 'N2', 'vocab', true),
  ('b0000001-0000-4000-a000-0000002002f1', 'a0000001-0000-4000-a000-000000000025', 'multiple_choice', '「妨げる」의 의미로 올바른 것은?', '妨げる(さまたげる)는 ''방해하다''라는 뜻의 N2 동사입니다.', 1, 2, 'N2', 'vocab', true),
  ('b0000001-0000-4000-a000-0000002002f2', 'a0000001-0000-4000-a000-000000000025', 'multiple_choice', '「恐れる」의 의미로 올바른 것은?', '恐れる(おそれる)는 ''두려워하다''라는 뜻의 N2 동사입니다.', 1, 3, 'N2', 'vocab', true),
  ('b0000001-0000-4000-a000-0000002002f3', 'a0000001-0000-4000-a000-000000000025', 'multiple_choice', '「優れる」의 의미로 올바른 것은?', '優れる(すぐれる)는 ''뛰어나다''라는 뜻의 N2 동사입니다.', 1, 4, 'N2', 'vocab', true),
  ('b0000001-0000-4000-a000-0000002002f4', 'a0000001-0000-4000-a000-000000000025', 'multiple_choice', '「溢れる」의 의미로 올바른 것은?', '溢れる(あふれる)는 ''넘치다''라는 뜻의 N2 동사입니다.', 1, 5, 'N2', 'vocab', true),
  ('b0000001-0000-4000-a000-0000002002f5', 'a0000001-0000-4000-a000-000000000025', 'multiple_choice', '「振り返る」의 의미로 올바른 것은?', '振り返る(ふりかえる)는 ''되돌아보다''라는 뜻의 N2 동사입니다.', 1, 6, 'N2', 'vocab', true),
  ('b0000001-0000-4000-a000-0000002002f6', 'a0000001-0000-4000-a000-000000000025', 'multiple_choice', '「見直す」의 의미로 올바른 것은?', '見直す(みなおす)는 ''재검토하다''라는 뜻의 N2 동사입니다.', 1, 7, 'N2', 'vocab', true),
  ('b0000001-0000-4000-a000-0000002002f7', 'a0000001-0000-4000-a000-000000000025', 'multiple_choice', '「取り組む」의 의미로 올바른 것은?', '取り組む(とりくむ)는 ''몰두하다, 임하다''라는 뜻의 N2 동사입니다.', 1, 8, 'N2', 'vocab', true),
  ('b0000001-0000-4000-a000-0000002002f8', 'a0000001-0000-4000-a000-000000000025', 'multiple_choice', '「思い込む」의 의미로 올바른 것은?', '思い込む(おもいこむ)는 ''확신하다, 믿어버리다''라는 뜻의 N2 동사입니다.', 1, 9, 'N2', 'vocab', true),
  ('b0000001-0000-4000-a000-0000002002f9', 'a0000001-0000-4000-a000-000000000025', 'multiple_choice', '「打ち込む」의 의미로 올바른 것은?', '打ち込む(うちこむ)는 ''몰두하다, 빠져들다''라는 뜻의 N2 동사입니다.', 1, 10, 'N2', 'vocab', true),
  ('b0000001-0000-4000-a000-0000002002fa', 'a0000001-0000-4000-a000-000000000025', 'multiple_choice', '「追い込む」의 의미로 올바른 것은?', '追い込む(おいこむ)는 ''몰아넣다, 궁지에 빠뜨리다''라는 뜻의 N2 동사입니다.', 1, 11, 'N2', 'vocab', true),
  ('b0000001-0000-4000-a000-0000002002fb', 'a0000001-0000-4000-a000-000000000025', 'multiple_choice', '「落ち着く」의 의미로 올바른 것은?', '落ち着く(おちつく)는 ''안정되다, 침착해지다''라는 뜻의 N2 동사입니다.', 1, 12, 'N2', 'vocab', true),
  ('b0000001-0000-4000-a000-0000002002fc', 'a0000001-0000-4000-a000-000000000025', 'multiple_choice', '「当てはまる」의 의미로 올바른 것은?', '当てはまる(あてはまる)는 ''해당하다, 들어맞다''라는 뜻의 N2 동사입니다.', 1, 13, 'N2', 'vocab', true),
  ('b0000001-0000-4000-a000-0000002002fd', 'a0000001-0000-4000-a000-000000000025', 'multiple_choice', '「見込む」의 의미로 올바른 것은?', '見込む(みこむ)는 ''예상하다, 기대하다''라는 뜻의 N2 동사입니다.', 1, 14, 'N2', 'vocab', true),
  ('b0000001-0000-4000-a000-0000002002fe', 'a0000001-0000-4000-a000-000000000025', 'multiple_choice', '「割り当てる」의 의미로 올바른 것은?', '割り当てる(わりあてる)는 ''배정하다, 할당하다''라는 뜻의 N2 동사입니다.', 1, 15, 'N2', 'vocab', true),
  ('b0000001-0000-4000-a000-0000002002ff', 'a0000001-0000-4000-a000-000000000025', 'multiple_choice', '「激しい」의 의미로 올바른 것은?', '激しい(はげしい)는 ''격렬하다, 심하다''라는 뜻의 N2 い형용사입니다.', 1, 16, 'N2', 'vocab', true),
  ('b0000001-0000-4000-a000-000000200300', 'a0000001-0000-4000-a000-000000000025', 'multiple_choice', '「恥ずかしい」의 의미로 올바른 것은?', '恥ずかしい(はずかしい)는 ''부끄럽다''라는 뜻의 N2 い형용사입니다.', 1, 17, 'N2', 'vocab', true),
  ('b0000001-0000-4000-a000-000000200301', 'a0000001-0000-4000-a000-000000000025', 'multiple_choice', '「悔しい」의 의미로 올바른 것은?', '悔しい(くやしい)는 ''분하다, 억울하다''라는 뜻의 N2 い형용사입니다.', 1, 18, 'N2', 'vocab', true),
  ('b0000001-0000-4000-a000-000000200302', 'a0000001-0000-4000-a000-000000000025', 'multiple_choice', '「著しい」의 의미로 올바른 것은?', '著しい(いちじるしい)는 ''현저하다, 두드러지다''라는 뜻의 N2 い형용사입니다.', 1, 19, 'N2', 'vocab', true),
  ('b0000001-0000-4000-a000-000000200303', 'a0000001-0000-4000-a000-000000000025', 'multiple_choice', '「乏しい」의 의미로 올바른 것은?', '乏しい(とぼしい)는 ''부족하다, 빈약하다''라는 뜻의 N2 い형용사입니다.', 1, 20, 'N2', 'vocab', true),
  ('b0000001-0000-4000-a000-000000200304', 'a0000001-0000-4000-a000-000000000025', 'multiple_choice', '「好ましい」의 의미로 올바른 것은?', '好ましい(このましい)는 ''바람직하다, 호감이 가다''라는 뜻의 N2 い형용사입니다.', 1, 21, 'N2', 'vocab', true),
  ('b0000001-0000-4000-a000-000000200305', 'a0000001-0000-4000-a000-000000000025', 'multiple_choice', '「頼もしい」의 의미로 올바른 것은?', '頼もしい(たのもしい)는 ''든든하다, 믿음직하다''라는 뜻의 N2 い형용사입니다.', 1, 22, 'N2', 'vocab', true),
  ('b0000001-0000-4000-a000-000000200306', 'a0000001-0000-4000-a000-000000000025', 'multiple_choice', '「勇ましい」의 의미로 올바른 것은?', '勇ましい(いさましい)는 ''용감하다''라는 뜻의 N2 い형용사입니다.', 1, 23, 'N2', 'vocab', true),
  ('b0000001-0000-4000-a000-000000200307', 'a0000001-0000-4000-a000-000000000025', 'multiple_choice', '「騒がしい」의 의미로 올바른 것은?', '騒がしい(さわがしい)는 ''시끄럽다, 소란스럽다''라는 뜻의 N2 い형용사입니다.', 1, 24, 'N2', 'vocab', true),
  ('b0000001-0000-4000-a000-000000200308', 'a0000001-0000-4000-a000-000000000025', 'multiple_choice', '「慌ただしい」의 의미로 올바른 것은?', '慌ただしい(あわただしい)는 ''분주하다, 바쁘다''라는 뜻의 N2 い형용사입니다.', 1, 25, 'N2', 'vocab', true),
  ('b0000001-0000-4000-a000-000000200309', 'a0000001-0000-4000-a000-000000000025', 'multiple_choice', '「空しい」의 의미로 올바른 것은?', '空しい(むなしい)는 ''허무하다, 공허하다''라는 뜻의 N2 い형용사입니다.', 1, 26, 'N2', 'vocab', true),
  ('b0000001-0000-4000-a000-00000020030a', 'a0000001-0000-4000-a000-000000000025', 'multiple_choice', '「鋭い」의 의미로 올바른 것은?', '鋭い(するどい)는 ''날카롭다, 예리하다''라는 뜻의 N2 い형용사입니다.', 1, 27, 'N2', 'vocab', true),
  ('b0000001-0000-4000-a000-00000020030b', 'a0000001-0000-4000-a000-000000000025', 'multiple_choice', '「幼い」의 의미로 올바른 것은?', '幼い(おさない)는 ''어리다''라는 뜻의 N2 い형용사입니다.', 1, 28, 'N2', 'vocab', true),
  ('b0000001-0000-4000-a000-00000020030c', 'a0000001-0000-4000-a000-000000000025', 'multiple_choice', '「等しい」의 의미로 올바른 것은?', '等しい(ひとしい)는 ''같다, 동등하다''라는 뜻의 N2 い형용사입니다.', 1, 29, 'N2', 'vocab', true),
  ('b0000001-0000-4000-a000-00000020030d', 'a0000001-0000-4000-a000-000000000025', 'multiple_choice', '「潔い」의 의미로 올바른 것은?', '潔い(いさぎよい)는 ''깨끗하다, 미련 없다''라는 뜻의 N2 い형용사입니다.', 1, 30, 'N2', 'vocab', true),
  ('b0000001-0000-4000-a000-00000020030e', 'a0000001-0000-4000-a000-000000000025', 'multiple_choice', '「物足りない」의 의미로 올바른 것은?', '物足りない(ものたりない)는 ''부족하다, 아쉽다''라는 뜻의 N2 い형용사입니다.', 1, 31, 'N2', 'vocab', true),
  ('b0000001-0000-4000-a000-00000020030f', 'a0000001-0000-4000-a000-000000000025', 'multiple_choice', '「情けない」의 의미로 올바른 것은?', '情けない(なさけない)는 ''한심하다, 정없다''라는 뜻의 N2 い형용사입니다.', 1, 32, 'N2', 'vocab', true),
  ('b0000001-0000-4000-a000-000000200310', 'a0000001-0000-4000-a000-000000000025', 'multiple_choice', '「やむを得ない」의 의미로 올바른 것은?', 'やむを得ない(やむをえない)는 ''어쩔 수 없다, 부득이하다''라는 뜻의 N2 い형용사입니다.', 1, 33, 'N2', 'vocab', true),
  ('b0000001-0000-4000-a000-000000200311', 'a0000001-0000-4000-a000-000000000025', 'multiple_choice', '「心強い」의 의미로 올바른 것은?', '心強い(こころづよい)는 ''마음 든든하다''라는 뜻의 N2 い형용사입니다.', 1, 34, 'N2', 'vocab', true),
  ('b0000001-0000-4000-a000-000000200312', 'a0000001-0000-4000-a000-000000000025', 'multiple_choice', '「手堅い」의 의미로 올바른 것은?', '手堅い(てがたい)는 ''확실하다, 탄탄하다''라는 뜻의 N2 い형용사입니다.', 1, 35, 'N2', 'vocab', true),
  ('b0000001-0000-4000-a000-000000200313', 'a0000001-0000-4000-a000-000000000025', 'multiple_choice', '「目覚ましい」의 의미로 올바른 것은?', '目覚ましい(めざましい)는 ''눈부시다, 놀랍다''라는 뜻의 N2 い형용사입니다.', 1, 36, 'N2', 'vocab', true),
  ('b0000001-0000-4000-a000-000000200314', 'a0000001-0000-4000-a000-000000000025', 'multiple_choice', '「紛らわしい」의 의미로 올바른 것은?', '紛らわしい(まぎらわしい)는 ''혼동하기 쉽다, 헷갈리다''라는 뜻의 N2 い형용사입니다.', 1, 37, 'N2', 'vocab', true),
  ('b0000001-0000-4000-a000-000000200315', 'a0000001-0000-4000-a000-000000000025', 'multiple_choice', '「深刻」의 의미로 올바른 것은?', '深刻(しんこく)는 ''심각하다''라는 뜻의 N2 な형용사입니다.', 1, 38, 'N2', 'vocab', true),
  ('b0000001-0000-4000-a000-000000200316', 'a0000001-0000-4000-a000-000000000025', 'multiple_choice', '「重大」의 의미로 올바른 것은?', '重大(じゅうだい)는 ''중대하다''라는 뜻의 N2 な형용사입니다.', 1, 39, 'N2', 'vocab', true),
  ('b0000001-0000-4000-a000-000000200317', 'a0000001-0000-4000-a000-000000000025', 'multiple_choice', '「膨大」의 의미로 올바른 것은?', '膨大(ぼうだい)는 ''방대하다''라는 뜻의 N2 な형용사입니다.', 1, 40, 'N2', 'vocab', true),
  ('b0000001-0000-4000-a000-000000200318', 'a0000001-0000-4000-a000-000000000025', 'multiple_choice', '「顕著」의 의미로 올바른 것은?', '顕著(けんちょ)는 ''현저하다''라는 뜻의 N2 な형용사입니다.', 1, 41, 'N2', 'vocab', true),
  ('b0000001-0000-4000-a000-000000200319', 'a0000001-0000-4000-a000-000000000025', 'multiple_choice', '「複雑」의 의미로 올바른 것은?', '複雑(ふくざつ)는 ''복잡하다''라는 뜻의 N2 な형용사입니다.', 1, 42, 'N2', 'vocab', true),
  ('b0000001-0000-4000-a000-00000020031a', 'a0000001-0000-4000-a000-000000000025', 'multiple_choice', '「単純」의 의미로 올바른 것은?', '単純(たんじゅん)는 ''단순하다''라는 뜻의 N2 な형용사입니다.', 1, 43, 'N2', 'vocab', true),
  ('b0000001-0000-4000-a000-00000020031b', 'a0000001-0000-4000-a000-000000000025', 'multiple_choice', '「正確」의 의미로 올바른 것은?', '正確(せいかく)는 ''정확하다''라는 뜻의 N2 な형용사입니다.', 1, 44, 'N2', 'vocab', true),
  ('b0000001-0000-4000-a000-00000020031c', 'a0000001-0000-4000-a000-000000000025', 'multiple_choice', '「豊富」의 의미로 올바른 것은?', '豊富(ほうふ)는 ''풍부하다''라는 뜻의 N2 な형용사입니다.', 1, 45, 'N2', 'vocab', true);

