  ('b0000001-0000-4000-a000-00000020031d', 'a0000001-0000-4000-a000-000000000026', 'multiple_choice', '「貴重」의 의미로 올바른 것은?', '貴重(きちょう)는 ''귀중하다''라는 뜻의 N2 な형용사입니다.', 1, 1, 'N2', 'vocab', true),
  ('b0000001-0000-4000-a000-00000020031e', 'a0000001-0000-4000-a000-000000000026', 'multiple_choice', '「重要」의 의미로 올바른 것은?', '重要(じゅうよう)는 ''중요하다''라는 뜻의 N2 な형용사입니다.', 1, 2, 'N2', 'vocab', true),
  ('b0000001-0000-4000-a000-00000020031f', 'a0000001-0000-4000-a000-000000000026', 'multiple_choice', '「必要」의 의미로 올바른 것은?', '必要(ひつよう)는 ''필요하다''라는 뜻의 N2 な형용사입니다.', 1, 3, 'N2', 'vocab', true),
  ('b0000001-0000-4000-a000-000000200320', 'a0000001-0000-4000-a000-000000000026', 'multiple_choice', '「効果的」의 의미로 올바른 것은?', '効果的(こうかてき)는 ''효과적이다''라는 뜻의 N2 な형용사입니다.', 1, 4, 'N2', 'vocab', true),
  ('b0000001-0000-4000-a000-000000200321', 'a0000001-0000-4000-a000-000000000026', 'multiple_choice', '「消極的」의 의미로 올바른 것은?', '消極的(しょうきょくてき)는 ''소극적이다''라는 뜻의 N2 な형용사입니다.', 1, 5, 'N2', 'vocab', true),
  ('b0000001-0000-4000-a000-000000200322', 'a0000001-0000-4000-a000-000000000026', 'multiple_choice', '「圧倒的」의 의미로 올바른 것은?', '圧倒的(あっとうてき)는 ''압도적이다''라는 뜻의 N2 な형용사입니다.', 1, 6, 'N2', 'vocab', true),
  ('b0000001-0000-4000-a000-000000200323', 'a0000001-0000-4000-a000-000000000026', 'multiple_choice', '「画期的」의 의미로 올바른 것은?', '画期的(かっきてき)는 ''획기적이다''라는 뜻의 N2 な형용사입니다.', 1, 7, 'N2', 'vocab', true),
  ('b0000001-0000-4000-a000-000000200324', 'a0000001-0000-4000-a000-000000000026', 'multiple_choice', '「慎重」의 의미로 올바른 것은?', '慎重(しんちょう)는 ''신중하다''라는 뜻의 N2 な형용사입니다.', 1, 8, 'N2', 'vocab', true),
  ('b0000001-0000-4000-a000-000000200325', 'a0000001-0000-4000-a000-000000000026', 'multiple_choice', '「柔軟」의 의미로 올바른 것은?', '柔軟(じゅうなん)는 ''유연하다''라는 뜻의 N2 な형용사입니다.', 1, 9, 'N2', 'vocab', true),
  ('b0000001-0000-4000-a000-000000200326', 'a0000001-0000-4000-a000-000000000026', 'multiple_choice', '「多様」의 의미로 올바른 것은?', '多様(たよう)는 ''다양하다''라는 뜻의 N2 な형용사입니다.', 1, 10, 'N2', 'vocab', true),
