INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES
  ('b0000001-0000-4000-a000-00000020034a', 'a0000001-0000-4000-a000-000000000027', 'multiple_choice', '「目標」의 의미로 올바른 것은?', '目標(もくひょう)는 ''목표''라는 뜻의 N2 명사입니다.', 1, 1, 'N2', 'vocab', true),
  ('b0000001-0000-4000-a000-00000020034b', 'a0000001-0000-4000-a000-000000000027', 'multiple_choice', '「手段」의 의미로 올바른 것은?', '手段(しゅだん)는 ''수단''라는 뜻의 N2 명사입니다.', 1, 2, 'N2', 'vocab', true),
  ('b0000001-0000-4000-a000-00000020034c', 'a0000001-0000-4000-a000-000000000027', 'multiple_choice', '「課題」의 의미로 올바른 것은?', '課題(かだい)는 ''과제''라는 뜻의 N2 명사입니다.', 1, 3, 'N2', 'vocab', true),
  ('b0000001-0000-4000-a000-00000020034d', 'a0000001-0000-4000-a000-000000000027', 'multiple_choice', '「実態」의 의미로 올바른 것은?', '実態(じったい)는 ''실태''라는 뜻의 N2 명사입니다.', 1, 4, 'N2', 'vocab', true),
  ('b0000001-0000-4000-a000-00000020034e', 'a0000001-0000-4000-a000-000000000027', 'multiple_choice', '「概念」의 의미로 올바른 것은?', '概念(がいねん)는 ''개념''라는 뜻의 N2 명사입니다.', 1, 5, 'N2', 'vocab', true),
  ('b0000001-0000-4000-a000-00000020034f', 'a0000001-0000-4000-a000-000000000027', 'multiple_choice', '「観点」의 의미로 올바른 것은?', '観点(かんてん)는 ''관점''라는 뜻의 N2 명사입니다.', 1, 6, 'N2', 'vocab', true),
  ('b0000001-0000-4000-a000-000000200350', 'a0000001-0000-4000-a000-000000000027', 'multiple_choice', '「視点」의 의미로 올바른 것은?', '視点(してん)는 ''시점, 관점''라는 뜻의 N2 명사입니다.', 1, 7, 'N2', 'vocab', true),
  ('b0000001-0000-4000-a000-000000200351', 'a0000001-0000-4000-a000-000000000027', 'multiple_choice', '「範囲」의 의미로 올바른 것은?', '範囲(はんい)는 ''범위''라는 뜻의 N2 명사입니다.', 1, 8, 'N2', 'vocab', true),
