  ('b0000001-0000-4000-a000-000000200353', 'a0000001-0000-4000-a000-000000000027', 'multiple_choice', '「割合」의 의미로 올바른 것은?', '割合(わりあい)는 ''비율''라는 뜻의 N2 명사입니다.', 1, 10, 'N2', 'vocab', true),
