INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES
  ('b0000001-0000-4000-a000-000000200377', 'a0000001-0000-4000-a000-000000000028', 'multiple_choice', '「体制」의 의미로 올바른 것은?', '体制(たいせい)는 ''체제''라는 뜻의 N2 명사입니다.', 1, 1, 'N2', 'vocab', true),
  ('b0000001-0000-4000-a000-000000200378', 'a0000001-0000-4000-a000-000000000028', 'multiple_choice', '「仕組み」의 의미로 올바른 것은?', '仕組み(しくみ)는 ''구조, 체계''라는 뜻의 N2 명사입니다.', 1, 2, 'N2', 'vocab', true),
  ('b0000001-0000-4000-a000-000000200379', 'a0000001-0000-4000-a000-000000000028', 'multiple_choice', '「取り組み」의 의미로 올바른 것은?', '取り組み(とりくみ)는 ''노력, 임하는 것''라는 뜻의 N2 명사입니다.', 1, 3, 'N2', 'vocab', true),
  ('b0000001-0000-4000-a000-00000020037a', 'a0000001-0000-4000-a000-000000000028', 'multiple_choice', '「実施」의 의미로 올바른 것은?', '実施(じっし)는 ''실시''라는 뜻의 N2 명사입니다.', 1, 4, 'N2', 'vocab', true),
  ('b0000001-0000-4000-a000-00000020037b', 'a0000001-0000-4000-a000-000000000028', 'multiple_choice', '「把握」의 의미로 올바른 것은?', '把握(はあく)는 ''파악''라는 뜻의 N2 명사입니다.', 1, 5, 'N2', 'vocab', true),
  ('b0000001-0000-4000-a000-00000020037c', 'a0000001-0000-4000-a000-000000000028', 'multiple_choice', '「促進」의 의미로 올바른 것은?', '促進(そくしん)는 ''촉진''라는 뜻의 N2 명사입니다.', 1, 6, 'N2', 'vocab', true),
  ('b0000001-0000-4000-a000-00000020037d', 'a0000001-0000-4000-a000-000000000028', 'multiple_choice', '「普及」의 의미로 올바른 것은?', '普及(ふきゅう)는 ''보급''라는 뜻의 N2 명사입니다.', 1, 7, 'N2', 'vocab', true),
  ('b0000001-0000-4000-a000-00000020037e', 'a0000001-0000-4000-a000-000000000028', 'multiple_choice', '「浸透」의 의미로 올바른 것은?', '浸透(しんとう)는 ''침투, 보급''라는 뜻의 N2 명사입니다.', 1, 8, 'N2', 'vocab', true),
  ('b0000001-0000-4000-a000-00000020037f', 'a0000001-0000-4000-a000-000000000028', 'multiple_choice', '「格差」의 의미로 올바른 것은?', '格差(かくさ)는 ''격차''라는 뜻의 N2 명사입니다.', 1, 9, 'N2', 'vocab', true),
  ('b0000001-0000-4000-a000-000000200380', 'a0000001-0000-4000-a000-000000000028', 'multiple_choice', '「偏見」의 의미로 올바른 것은?', '偏見(へんけん)는 ''편견''라는 뜻의 N2 명사입니다.', 1, 10, 'N2', 'vocab', true),
  ('b0000001-0000-4000-a000-000000200381', 'a0000001-0000-4000-a000-000000000028', 'multiple_choice', '「概要」의 의미로 올바른 것은?', '概要(がいよう)는 ''개요''라는 뜻의 N2 명사입니다.', 1, 11, 'N2', 'vocab', true),
  ('b0000001-0000-4000-a000-000000200382', 'a0000001-0000-4000-a000-000000000028', 'multiple_choice', '「統計」의 의미로 올바른 것은?', '統計(とうけい)는 ''통계''라는 뜻의 N2 명사입니다.', 1, 12, 'N2', 'vocab', true),
  ('b0000001-0000-4000-a000-000000200383', 'a0000001-0000-4000-a000-000000000028', 'multiple_choice', '「予算」의 의미로 올바른 것은?', '予算(よさん)는 ''예산''라는 뜻의 N2 명사입니다.', 1, 13, 'N2', 'vocab', true),
  ('b0000001-0000-4000-a000-000000200384', 'a0000001-0000-4000-a000-000000000028', 'multiple_choice', '「人材」의 의미로 올바른 것은?', '人材(じんざい)는 ''인재''라는 뜻의 N2 명사입니다.', 1, 14, 'N2', 'vocab', true),
  ('b0000001-0000-4000-a000-000000200385', 'a0000001-0000-4000-a000-000000000028', 'multiple_choice', '「雇用」의 의미로 올바른 것은?', '雇用(こよう)는 ''고용''라는 뜻의 N2 명사입니다.', 1, 15, 'N2', 'vocab', true),
  ('b0000001-0000-4000-a000-000000200386', 'a0000001-0000-4000-a000-000000000028', 'multiple_choice', '「福祉」의 의미로 올바른 것은?', '福祉(ふくし)는 ''복지''라는 뜻의 N2 명사입니다.', 1, 16, 'N2', 'vocab', true),
  ('b0000001-0000-4000-a000-000000200387', 'a0000001-0000-4000-a000-000000000028', 'multiple_choice', '「保障」의 의미로 올바른 것은?', '保障(ほしょう)는 ''보장''라는 뜻의 N2 명사입니다.', 1, 17, 'N2', 'vocab', true),
  ('b0000001-0000-4000-a000-000000200388', 'a0000001-0000-4000-a000-000000000028', 'multiple_choice', '「支援」의 의미로 올바른 것은?', '支援(しえん)는 ''지원''라는 뜻의 N2 명사입니다.', 1, 18, 'N2', 'vocab', true),
  ('b0000001-0000-4000-a000-000000200389', 'a0000001-0000-4000-a000-000000000028', 'multiple_choice', '「貢献」의 의미로 올바른 것은?', '貢献(こうけん)는 ''공헌''라는 뜻의 N2 명사입니다.', 1, 19, 'N2', 'vocab', true),
  ('b0000001-0000-4000-a000-00000020038a', 'a0000001-0000-4000-a000-000000000028', 'multiple_choice', '「連携」의 의미로 올바른 것은?', '連携(れんけい)는 ''연계''라는 뜻의 N2 명사입니다.', 1, 20, 'N2', 'vocab', true),
  ('b0000001-0000-4000-a000-00000020038b', 'a0000001-0000-4000-a000-000000000028', 'multiple_choice', '「むしろ」의 의미로 올바른 것은?', 'むしろ(むしろ)는 ''오히려, 차라리''라는 뜻의 N2 부사입니다.', 1, 21, 'N2', 'vocab', true),
  ('b0000001-0000-4000-a000-00000020038c', 'a0000001-0000-4000-a000-000000000028', 'multiple_choice', '「かえって」의 의미로 올바른 것은?', 'かえって(かえって)는 ''오히려, 도리어''라는 뜻의 N2 부사입니다.', 1, 22, 'N2', 'vocab', true),
  ('b0000001-0000-4000-a000-00000020038d', 'a0000001-0000-4000-a000-000000000028', 'multiple_choice', '「せいぜい」의 의미로 올바른 것은?', 'せいぜい(せいぜい)는 ''기껏해야, 고작''라는 뜻의 N2 부사입니다.', 1, 23, 'N2', 'vocab', true),
  ('b0000001-0000-4000-a000-00000020038e', 'a0000001-0000-4000-a000-000000000028', 'multiple_choice', '「せめて」의 의미로 올바른 것은?', 'せめて(せめて)는 ''적어도, 최소한''라는 뜻의 N2 부사입니다.', 1, 24, 'N2', 'vocab', true),
  ('b0000001-0000-4000-a000-00000020038f', 'a0000001-0000-4000-a000-000000000028', 'multiple_choice', '「さすが」의 의미로 올바른 것은?', 'さすが(さすが)는 ''과연, 역시''라는 뜻의 N2 부사입니다.', 1, 25, 'N2', 'vocab', true),
  ('b0000001-0000-4000-a000-000000200390', 'a0000001-0000-4000-a000-000000000028', 'multiple_choice', '「いよいよ」의 의미로 올바른 것은?', 'いよいよ(いよいよ)는 ''드디어, 마침내''라는 뜻의 N2 부사입니다.', 1, 26, 'N2', 'vocab', true),
  ('b0000001-0000-4000-a000-000000200391', 'a0000001-0000-4000-a000-000000000028', 'multiple_choice', '「ますます」의 의미로 올바른 것은?', 'ますます(ますます)는 ''점점, 더욱더''라는 뜻의 N2 부사입니다.', 1, 27, 'N2', 'vocab', true),
  ('b0000001-0000-4000-a000-000000200392', 'a0000001-0000-4000-a000-000000000028', 'multiple_choice', '「わざわざ」의 의미로 올바른 것은?', 'わざわざ(わざわざ)는 ''일부러, 구태여''라는 뜻의 N2 부사입니다.', 1, 28, 'N2', 'vocab', true),
  ('b0000001-0000-4000-a000-000000200393', 'a0000001-0000-4000-a000-000000000028', 'multiple_choice', '「しばしば」의 의미로 올바른 것은?', 'しばしば(しばしば)는 ''종종, 자주''라는 뜻의 N2 부사입니다.', 1, 29, 'N2', 'vocab', true),
  ('b0000001-0000-4000-a000-000000200394', 'a0000001-0000-4000-a000-000000000028', 'multiple_choice', '「たちまち」의 의미로 올바른 것은?', 'たちまち(たちまち)는 ''순식간에, 금방''라는 뜻의 N2 부사입니다.', 1, 30, 'N2', 'vocab', true),
  ('b0000001-0000-4000-a000-000000200395', 'a0000001-0000-4000-a000-000000000028', 'multiple_choice', '「ようやく」의 의미로 올바른 것은?', 'ようやく(ようやく)는 ''겨우, 마침내''라는 뜻의 N2 부사입니다.', 1, 31, 'N2', 'vocab', true),
  ('b0000001-0000-4000-a000-000000200396', 'a0000001-0000-4000-a000-000000000028', 'multiple_choice', '「いずれ」의 의미로 올바른 것은?', 'いずれ(いずれ)는 ''머지않아, 언젠가''라는 뜻의 N2 부사입니다.', 1, 32, 'N2', 'vocab', true),
  ('b0000001-0000-4000-a000-000000200397', 'a0000001-0000-4000-a000-000000000028', 'multiple_choice', '「一応」의 의미로 올바른 것은?', '一応(いちおう)는 ''일단, 우선''라는 뜻의 N2 부사입니다.', 1, 33, 'N2', 'vocab', true),
  ('b0000001-0000-4000-a000-000000200398', 'a0000001-0000-4000-a000-000000000028', 'multiple_choice', '「一層」의 의미로 올바른 것은?', '一層(いっそう)는 ''한층, 더욱''라는 뜻의 N2 부사입니다.', 1, 34, 'N2', 'vocab', true),
  ('b0000001-0000-4000-a000-000000200399', 'a0000001-0000-4000-a000-000000000028', 'multiple_choice', '「一斉に」의 의미로 올바른 것은?', '一斉に(いっせいに)는 ''일제히''라는 뜻의 N2 부사입니다.', 1, 35, 'N2', 'vocab', true),
  ('b0000001-0000-4000-a000-00000020039a', 'a0000001-0000-4000-a000-000000000028', 'multiple_choice', '「大いに」의 의미로 올바른 것은?', '大いに(おおいに)는 ''크게, 매우''라는 뜻의 N2 부사입니다.', 1, 36, 'N2', 'vocab', true),
  ('b0000001-0000-4000-a000-00000020039b', 'a0000001-0000-4000-a000-000000000028', 'multiple_choice', '「直ちに」의 의미로 올바른 것은?', '直ちに(ただちに)는 ''즉시, 곧바로''라는 뜻의 N2 부사입니다.', 1, 37, 'N2', 'vocab', true),
  ('b0000001-0000-4000-a000-00000020039c', 'a0000001-0000-4000-a000-000000000028', 'multiple_choice', '「思わず」의 의미로 올바른 것은?', '思わず(おもわず)는 ''무심코, 자기도 모르게''라는 뜻의 N2 부사입니다.', 1, 38, 'N2', 'vocab', true),
  ('b0000001-0000-4000-a000-00000020039d', 'a0000001-0000-4000-a000-000000000028', 'multiple_choice', '「辛うじて」의 의미로 올바른 것은?', '辛うじて(かろうじて)는 ''겨우, 간신히''라는 뜻의 N2 부사입니다.', 1, 39, 'N2', 'vocab', true),
  ('b0000001-0000-4000-a000-00000020039e', 'a0000001-0000-4000-a000-000000000028', 'multiple_choice', '「概ね」의 의미로 올바른 것은?', '概ね(おおむね)는 ''대체로, 대략''라는 뜻의 N2 부사입니다.', 1, 40, 'N2', 'vocab', true),
  ('b0000001-0000-4000-a000-00000020039f', 'a0000001-0000-4000-a000-000000000028', 'multiple_choice', '「少なくとも」의 의미로 올바른 것은?', '少なくとも(すくなくとも)는 ''적어도''라는 뜻의 N2 부사입니다.', 1, 41, 'N2', 'vocab', true),
  ('b0000001-0000-4000-a000-0000002003a0', 'a0000001-0000-4000-a000-000000000028', 'multiple_choice', '「必ずしも」의 의미로 올바른 것은?', '必ずしも(かならずしも)는 ''반드시 ~은 아니다''라는 뜻의 N2 부사입니다.', 1, 42, 'N2', 'vocab', true),
  ('b0000001-0000-4000-a000-0000002003a1', 'a0000001-0000-4000-a000-000000000028', 'multiple_choice', '「極めて」의 의미로 올바른 것은?', '極めて(きわめて)는 ''극히, 매우''라는 뜻의 N2 부사입니다.', 1, 43, 'N2', 'vocab', true),
  ('b0000001-0000-4000-a000-0000002003a2', 'a0000001-0000-4000-a000-000000000028', 'multiple_choice', '「絶えず」의 의미로 올바른 것은?', '絶えず(たえず)는 ''끊임없이''라는 뜻의 N2 부사입니다.', 1, 44, 'N2', 'vocab', true),
  ('b0000001-0000-4000-a000-0000002003a3', 'a0000001-0000-4000-a000-000000000028', 'multiple_choice', '「相変わらず」의 의미로 올바른 것은?', '相変わらず(あいかわらず)는 ''여전히, 변함없이''라는 뜻의 N2 부사입니다.', 1, 45, 'N2', 'vocab', true);

