-- N2 語彙テスト 第9回 (45 questions)
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES
  ('b0000001-0000-4000-a000-0000002003a4', 'a0000001-0000-4000-a000-000000000029', 'multiple_choice', '「予め」의 의미로 올바른 것은?', '予め(あらかじめ)는 ''미리, 사전에''라는 뜻의 N2 부사입니다.', 1, 1, 'N2', 'vocab', true),
  ('b0000001-0000-4000-a000-0000002003a5', 'a0000001-0000-4000-a000-000000000029', 'multiple_choice', '「僅かに」의 의미로 올바른 것은?', '僅かに(わずかに)는 ''약간, 조금''라는 뜻의 N2 부사입니다.', 1, 2, 'N2', 'vocab', true),
  ('b0000001-0000-4000-a000-0000002003a6', 'a0000001-0000-4000-a000-000000000029', 'multiple_choice', '「徐々に」의 의미로 올바른 것은?', '徐々に(じょじょに)는 ''서서히, 점차''라는 뜻의 N2 부사입니다.', 1, 3, 'N2', 'vocab', true),
  ('b0000001-0000-4000-a000-0000002003a7', 'a0000001-0000-4000-a000-000000000029', 'multiple_choice', '「次第に」의 의미로 올바른 것은?', '次第に(しだいに)는 ''점차, 차차''라는 뜻의 N2 부사입니다.', 1, 4, 'N2', 'vocab', true),
  ('b0000001-0000-4000-a000-0000002003a8', 'a0000001-0000-4000-a000-000000000029', 'multiple_choice', '「何とか」의 의미로 올바른 것은?', '何とか(なんとか)는 ''어떻게든, 겨우''라는 뜻의 N2 부사입니다.', 1, 5, 'N2', 'vocab', true),
  ('b0000001-0000-4000-a000-0000002003a9', 'a0000001-0000-4000-a000-000000000029', 'multiple_choice', '「今にも」의 의미로 올바른 것은?', '今にも(いまにも)는 ''금방이라도, 당장이라도''라는 뜻의 N2 부사입니다.', 1, 6, 'N2', 'vocab', true),
  ('b0000001-0000-4000-a000-0000002003aa', 'a0000001-0000-4000-a000-000000000029', 'multiple_choice', '「案外」의 의미로 올바른 것은?', '案外(あんがい)는 ''의외로''라는 뜻의 N2 부사입니다.', 1, 7, 'N2', 'vocab', true),
  ('b0000001-0000-4000-a000-0000002003ab', 'a0000001-0000-4000-a000-000000000029', 'multiple_choice', '「たまたま」의 의미로 올바른 것은?', 'たまたま(たまたま)는 ''우연히''라는 뜻의 N2 부사입니다.', 1, 8, 'N2', 'vocab', true),
  ('b0000001-0000-4000-a000-0000002003ac', 'a0000001-0000-4000-a000-000000000029', 'multiple_choice', '「単に」의 의미로 올바른 것은?', '単に(たんに)는 ''단지, 단순히''라는 뜻의 N2 부사입니다.', 1, 9, 'N2', 'vocab', true),
  ('b0000001-0000-4000-a000-0000002003ad', 'a0000001-0000-4000-a000-000000000029', 'multiple_choice', '「果たして」의 의미로 올바른 것은?', '果たして(はたして)는 ''과연''라는 뜻의 N2 부사입니다.', 1, 10, 'N2', 'vocab', true),
  ('b0000001-0000-4000-a000-0000002003ae', 'a0000001-0000-4000-a000-000000000029', 'multiple_choice', '「すなわち」의 의미로 올바른 것은?', 'すなわち(すなわち)는 ''즉, 다시 말해서''라는 뜻의 N2 접속사입니다.', 1, 11, 'N2', 'vocab', true),
  ('b0000001-0000-4000-a000-0000002003af', 'a0000001-0000-4000-a000-000000000029', 'multiple_choice', '「なお」의 의미로 올바른 것은?', 'なお(なお)는 ''또한, 덧붙여''라는 뜻의 N2 접속사입니다.', 1, 12, 'N2', 'vocab', true),
  ('b0000001-0000-4000-a000-0000002003b0', 'a0000001-0000-4000-a000-000000000029', 'multiple_choice', '「ただし」의 의미로 올바른 것은?', 'ただし(ただし)는 ''단, 다만''라는 뜻의 N2 접속사입니다.', 1, 13, 'N2', 'vocab', true),
  ('b0000001-0000-4000-a000-0000002003b1', 'a0000001-0000-4000-a000-000000000029', 'multiple_choice', '「一方」의 의미로 올바른 것은?', '一方(いっぽう)는 ''한편''라는 뜻의 N2 접속사입니다.', 1, 14, 'N2', 'vocab', true),
  ('b0000001-0000-4000-a000-0000002003b2', 'a0000001-0000-4000-a000-000000000029', 'multiple_choice', '「それにしても」의 의미로 올바른 것은?', 'それにしても(それにしても)는 ''그렇다 하더라도''라는 뜻의 N2 접속사입니다.', 1, 15, 'N2', 'vocab', true),
  ('b0000001-0000-4000-a000-0000002003b3', 'a0000001-0000-4000-a000-000000000029', 'multiple_choice', '「に関して」의 의미로 올바른 것은?', 'に関して(にかんして)는 ''~에 관하여''라는 뜻의 N2 표현입니다.', 1, 16, 'N2', 'vocab', true),
  ('b0000001-0000-4000-a000-0000002003b4', 'a0000001-0000-4000-a000-000000000029', 'multiple_choice', '「に対して」의 의미로 올바른 것은?', 'に対して(にたいして)는 ''~에 대하여''라는 뜻의 N2 표현입니다.', 1, 17, 'N2', 'vocab', true),
  ('b0000001-0000-4000-a000-0000002003b5', 'a0000001-0000-4000-a000-000000000029', 'multiple_choice', '「に基づいて」의 의미로 올바른 것은?', 'に基づいて(にもとづいて)는 ''~에 근거하여''라는 뜻의 N2 표현입니다.', 1, 18, 'N2', 'vocab', true),
  ('b0000001-0000-4000-a000-0000002003b6', 'a0000001-0000-4000-a000-000000000029', 'multiple_choice', '「において」의 의미로 올바른 것은?', 'において(において)는 ''~에서, ~에 있어서''라는 뜻의 N2 표현입니다.', 1, 19, 'N2', 'vocab', true),
  ('b0000001-0000-4000-a000-0000002003b7', 'a0000001-0000-4000-a000-000000000029', 'multiple_choice', '「にとって」의 의미로 올바른 것은?', 'にとって(にとって)는 ''~에게 있어서''라는 뜻의 N2 표현입니다.', 1, 20, 'N2', 'vocab', true),
  ('b0000001-0000-4000-a000-0000002003b8', 'a0000001-0000-4000-a000-000000000029', 'multiple_choice', '「に伴って」의 의미로 올바른 것은?', 'に伴って(にともなって)는 ''~에 따라, ~와 함께''라는 뜻의 N2 표현입니다.', 1, 21, 'N2', 'vocab', true),
  ('b0000001-0000-4000-a000-0000002003b9', 'a0000001-0000-4000-a000-000000000029', 'multiple_choice', '「に応じて」의 의미로 올바른 것은?', 'に応じて(におうじて)는 ''~에 따라, ~에 응하여''라는 뜻의 N2 표현입니다.', 1, 22, 'N2', 'vocab', true),
  ('b0000001-0000-4000-a000-0000002003ba', 'a0000001-0000-4000-a000-000000000029', 'multiple_choice', '「に沿って」의 의미로 올바른 것은?', 'に沿って(にそって)는 ''~을 따라, ~에 맞게''라는 뜻의 N2 표현입니다.', 1, 23, 'N2', 'vocab', true),
  ('b0000001-0000-4000-a000-0000002003bb', 'a0000001-0000-4000-a000-000000000029', 'multiple_choice', '「をはじめ」의 의미로 올바른 것은?', 'をはじめ(をはじめ)는 ''~을 비롯하여''라는 뜻의 N2 표현입니다.', 1, 24, 'N2', 'vocab', true),
  ('b0000001-0000-4000-a000-0000002003bc', 'a0000001-0000-4000-a000-000000000029', 'multiple_choice', '「を通じて」의 의미로 올바른 것은?', 'を通じて(をつうじて)는 ''~을 통하여''라는 뜻의 N2 표현입니다.', 1, 25, 'N2', 'vocab', true),
  ('b0000001-0000-4000-a000-0000002003bd', 'a0000001-0000-4000-a000-000000000029', 'multiple_choice', '「を踏まえて」의 의미로 올바른 것은?', 'を踏まえて(をふまえて)는 ''~을 바탕으로''라는 뜻의 N2 표현입니다.', 1, 26, 'N2', 'vocab', true),
  ('b0000001-0000-4000-a000-0000002003be', 'a0000001-0000-4000-a000-000000000029', 'multiple_choice', '「に限り」의 의미로 올바른 것은?', 'に限り(にかぎり)는 ''~에 한하여''라는 뜻의 N2 표현입니다.', 1, 27, 'N2', 'vocab', true),
  ('b0000001-0000-4000-a000-0000002003bf', 'a0000001-0000-4000-a000-000000000029', 'multiple_choice', '「に反して」의 의미로 올바른 것은?', 'に反して(にはんして)는 ''~에 반하여''라는 뜻의 N2 표현입니다.', 1, 28, 'N2', 'vocab', true),
  ('b0000001-0000-4000-a000-0000002003c0', 'a0000001-0000-4000-a000-000000000029', 'multiple_choice', '「にわたって」의 의미로 올바른 것은?', 'にわたって(にわたって)는 ''~에 걸쳐''라는 뜻의 N2 표현입니다.', 1, 29, 'N2', 'vocab', true),
  ('b0000001-0000-4000-a000-0000002003c1', 'a0000001-0000-4000-a000-000000000029', 'multiple_choice', '「に先立って」의 의미로 올바른 것은?', 'に先立って(にさきだって)는 ''~에 앞서''라는 뜻의 N2 표현입니다.', 1, 30, 'N2', 'vocab', true),
  ('b0000001-0000-4000-a000-0000002003c2', 'a0000001-0000-4000-a000-000000000029', 'multiple_choice', '「とは限らない」의 의미로 올바른 것은?', 'とは限らない(とはかぎらない)는 ''반드시 ~인 것은 아니다''라는 뜻의 N2 표현입니다.', 1, 31, 'N2', 'vocab', true),
  ('b0000001-0000-4000-a000-0000002003c3', 'a0000001-0000-4000-a000-000000000029', 'multiple_choice', '「わけがない」의 의미로 올바른 것은?', 'わけがない(わけがない)는 ''~할 리가 없다''라는 뜻의 N2 표현입니다.', 1, 32, 'N2', 'vocab', true),
  ('b0000001-0000-4000-a000-0000002003c4', 'a0000001-0000-4000-a000-000000000029', 'multiple_choice', '「わけにはいかない」의 의미로 올바른 것은?', 'わけにはいかない(わけにはいかない)는 ''~할 수는 없다''라는 뜻의 N2 표현입니다.', 1, 33, 'N2', 'vocab', true),
  ('b0000001-0000-4000-a000-0000002003c5', 'a0000001-0000-4000-a000-000000000029', 'multiple_choice', '「ざるを得ない」의 의미로 올바른 것은?', 'ざるを得ない(ざるをえない)는 ''~하지 않을 수 없다''라는 뜻의 N2 표현입니다.', 1, 34, 'N2', 'vocab', true),
  ('b0000001-0000-4000-a000-0000002003c6', 'a0000001-0000-4000-a000-000000000029', 'multiple_choice', '「に違いない」의 의미로 올바른 것은?', 'に違いない(にちがいない)는 ''~임에 틀림없다''라는 뜻의 N2 표현입니다.', 1, 35, 'N2', 'vocab', true),
  ('b0000001-0000-4000-a000-0000002003c7', 'a0000001-0000-4000-a000-000000000029', 'multiple_choice', '「に過ぎない」의 의미로 올바른 것은?', 'に過ぎない(にすぎない)는 ''~에 불과하다''라는 뜻의 N2 표현입니다.', 1, 36, 'N2', 'vocab', true),
  ('b0000001-0000-4000-a000-0000002003c8', 'a0000001-0000-4000-a000-000000000029', 'multiple_choice', '「に他ならない」의 의미로 올바른 것은?', 'に他ならない(にほかならない)는 ''~에 다름 아니다''라는 뜻의 N2 표현입니다.', 1, 37, 'N2', 'vocab', true),
  ('b0000001-0000-4000-a000-0000002003c9', 'a0000001-0000-4000-a000-000000000029', 'multiple_choice', '「つつある」의 의미로 올바른 것은?', 'つつある(つつある)는 ''~하고 있는 중이다''라는 뜻의 N2 표현입니다.', 1, 38, 'N2', 'vocab', true),
  ('b0000001-0000-4000-a000-0000002003ca', 'a0000001-0000-4000-a000-000000000029', 'multiple_choice', '「一方だ」의 의미로 올바른 것은?', '一方だ(いっぽうだ)는 ''~하기만 하다''라는 뜻의 N2 표현입니다.', 1, 39, 'N2', 'vocab', true),
  ('b0000001-0000-4000-a000-0000002003cb', 'a0000001-0000-4000-a000-000000000029', 'multiple_choice', '「おそれがある」의 의미로 올바른 것은?', 'おそれがある(おそれがある)는 ''~할 우려가 있다''라는 뜻의 N2 표현입니다.', 1, 40, 'N2', 'vocab', true),
  ('b0000001-0000-4000-a000-0000002003cc', 'a0000001-0000-4000-a000-000000000029', 'multiple_choice', '「かねない」의 의미로 올바른 것은?', 'かねない(かねない)는 ''~할 수도 있다 (부정적)''라는 뜻의 N2 표현입니다.', 1, 41, 'N2', 'vocab', true),
  ('b0000001-0000-4000-a000-0000002003cd', 'a0000001-0000-4000-a000-000000000029', 'multiple_choice', '「上で」의 의미로 올바른 것은?', '上で(うえで)는 ''~하는 데 있어서''라는 뜻의 N2 표현입니다.', 1, 42, 'N2', 'vocab', true),
  ('b0000001-0000-4000-a000-0000002003ce', 'a0000001-0000-4000-a000-000000000029', 'multiple_choice', '「次第」의 의미로 올바른 것은?', '次第(しだい)는 ''~하는 대로''라는 뜻의 N2 표현입니다.', 1, 43, 'N2', 'vocab', true),
  ('b0000001-0000-4000-a000-0000002003cf', 'a0000001-0000-4000-a000-000000000029', 'multiple_choice', '「を問わず」의 의미로 올바른 것은?', 'を問わず(をとわず)는 ''~을 불문하고''라는 뜻의 N2 표현입니다.', 1, 44, 'N2', 'vocab', true),
  ('b0000001-0000-4000-a000-0000002003d0', 'a0000001-0000-4000-a000-000000000029', 'multiple_choice', '「末に」의 의미로 올바른 것은?', '末に(すえに)는 ''~한 끝에''라는 뜻의 N2 표현입니다.', 1, 45, 'N2', 'vocab', true);

