-- N1 語彙テスト 第3回 (45 questions)
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES
  ('b0000001-0000-4000-a000-0000002003d1', 'a0000001-0000-4000-a000-00000000002a', 'multiple_choice', '「施す」의 의미로 올바른 것은?', '施す(ほどこす)는 ''베풀다, 실시하다''라는 뜻의 N1 동사입니다.', 1, 1, 'N1', 'vocab', true),
  ('b0000001-0000-4000-a000-0000002003d2', 'a0000001-0000-4000-a000-00000000002a', 'multiple_choice', '「伴う」의 의미로 올바른 것은?', '伴う(ともなう)는 ''수반하다, 동반하다''라는 뜻의 N1 동사입니다.', 1, 2, 'N1', 'vocab', true),
  ('b0000001-0000-4000-a000-0000002003d3', 'a0000001-0000-4000-a000-00000000002a', 'multiple_choice', '「覆る」의 의미로 올바른 것은?', '覆る(くつがえる)는 ''뒤집히다, 번복되다''라는 뜻의 N1 동사입니다.', 1, 3, 'N1', 'vocab', true),
  ('b0000001-0000-4000-a000-0000002003d4', 'a0000001-0000-4000-a000-00000000002a', 'multiple_choice', '「見なす」의 의미로 올바른 것은?', '見なす(みなす)는 ''간주하다''라는 뜻의 N1 동사입니다.', 1, 4, 'N1', 'vocab', true),
  ('b0000001-0000-4000-a000-0000002003d5', 'a0000001-0000-4000-a000-00000000002a', 'multiple_choice', '「損なう」의 의미로 올바른 것은?', '損なう(そこなう)는 ''손상하다, 해치다''라는 뜻의 N1 동사입니다.', 1, 5, 'N1', 'vocab', true),
  ('b0000001-0000-4000-a000-0000002003d6', 'a0000001-0000-4000-a000-00000000002a', 'multiple_choice', '「潤う」의 의미로 올바른 것은?', '潤う(うるおう)는 ''윤택해지다, 촉촉해지다''라는 뜻의 N1 동사입니다.', 1, 6, 'N1', 'vocab', true),
  ('b0000001-0000-4000-a000-0000002003d7', 'a0000001-0000-4000-a000-00000000002a', 'multiple_choice', '「費やす」의 의미로 올바른 것은?', '費やす(ついやす)는 ''소비하다, 쏟다''라는 뜻의 N1 동사입니다.', 1, 7, 'N1', 'vocab', true),
  ('b0000001-0000-4000-a000-0000002003d8', 'a0000001-0000-4000-a000-00000000002a', 'multiple_choice', '「賄う」의 의미로 올바른 것은?', '賄う(まかなう)는 ''충당하다, 조달하다''라는 뜻의 N1 동사입니다.', 1, 8, 'N1', 'vocab', true),
  ('b0000001-0000-4000-a000-0000002003d9', 'a0000001-0000-4000-a000-00000000002a', 'multiple_choice', '「催す」의 의미로 올바른 것은?', '催す(もよおす)는 ''개최하다, 최하다''라는 뜻의 N1 동사입니다.', 1, 9, 'N1', 'vocab', true),
  ('b0000001-0000-4000-a000-0000002003da', 'a0000001-0000-4000-a000-00000000002a', 'multiple_choice', '「赴く」의 의미로 올바른 것은?', '赴く(おもむく)는 ''향하다, 가다''라는 뜻의 N1 동사입니다.', 1, 10, 'N1', 'vocab', true),
  ('b0000001-0000-4000-a000-0000002003db', 'a0000001-0000-4000-a000-00000000002a', 'multiple_choice', '「企てる」의 의미로 올바른 것은?', '企てる(くわだてる)는 ''기획하다, 꾀하다''라는 뜻의 N1 동사입니다.', 1, 11, 'N1', 'vocab', true),
  ('b0000001-0000-4000-a000-0000002003dc', 'a0000001-0000-4000-a000-00000000002a', 'multiple_choice', '「偏る」의 의미로 올바른 것은?', '偏る(かたよる)는 ''치우치다, 편향되다''라는 뜻의 N1 동사입니다.', 1, 12, 'N1', 'vocab', true),
  ('b0000001-0000-4000-a000-0000002003dd', 'a0000001-0000-4000-a000-00000000002a', 'multiple_choice', '「怠る」의 의미로 올바른 것은?', '怠る(おこたる)는 ''게을리하다, 태만하다''라는 뜻의 N1 동사입니다.', 1, 13, 'N1', 'vocab', true),
  ('b0000001-0000-4000-a000-0000002003de', 'a0000001-0000-4000-a000-00000000002a', 'multiple_choice', '「募る」의 의미로 올바른 것은?', '募る(つのる)는 ''모집하다, 심해지다''라는 뜻의 N1 동사입니다.', 1, 14, 'N1', 'vocab', true),
  ('b0000001-0000-4000-a000-0000002003df', 'a0000001-0000-4000-a000-00000000002a', 'multiple_choice', '「兼ねる」의 의미로 올바른 것은?', '兼ねる(かねる)는 ''겸하다, ~하기 어렵다''라는 뜻의 N1 동사입니다.', 1, 15, 'N1', 'vocab', true),
  ('b0000001-0000-4000-a000-0000002003e0', 'a0000001-0000-4000-a000-00000000002a', 'multiple_choice', '「挑む」의 의미로 올바른 것은?', '挑む(いどむ)는 ''도전하다''라는 뜻의 N1 동사입니다.', 1, 16, 'N1', 'vocab', true),
  ('b0000001-0000-4000-a000-0000002003e1', 'a0000001-0000-4000-a000-00000000002a', 'multiple_choice', '「築く」의 의미로 올바른 것은?', '築く(きずく)는 ''쌓다, 구축하다''라는 뜻의 N1 동사입니다.', 1, 17, 'N1', 'vocab', true),
  ('b0000001-0000-4000-a000-0000002003e2', 'a0000001-0000-4000-a000-00000000002a', 'multiple_choice', '「滅びる」의 의미로 올바른 것은?', '滅びる(ほろびる)는 ''멸망하다''라는 뜻의 N1 동사입니다.', 1, 18, 'N1', 'vocab', true),
  ('b0000001-0000-4000-a000-0000002003e3', 'a0000001-0000-4000-a000-00000000002a', 'multiple_choice', '「抱える」의 의미로 올바른 것은?', '抱える(かかえる)는 ''안다, 떠안다''라는 뜻의 N1 동사입니다.', 1, 19, 'N1', 'vocab', true),
  ('b0000001-0000-4000-a000-0000002003e4', 'a0000001-0000-4000-a000-00000000002a', 'multiple_choice', '「惜しむ」의 의미로 올바른 것은?', '惜しむ(おしむ)는 ''아끼다, 아쉬워하다''라는 뜻의 N1 동사입니다.', 1, 20, 'N1', 'vocab', true),
  ('b0000001-0000-4000-a000-0000002003e5', 'a0000001-0000-4000-a000-00000000002a', 'multiple_choice', '「屈する」의 의미로 올바른 것은?', '屈する(くっする)는 ''굴하다, 굴복하다''라는 뜻의 N1 동사입니다.', 1, 21, 'N1', 'vocab', true),
  ('b0000001-0000-4000-a000-0000002003e6', 'a0000001-0000-4000-a000-00000000002a', 'multiple_choice', '「廃れる」의 의미로 올바른 것은?', '廃れる(すたれる)는 ''쇠퇴하다, 폐하다''라는 뜻의 N1 동사입니다.', 1, 22, 'N1', 'vocab', true),
  ('b0000001-0000-4000-a000-0000002003e7', 'a0000001-0000-4000-a000-00000000002a', 'multiple_choice', '「揺るぐ」의 의미로 올바른 것은?', '揺るぐ(ゆるぐ)는 ''흔들리다, 동요하다''라는 뜻의 N1 동사입니다.', 1, 23, 'N1', 'vocab', true),
  ('b0000001-0000-4000-a000-0000002003e8', 'a0000001-0000-4000-a000-00000000002a', 'multiple_choice', '「傾く」의 의미로 올바른 것은?', '傾く(かたむく)는 ''기울다, 쇠퇴하다''라는 뜻의 N1 동사입니다.', 1, 24, 'N1', 'vocab', true),
  ('b0000001-0000-4000-a000-0000002003e9', 'a0000001-0000-4000-a000-00000000002a', 'multiple_choice', '「悟る」의 의미로 올바른 것은?', '悟る(さとる)는 ''깨닫다, 각오하다''라는 뜻의 N1 동사입니다.', 1, 25, 'N1', 'vocab', true),
  ('b0000001-0000-4000-a000-0000002003ea', 'a0000001-0000-4000-a000-00000000002a', 'multiple_choice', '「潜む」의 의미로 올바른 것은?', '潜む(ひそむ)는 ''숨다, 잠복하다''라는 뜻의 N1 동사입니다.', 1, 26, 'N1', 'vocab', true),
  ('b0000001-0000-4000-a000-0000002003eb', 'a0000001-0000-4000-a000-00000000002a', 'multiple_choice', '「遮る」의 의미로 올바른 것은?', '遮る(さえぎる)는 ''가로막다, 차단하다''라는 뜻의 N1 동사입니다.', 1, 27, 'N1', 'vocab', true),
  ('b0000001-0000-4000-a000-0000002003ec', 'a0000001-0000-4000-a000-00000000002a', 'multiple_choice', '「紛れる」의 의미로 올바른 것은?', '紛れる(まぎれる)는 ''섞이다, 묻히다''라는 뜻의 N1 동사입니다.', 1, 28, 'N1', 'vocab', true),
  ('b0000001-0000-4000-a000-0000002003ed', 'a0000001-0000-4000-a000-00000000002a', 'multiple_choice', '「脅かす」의 의미로 올바른 것은?', '脅かす(おびやかす)는 ''위협하다''라는 뜻의 N1 동사입니다.', 1, 29, 'N1', 'vocab', true),
  ('b0000001-0000-4000-a000-0000002003ee', 'a0000001-0000-4000-a000-00000000002a', 'multiple_choice', '「唱える」의 의미로 올바른 것은?', '唱える(となえる)는 ''주창하다, 외치다''라는 뜻의 N1 동사입니다.', 1, 30, 'N1', 'vocab', true),
  ('b0000001-0000-4000-a000-0000002003ef', 'a0000001-0000-4000-a000-00000000002a', 'multiple_choice', '「漂う」의 의미로 올바른 것은?', '漂う(ただよう)는 ''떠돌다, 감돌다''라는 뜻의 N1 동사입니다.', 1, 31, 'N1', 'vocab', true),
  ('b0000001-0000-4000-a000-0000002003f0', 'a0000001-0000-4000-a000-00000000002a', 'multiple_choice', '「滞る」의 의미로 올바른 것은?', '滞る(とどこおる)는 ''정체되다, 지체되다''라는 뜻의 N1 동사입니다.', 1, 32, 'N1', 'vocab', true),
  ('b0000001-0000-4000-a000-0000002003f1', 'a0000001-0000-4000-a000-00000000002a', 'multiple_choice', '「慕う」의 의미로 올바른 것은?', '慕う(したう)는 ''사모하다, 따르다''라는 뜻의 N1 동사입니다.', 1, 33, 'N1', 'vocab', true),
