INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES
  ('b0000001-0000-4000-a000-0000002003fe', 'a0000001-0000-4000-a000-00000000002b', 'multiple_choice', '「著しい」의 의미로 올바른 것은?', '著しい(いちじるしい)는 ''현저하다, 두드러지다''라는 뜻의 N1 い형용사입니다.', 1, 1, 'N1', 'vocab', true),
  ('b0000001-0000-4000-a000-0000002003ff', 'a0000001-0000-4000-a000-00000000002b', 'multiple_choice', '「怪しい」의 의미로 올바른 것은?', '怪しい(あやしい)는 ''수상하다, 의심스럽다''라는 뜻의 N1 い형용사입니다.', 1, 2, 'N1', 'vocab', true),
  ('b0000001-0000-4000-a000-000000200400', 'a0000001-0000-4000-a000-00000000002b', 'multiple_choice', '「乏しい」의 의미로 올바른 것은?', '乏しい(とぼしい)는 ''부족하다, 빈약하다''라는 뜻의 N1 い형용사입니다.', 1, 3, 'N1', 'vocab', true),
  ('b0000001-0000-4000-a000-000000200401', 'a0000001-0000-4000-a000-00000000002b', 'multiple_choice', '「煩わしい」의 의미로 올바른 것은?', '煩わしい(わずらわしい)는 ''번거롭다, 귀찮다''라는 뜻의 N1 い형용사입니다.', 1, 4, 'N1', 'vocab', true),
  ('b0000001-0000-4000-a000-000000200402', 'a0000001-0000-4000-a000-00000000002b', 'multiple_choice', '「空しい」의 의미로 올바른 것은?', '空しい(むなしい)는 ''허무하다, 공허하다''라는 뜻의 N1 い형용사입니다.', 1, 5, 'N1', 'vocab', true),
  ('b0000001-0000-4000-a000-000000200403', 'a0000001-0000-4000-a000-00000000002b', 'multiple_choice', '「慌ただしい」의 의미로 올바른 것은?', '慌ただしい(あわただしい)는 ''분주하다, 바쁘다''라는 뜻의 N1 い형용사입니다.', 1, 6, 'N1', 'vocab', true),
  ('b0000001-0000-4000-a000-000000200404', 'a0000001-0000-4000-a000-00000000002b', 'multiple_choice', '「快い」의 의미로 올바른 것은?', '快い(こころよい)는 ''기분 좋다, 쾌적하다''라는 뜻의 N1 い형용사입니다.', 1, 7, 'N1', 'vocab', true),
  ('b0000001-0000-4000-a000-000000200405', 'a0000001-0000-4000-a000-00000000002b', 'multiple_choice', '「潔い」의 의미로 올바른 것은?', '潔い(いさぎよい)는 ''깨끗하다, 결백하다''라는 뜻의 N1 い형용사입니다.', 1, 8, 'N1', 'vocab', true),
  ('b0000001-0000-4000-a000-000000200406', 'a0000001-0000-4000-a000-00000000002b', 'multiple_choice', '「逞しい」의 의미로 올바른 것은?', '逞しい(たくましい)는 ''듬직하다, 건장하다''라는 뜻의 N1 い형용사입니다.', 1, 9, 'N1', 'vocab', true),
  ('b0000001-0000-4000-a000-000000200407', 'a0000001-0000-4000-a000-00000000002b', 'multiple_choice', '「勿体ない」의 의미로 올바른 것은?', '勿体ない(もったいない)는 ''아깝다, 과분하다''라는 뜻의 N1 い형용사입니다.', 1, 10, 'N1', 'vocab', true),
  ('b0000001-0000-4000-a000-000000200408', 'a0000001-0000-4000-a000-00000000002b', 'multiple_choice', '「図々しい」의 의미로 올바른 것은?', '図々しい(ずうずうしい)는 ''뻔뻔하다, 염치없다''라는 뜻의 N1 い형용사입니다.', 1, 11, 'N1', 'vocab', true),
  ('b0000001-0000-4000-a000-000000200409', 'a0000001-0000-4000-a000-00000000002b', 'multiple_choice', '「忌まわしい」의 의미로 올바른 것은?', '忌まわしい(いまわしい)는 ''불길하다, 꺼림칙하다''라는 뜻의 N1 い형용사입니다.', 1, 12, 'N1', 'vocab', true),
  ('b0000001-0000-4000-a000-00000020040a', 'a0000001-0000-4000-a000-00000000002b', 'multiple_choice', '「目まぐるしい」의 의미로 올바른 것은?', '目まぐるしい(めまぐるしい)는 ''눈이 돌 정도로 바쁘다''라는 뜻의 N1 い형용사입니다.', 1, 13, 'N1', 'vocab', true),
  ('b0000001-0000-4000-a000-00000020040b', 'a0000001-0000-4000-a000-00000000002b', 'multiple_choice', '「厚かましい」의 의미로 올바른 것은?', '厚かましい(あつかましい)는 ''뻔뻔하다, 후안무치하다''라는 뜻의 N1 い형용사입니다.', 1, 14, 'N1', 'vocab', true),
  ('b0000001-0000-4000-a000-00000020040c', 'a0000001-0000-4000-a000-00000000002b', 'multiple_choice', '「儚い」의 의미로 올바른 것은?', '儚い(はかない)는 ''덧없다, 허무하다''라는 뜻의 N1 い형용사입니다.', 1, 15, 'N1', 'vocab', true),
  ('b0000001-0000-4000-a000-00000020040d', 'a0000001-0000-4000-a000-00000000002b', 'multiple_choice', '「稀」의 의미로 올바른 것은?', '稀(まれ)는 ''드물다, 희귀하다''라는 뜻의 N1 な형용사입니다.', 1, 16, 'N1', 'vocab', true),
  ('b0000001-0000-4000-a000-00000020040e', 'a0000001-0000-4000-a000-00000000002b', 'multiple_choice', '「膨大」의 의미로 올바른 것은?', '膨大(ぼうだい)는 ''방대하다, 팽대하다''라는 뜻의 N1 な형용사입니다.', 1, 17, 'N1', 'vocab', true),
  ('b0000001-0000-4000-a000-00000020040f', 'a0000001-0000-4000-a000-00000000002b', 'multiple_choice', '「壮大」의 의미로 올바른 것은?', '壮大(そうだい)는 ''장대하다, 웅장하다''라는 뜻의 N1 な형용사입니다.', 1, 18, 'N1', 'vocab', true),
  ('b0000001-0000-4000-a000-000000200410', 'a0000001-0000-4000-a000-00000000002b', 'multiple_choice', '「崇高」의 의미로 올바른 것은?', '崇高(すうこう)는 ''숭고하다''라는 뜻의 N1 な형용사입니다.', 1, 19, 'N1', 'vocab', true),
  ('b0000001-0000-4000-a000-000000200411', 'a0000001-0000-4000-a000-00000000002b', 'multiple_choice', '「卑怯」의 의미로 올바른 것은?', '卑怯(ひきょう)는 ''비겁하다''라는 뜻의 N1 な형용사입니다.', 1, 20, 'N1', 'vocab', true),
  ('b0000001-0000-4000-a000-000000200412', 'a0000001-0000-4000-a000-00000000002b', 'multiple_choice', '「巧妙」의 의미로 올바른 것은?', '巧妙(こうみょう)는 ''교묘하다, 정교하다''라는 뜻의 N1 な형용사입니다.', 1, 21, 'N1', 'vocab', true),
  ('b0000001-0000-4000-a000-000000200413', 'a0000001-0000-4000-a000-00000000002b', 'multiple_choice', '「対等」의 의미로 올바른 것은?', '対等(たいとう)는 ''대등하다, 동등하다''라는 뜻의 N1 な형용사입니다.', 1, 22, 'N1', 'vocab', true),
  ('b0000001-0000-4000-a000-000000200414', 'a0000001-0000-4000-a000-00000000002b', 'multiple_choice', '「安易」의 의미로 올바른 것은?', '安易(あんい)는 ''안이하다, 손쉽다''라는 뜻의 N1 な형용사입니다.', 1, 23, 'N1', 'vocab', true),
  ('b0000001-0000-4000-a000-000000200415', 'a0000001-0000-4000-a000-00000000002b', 'multiple_choice', '「曖昧」의 의미로 올바른 것은?', '曖昧(あいまい)는 ''애매하다, 모호하다''라는 뜻의 N1 な형용사입니다.', 1, 24, 'N1', 'vocab', true),
  ('b0000001-0000-4000-a000-000000200416', 'a0000001-0000-4000-a000-00000000002b', 'multiple_choice', '「強引」의 의미로 올바른 것은?', '強引(ごういん)는 ''억지스럽다, 강압적이다''라는 뜻의 N1 な형용사입니다.', 1, 25, 'N1', 'vocab', true),
  ('b0000001-0000-4000-a000-000000200417', 'a0000001-0000-4000-a000-00000000002b', 'multiple_choice', '「概念」의 의미로 올바른 것은?', '概念(がいねん)는 ''개념''라는 뜻의 N1 명사입니다.', 1, 26, 'N1', 'vocab', true),
  ('b0000001-0000-4000-a000-000000200418', 'a0000001-0000-4000-a000-00000000002b', 'multiple_choice', '「理念」의 의미로 올바른 것은?', '理念(りねん)는 ''이념, 신념''라는 뜻의 N1 명사입니다.', 1, 27, 'N1', 'vocab', true),
  ('b0000001-0000-4000-a000-000000200419', 'a0000001-0000-4000-a000-00000000002b', 'multiple_choice', '「信念」의 의미로 올바른 것은?', '信念(しんねん)는 ''신념''라는 뜻의 N1 명사입니다.', 1, 28, 'N1', 'vocab', true),
  ('b0000001-0000-4000-a000-00000020041a', 'a0000001-0000-4000-a000-00000000002b', 'multiple_choice', '「体制」의 의미로 올바른 것은?', '体制(たいせい)는 ''체제''라는 뜻의 N1 명사입니다.', 1, 29, 'N1', 'vocab', true),
  ('b0000001-0000-4000-a000-00000020041b', 'a0000001-0000-4000-a000-00000000002b', 'multiple_choice', '「制度」의 의미로 올바른 것은?', '制度(せいど)는 ''제도''라는 뜻의 N1 명사입니다.', 1, 30, 'N1', 'vocab', true),
  ('b0000001-0000-4000-a000-00000020041c', 'a0000001-0000-4000-a000-00000000002b', 'multiple_choice', '「仕組み」의 의미로 올바른 것은?', '仕組み(しくみ)는 ''구조, 시스템''라는 뜻의 N1 명사입니다.', 1, 31, 'N1', 'vocab', true),
  ('b0000001-0000-4000-a000-00000020041d', 'a0000001-0000-4000-a000-00000000002b', 'multiple_choice', '「推移」의 의미로 올바른 것은?', '推移(すいい)는 ''추이, 변천''라는 뜻의 N1 명사입니다.', 1, 32, 'N1', 'vocab', true),
  ('b0000001-0000-4000-a000-00000020041e', 'a0000001-0000-4000-a000-00000000002b', 'multiple_choice', '「動向」의 의미로 올바른 것은?', '動向(どうこう)는 ''동향''라는 뜻의 N1 명사입니다.', 1, 33, 'N1', 'vocab', true),
  ('b0000001-0000-4000-a000-00000020041f', 'a0000001-0000-4000-a000-00000000002b', 'multiple_choice', '「実態」의 의미로 올바른 것은?', '実態(じったい)는 ''실태''라는 뜻의 N1 명사입니다.', 1, 34, 'N1', 'vocab', true),
  ('b0000001-0000-4000-a000-000000200420', 'a0000001-0000-4000-a000-00000000002b', 'multiple_choice', '「見解」의 의미로 올바른 것은?', '見解(けんかい)는 ''견해''라는 뜻의 N1 명사입니다.', 1, 35, 'N1', 'vocab', true),
  ('b0000001-0000-4000-a000-000000200421', 'a0000001-0000-4000-a000-00000000002b', 'multiple_choice', '「趣旨」의 의미로 올바른 것은?', '趣旨(しゅし)는 ''취지''라는 뜻의 N1 명사입니다.', 1, 36, 'N1', 'vocab', true),
  ('b0000001-0000-4000-a000-000000200422', 'a0000001-0000-4000-a000-00000000002b', 'multiple_choice', '「要旨」의 의미로 올바른 것은?', '要旨(ようし)는 ''요지, 요약''라는 뜻의 N1 명사입니다.', 1, 37, 'N1', 'vocab', true),
  ('b0000001-0000-4000-a000-000000200423', 'a0000001-0000-4000-a000-00000000002b', 'multiple_choice', '「概要」의 의미로 올바른 것은?', '概要(がいよう)는 ''개요''라는 뜻의 N1 명사입니다.', 1, 38, 'N1', 'vocab', true),
  ('b0000001-0000-4000-a000-000000200424', 'a0000001-0000-4000-a000-00000000002b', 'multiple_choice', '「論点」의 의미로 올바른 것은?', '論点(ろんてん)는 ''논점''라는 뜻의 N1 명사입니다.', 1, 39, 'N1', 'vocab', true),
  ('b0000001-0000-4000-a000-000000200425', 'a0000001-0000-4000-a000-00000000002b', 'multiple_choice', '「根拠」의 의미로 올바른 것은?', '根拠(こんきょ)는 ''근거''라는 뜻의 N1 명사입니다.', 1, 40, 'N1', 'vocab', true),
  ('b0000001-0000-4000-a000-000000200426', 'a0000001-0000-4000-a000-00000000002b', 'multiple_choice', '「前提」의 의미로 올바른 것은?', '前提(ぜんてい)는 ''전제''라는 뜻의 N1 명사입니다.', 1, 41, 'N1', 'vocab', true),
  ('b0000001-0000-4000-a000-000000200427', 'a0000001-0000-4000-a000-00000000002b', 'multiple_choice', '「矛盾」의 의미로 올바른 것은?', '矛盾(むじゅん)는 ''모순''라는 뜻의 N1 명사입니다.', 1, 42, 'N1', 'vocab', true),
  ('b0000001-0000-4000-a000-000000200428', 'a0000001-0000-4000-a000-00000000002b', 'multiple_choice', '「偏見」의 의미로 올바른 것은?', '偏見(へんけん)는 ''편견''라는 뜻의 N1 명사입니다.', 1, 43, 'N1', 'vocab', true),
  ('b0000001-0000-4000-a000-000000200429', 'a0000001-0000-4000-a000-00000000002b', 'multiple_choice', '「素質」의 의미로 올바른 것은?', '素質(そしつ)는 ''소질, 자질''라는 뜻의 N1 명사입니다.', 1, 44, 'N1', 'vocab', true),
  ('b0000001-0000-4000-a000-00000020042a', 'a0000001-0000-4000-a000-00000000002b', 'multiple_choice', '「素養」의 의미로 올바른 것은?', '素養(そよう)는 ''소양, 교양''라는 뜻의 N1 명사입니다.', 1, 45, 'N1', 'vocab', true);

