  ('b0000001-0000-4000-a000-00000020042b', 'a0000001-0000-4000-a000-00000000002c', 'multiple_choice', '「功績」의 의미로 올바른 것은?', '功績(こうせき)는 ''공적, 업적''라는 뜻의 N1 명사입니다.', 1, 1, 'N1', 'vocab', true),
  ('b0000001-0000-4000-a000-00000020042c', 'a0000001-0000-4000-a000-00000000002c', 'multiple_choice', '「威厳」의 의미로 올바른 것은?', '威厳(いげん)는 ''위엄''라는 뜻의 N1 명사입니다.', 1, 2, 'N1', 'vocab', true),
  ('b0000001-0000-4000-a000-00000020042d', 'a0000001-0000-4000-a000-00000000002c', 'multiple_choice', '「志」의 의미로 올바른 것은?', '志(こころざし)는 ''뜻, 포부''라는 뜻의 N1 명사입니다.', 1, 3, 'N1', 'vocab', true),
  ('b0000001-0000-4000-a000-00000020042e', 'a0000001-0000-4000-a000-00000000002c', 'multiple_choice', '「思惑」의 의미로 올바른 것은?', '思惑(おもわく)는 ''속셈, 의도''라는 뜻의 N1 명사입니다.', 1, 4, 'N1', 'vocab', true),
  ('b0000001-0000-4000-a000-00000020042f', 'a0000001-0000-4000-a000-00000000002c', 'multiple_choice', '「手腕」의 의미로 올바른 것은?', '手腕(しゅわん)는 ''수완, 역량''라는 뜻의 N1 명사입니다.', 1, 5, 'N1', 'vocab', true),
  ('b0000001-0000-4000-a000-000000200430', 'a0000001-0000-4000-a000-00000000002c', 'multiple_choice', '「境遇」의 의미로 올바른 것은?', '境遇(きょうぐう)는 ''처지, 경우''라는 뜻의 N1 명사입니다.', 1, 6, 'N1', 'vocab', true),
