  ('b0000001-0000-4000-a000-000000200433', 'a0000001-0000-4000-a000-00000000002c', 'multiple_choice', '「水準」의 의미로 올바른 것은?', '水準(すいじゅん)는 ''수준''라는 뜻의 N1 명사입니다.', 1, 9, 'N1', 'vocab', true),
  ('b0000001-0000-4000-a000-000000200434', 'a0000001-0000-4000-a000-00000000002c', 'multiple_choice', '「格差」의 의미로 올바른 것은?', '格差(かくさ)는 ''격차''라는 뜻의 N1 명사입니다.', 1, 10, 'N1', 'vocab', true),
