  ('b0000001-0000-4000-a000-000000200438', 'a0000001-0000-4000-a000-00000000002c', 'multiple_choice', '「一連」의 의미로 올바른 것은?', '一連(いちれん)는 ''일련''라는 뜻의 N1 명사입니다.', 1, 14, 'N1', 'vocab', true),
