-- N1 語彙テスト 第6回 (45 questions)
INSERT INTO quiz_questions (id, quiz_id, question_type, question_text, explanation, points, sort_order, difficulty, question_category, is_published) VALUES
  ('b0000001-0000-4000-a000-000000200458', 'a0000001-0000-4000-a000-00000000002d', 'multiple_choice', '「遂行」의 의미로 올바른 것은?', '遂行(すいこう)는 ''수행''라는 뜻의 N1 명사입니다.', 1, 1, 'N1', 'vocab', true),
  ('b0000001-0000-4000-a000-000000200459', 'a0000001-0000-4000-a000-00000000002d', 'multiple_choice', '「普及」의 의미로 올바른 것은?', '普及(ふきゅう)는 ''보급''라는 뜻의 N1 명사입니다.', 1, 2, 'N1', 'vocab', true),
  ('b0000001-0000-4000-a000-00000020045a', 'a0000001-0000-4000-a000-00000000002d', 'multiple_choice', '「是正」의 의미로 올바른 것은?', '是正(ぜせい)는 ''시정''라는 뜻의 N1 명사입니다.', 1, 3, 'N1', 'vocab', true),
  ('b0000001-0000-4000-a000-00000020045b', 'a0000001-0000-4000-a000-00000000002d', 'multiple_choice', '「促進」의 의미로 올바른 것은?', '促進(そくしん)는 ''촉진''라는 뜻의 N1 명사입니다.', 1, 4, 'N1', 'vocab', true),
  ('b0000001-0000-4000-a000-00000020045c', 'a0000001-0000-4000-a000-00000000002d', 'multiple_choice', '「抑制」의 의미로 올바른 것은?', '抑制(よくせい)는 ''억제''라는 뜻의 N1 명사입니다.', 1, 5, 'N1', 'vocab', true),
  ('b0000001-0000-4000-a000-00000020045d', 'a0000001-0000-4000-a000-00000000002d', 'multiple_choice', '「辛うじて」의 의미로 올바른 것은?', '辛うじて(かろうじて)는 ''가까스로, 간신히''라는 뜻의 N1 부사입니다.', 1, 6, 'N1', 'vocab', true),
  ('b0000001-0000-4000-a000-00000020045e', 'a0000001-0000-4000-a000-00000000002d', 'multiple_choice', '「概して」의 의미로 올바른 것은?', '概して(がいして)는 ''대체로, 전반적으로''라는 뜻의 N1 부사입니다.', 1, 7, 'N1', 'vocab', true),
  ('b0000001-0000-4000-a000-00000020045f', 'a0000001-0000-4000-a000-00000000002d', 'multiple_choice', '「強いて」의 의미로 올바른 것은?', '強いて(しいて)는 ''굳이, 억지로''라는 뜻의 N1 부사입니다.', 1, 8, 'N1', 'vocab', true),
  ('b0000001-0000-4000-a000-000000200460', 'a0000001-0000-4000-a000-00000000002d', 'multiple_choice', '「敢えて」의 의미로 올바른 것은?', '敢えて(あえて)는 ''감히, 일부러''라는 뜻의 N1 부사입니다.', 1, 9, 'N1', 'vocab', true),
  ('b0000001-0000-4000-a000-000000200461', 'a0000001-0000-4000-a000-00000000002d', 'multiple_choice', '「ひたすら」의 의미로 올바른 것은?', 'ひたすら(ひたすら)는 ''오로지, 열심히''라는 뜻의 N1 부사입니다.', 1, 10, 'N1', 'vocab', true),
  ('b0000001-0000-4000-a000-000000200462', 'a0000001-0000-4000-a000-00000000002d', 'multiple_choice', '「自ずと」의 의미로 올바른 것은?', '自ずと(おのずと)는 ''자연히, 저절로''라는 뜻의 N1 부사입니다.', 1, 11, 'N1', 'vocab', true),
  ('b0000001-0000-4000-a000-000000200463', 'a0000001-0000-4000-a000-00000000002d', 'multiple_choice', '「とりわけ」의 의미로 올바른 것은?', 'とりわけ(とりわけ)는 ''특히, 그 중에서도''라는 뜻의 N1 부사입니다.', 1, 12, 'N1', 'vocab', true),
  ('b0000001-0000-4000-a000-000000200464', 'a0000001-0000-4000-a000-00000000002d', 'multiple_choice', '「もっぱら」의 의미로 올바른 것은?', 'もっぱら(もっぱら)는 ''오로지, 전적으로''라는 뜻의 N1 부사입니다.', 1, 13, 'N1', 'vocab', true),
  ('b0000001-0000-4000-a000-000000200465', 'a0000001-0000-4000-a000-00000000002d', 'multiple_choice', '「ことごとく」의 의미로 올바른 것은?', 'ことごとく(ことごとく)는 ''모조리, 남김없이''라는 뜻의 N1 부사입니다.', 1, 14, 'N1', 'vocab', true),
  ('b0000001-0000-4000-a000-000000200466', 'a0000001-0000-4000-a000-00000000002d', 'multiple_choice', '「到底」의 의미로 올바른 것은?', '到底(とうてい)는 ''도저히''라는 뜻의 N1 부사입니다.', 1, 15, 'N1', 'vocab', true),
  ('b0000001-0000-4000-a000-000000200467', 'a0000001-0000-4000-a000-00000000002d', 'multiple_choice', '「一概に」의 의미로 올바른 것은?', '一概に(いちがいに)는 ''일률적으로, 한마디로''라는 뜻의 N1 부사입니다.', 1, 16, 'N1', 'vocab', true),
  ('b0000001-0000-4000-a000-000000200468', 'a0000001-0000-4000-a000-00000000002d', 'multiple_choice', '「一挙に」의 의미로 올바른 것은?', '一挙に(いっきょに)는 ''한꺼번에, 단번에''라는 뜻의 N1 부사입니다.', 1, 17, 'N1', 'vocab', true),
  ('b0000001-0000-4000-a000-000000200469', 'a0000001-0000-4000-a000-00000000002d', 'multiple_choice', '「一律に」의 의미로 올바른 것은?', '一律に(いちりつに)는 ''일률적으로, 일괄적으로''라는 뜻의 N1 부사입니다.', 1, 18, 'N1', 'vocab', true),
  ('b0000001-0000-4000-a000-00000020046a', 'a0000001-0000-4000-a000-00000000002d', 'multiple_choice', '「徐々に」의 의미로 올바른 것은?', '徐々に(じょじょに)는 ''서서히, 점차''라는 뜻의 N1 부사입니다.', 1, 19, 'N1', 'vocab', true),
  ('b0000001-0000-4000-a000-00000020046b', 'a0000001-0000-4000-a000-00000000002d', 'multiple_choice', '「大いに」의 의미로 올바른 것은?', '大いに(おおいに)는 ''크게, 매우''라는 뜻의 N1 부사입니다.', 1, 20, 'N1', 'vocab', true),
  ('b0000001-0000-4000-a000-00000020046c', 'a0000001-0000-4000-a000-00000000002d', 'multiple_choice', '「極めて」의 의미로 올바른 것은?', '極めて(きわめて)는 ''극히, 매우''라는 뜻의 N1 부사입니다.', 1, 21, 'N1', 'vocab', true),
  ('b0000001-0000-4000-a000-00000020046d', 'a0000001-0000-4000-a000-00000000002d', 'multiple_choice', '「遥かに」의 의미로 올바른 것은?', '遥かに(はるかに)는 ''훨씬''라는 뜻의 N1 부사입니다.', 1, 22, 'N1', 'vocab', true),
  ('b0000001-0000-4000-a000-00000020046e', 'a0000001-0000-4000-a000-00000000002d', 'multiple_choice', '「断じて」의 의미로 올바른 것은?', '断じて(だんじて)는 ''단연코, 결코''라는 뜻의 N1 부사입니다.', 1, 23, 'N1', 'vocab', true),
  ('b0000001-0000-4000-a000-00000020046f', 'a0000001-0000-4000-a000-00000000002d', 'multiple_choice', '「やむを得ず」의 의미로 올바른 것은?', 'やむを得ず(やむをえず)는 ''어쩔 수 없이, 부득이''라는 뜻의 N1 부사입니다.', 1, 24, 'N1', 'vocab', true),
  ('b0000001-0000-4000-a000-000000200470', 'a0000001-0000-4000-a000-00000000002d', 'multiple_choice', '「ろくに」의 의미로 올바른 것은?', 'ろくに(ろくに)는 ''제대로, 변변히''라는 뜻의 N1 부사입니다.', 1, 25, 'N1', 'vocab', true),
  ('b0000001-0000-4000-a000-000000200471', 'a0000001-0000-4000-a000-00000000002d', 'multiple_choice', '「何気なく」의 의미로 올바른 것은?', '何気なく(なにげなく)는 ''무심코, 아무렇지 않게''라는 뜻의 N1 부사입니다.', 1, 26, 'N1', 'vocab', true),
  ('b0000001-0000-4000-a000-000000200472', 'a0000001-0000-4000-a000-00000000002d', 'multiple_choice', '「いかにも」의 의미로 올바른 것은?', 'いかにも(いかにも)는 ''아무래도, 정말로''라는 뜻의 N1 부사입니다.', 1, 27, 'N1', 'vocab', true),
  ('b0000001-0000-4000-a000-000000200473', 'a0000001-0000-4000-a000-00000000002d', 'multiple_choice', '「むやみに」의 의미로 올바른 것은?', 'むやみに(むやみに)는 ''함부로, 무턱대고''라는 뜻의 N1 부사입니다.', 1, 28, 'N1', 'vocab', true),
  ('b0000001-0000-4000-a000-000000200474', 'a0000001-0000-4000-a000-00000000002d', 'multiple_choice', '「一向に」의 의미로 올바른 것은?', '一向に(いっこうに)는 ''전혀, 조금도''라는 뜻의 N1 부사입니다.', 1, 29, 'N1', 'vocab', true),
  ('b0000001-0000-4000-a000-000000200475', 'a0000001-0000-4000-a000-00000000002d', 'multiple_choice', '「直ちに」의 의미로 올바른 것은?', '直ちに(ただちに)는 ''즉시, 곧바로''라는 뜻의 N1 부사입니다.', 1, 30, 'N1', 'vocab', true),
  ('b0000001-0000-4000-a000-000000200476', 'a0000001-0000-4000-a000-00000000002d', 'multiple_choice', '「予め」의 의미로 올바른 것은?', '予め(あらかじめ)는 ''미리, 사전에''라는 뜻의 N1 부사입니다.', 1, 31, 'N1', 'vocab', true),
  ('b0000001-0000-4000-a000-000000200477', 'a0000001-0000-4000-a000-00000000002d', 'multiple_choice', '「速やかに」의 의미로 올바른 것은?', '速やかに(すみやかに)는 ''신속하게, 즉각''라는 뜻의 N1 부사입니다.', 1, 32, 'N1', 'vocab', true),
  ('b0000001-0000-4000-a000-000000200478', 'a0000001-0000-4000-a000-00000000002d', 'multiple_choice', '「絶えず」의 의미로 올바른 것은?', '絶えず(たえず)는 ''끊임없이''라는 뜻의 N1 부사입니다.', 1, 33, 'N1', 'vocab', true),
  ('b0000001-0000-4000-a000-000000200479', 'a0000001-0000-4000-a000-00000000002d', 'multiple_choice', '「未だに」의 의미로 올바른 것은?', '未だに(いまだに)는 ''아직도, 여전히''라는 뜻의 N1 부사입니다.', 1, 34, 'N1', 'vocab', true),
  ('b0000001-0000-4000-a000-00000020047a', 'a0000001-0000-4000-a000-00000000002d', 'multiple_choice', '「依然として」의 의미로 올바른 것은?', '依然として(いぜんとして)는 ''여전히, 변함없이''라는 뜻의 N1 부사입니다.', 1, 35, 'N1', 'vocab', true),
  ('b0000001-0000-4000-a000-00000020047b', 'a0000001-0000-4000-a000-00000000002d', 'multiple_choice', '「元来」의 의미로 올바른 것은?', '元来(がんらい)는 ''원래, 본래''라는 뜻의 N1 부사입니다.', 1, 36, 'N1', 'vocab', true),
  ('b0000001-0000-4000-a000-00000020047c', 'a0000001-0000-4000-a000-00000000002d', 'multiple_choice', '「所詮」의 의미로 올바른 것은?', '所詮(しょせん)는 ''결국, 소용없다''라는 뜻의 N1 부사입니다.', 1, 37, 'N1', 'vocab', true),
  ('b0000001-0000-4000-a000-00000020047d', 'a0000001-0000-4000-a000-00000000002d', 'multiple_choice', '「漸く」의 의미로 올바른 것은?', '漸く(ようやく)는 ''겨우, 드디어''라는 뜻의 N1 부사입니다.', 1, 38, 'N1', 'vocab', true),
  ('b0000001-0000-4000-a000-00000020047e', 'a0000001-0000-4000-a000-00000000002d', 'multiple_choice', '「すなわち」의 의미로 올바른 것은?', 'すなわち(すなわち)는 ''즉, 다시 말하면''라는 뜻의 N1 접속사입니다.', 1, 39, 'N1', 'vocab', true),
  ('b0000001-0000-4000-a000-00000020047f', 'a0000001-0000-4000-a000-00000000002d', 'multiple_choice', '「なおかつ」의 의미로 올바른 것은?', 'なおかつ(なおかつ)는 ''게다가, 더군다나''라는 뜻의 N1 접속사입니다.', 1, 40, 'N1', 'vocab', true),
  ('b0000001-0000-4000-a000-000000200480', 'a0000001-0000-4000-a000-00000000002d', 'multiple_choice', '「ただし」의 의미로 올바른 것은?', 'ただし(ただし)는 ''단, 다만''라는 뜻의 N1 접속사입니다.', 1, 41, 'N1', 'vocab', true),
  ('b0000001-0000-4000-a000-000000200481', 'a0000001-0000-4000-a000-00000000002d', 'multiple_choice', '「～に即して」의 의미로 올바른 것은?', '～に即して(にそくして)는 ''~에 입각하여''라는 뜻의 N1 표현입니다.', 1, 42, 'N1', 'vocab', true),
  ('b0000001-0000-4000-a000-000000200482', 'a0000001-0000-4000-a000-00000000002d', 'multiple_choice', '「～を踏まえて」의 의미로 올바른 것은?', '～を踏まえて(をふまえて)는 ''~을 근거로, ~에 기반하여''라는 뜻의 N1 표현입니다.', 1, 43, 'N1', 'vocab', true),
  ('b0000001-0000-4000-a000-000000200483', 'a0000001-0000-4000-a000-00000000002d', 'multiple_choice', '「～に先立って」의 의미로 올바른 것은?', '～に先立って(にさきだって)는 ''~에 앞서''라는 뜻의 N1 표현입니다.', 1, 44, 'N1', 'vocab', true),
  ('b0000001-0000-4000-a000-000000200484', 'a0000001-0000-4000-a000-00000000002d', 'multiple_choice', '「～をもって」의 의미로 올바른 것은?', '～をもって(をもって)는 ''~으로써, ~을 가지고''라는 뜻의 N1 표현입니다.', 1, 45, 'N1', 'vocab', true);

